CREATE OR ALTER VIEW [dbo].[QueryParamsNow] AS
-- the parameters of this Access process (modQueryParams), else those of a parameter not set
SELECT COALESCE(p.[PeriodStart], CAST('18991230' AS DATETIME)) AS [qp_PeriodStart],
    COALESCE(p.[PeriodEnd], CAST('18991230' AS DATETIME)) AS [qp_PeriodEnd],
    COALESCE(p.[ProductID], 0) AS [qp_ProductID],
    COALESCE(p.[WarehouseID], 0) AS [qp_WarehouseID],
    COALESCE(p.[CustomerID], 0) AS [qp_CustomerID],
    COALESCE(p.[SupplierID], 0) AS [qp_SupplierID],
    COALESCE(p.[VatReturnID], 0) AS [qp_VatReturnID],
    COALESCE(p.[DashDay], CAST('18991230' AS DATETIME)) AS [qp_DashDay],
    COALESCE(p.[DashEnd], CAST('18991230' AS DATETIME)) AS [qp_DashEnd],
    COALESCE(p.[DashMonth], CAST('18991230' AS DATETIME)) AS [qp_DashMonth],
    COALESCE(p.[CommissionRunID], 0) AS [qp_CommissionRunID],
    COALESCE(p.[IndMonth], CAST('18991230' AS DATETIME)) AS [qp_IndMonth],
    COALESCE(p.[IndEnd], CAST('18991230' AS DATETIME)) AS [qp_IndEnd],
    COALESCE(p.[IndPrevMonth], CAST('18991230' AS DATETIME)) AS [qp_IndPrevMonth],
    COALESCE(p.[IndYear], CAST('18991230' AS DATETIME)) AS [qp_IndYear],
    COALESCE(p.[Ind90], CAST('18991230' AS DATETIME)) AS [qp_Ind90],
    COALESCE(p.[CashBoxID], 0) AS [qp_CashBoxID],
    COALESCE(p.[PayrollRunID], 0) AS [qp_PayrollRunID],
    COALESCE(p.[AccountCode], 0) AS [qp_AccountCode],
    COALESCE(p.[CompareStart], CAST('18991230' AS DATETIME)) AS [qp_CompareStart],
    COALESCE(p.[CompareEnd], CAST('18991230' AS DATETIME)) AS [qp_CompareEnd]
FROM (SELECT 1 AS One) AS o LEFT JOIN [dbo].[QueryParams] AS p
    ON p.HostName = HOST_NAME() AND p.HostProcess = HOST_ID();
GO
