UNION ALL
SELECT 7, N'الواردات من السلع (المسددة ضريبتها في الجمارك)', CAST(0 AS MONEY), CAST(0 AS MONEY), CAST(0 AS MONEY), N'L', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [dbo].[qryVatReturnHead] AS v
UNION ALL
SELECT 8, N'الخدمات المستوردة من الخارج', CAST(0 AS MONEY), CAST(0 AS MONEY), CAST(0 AS MONEY), N'L', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
