SELECT 9, N'المشتريات المعفاة وغير الخاضعة', v.PurchZeroAmount, v.PurchZeroAdjust, CAST(0 AS MONEY), N'L', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
