SELECT 11, N'ضريبة المبيعات ناقص الضريبة القابلة للخصم عن الشهر', Null, Null, v.SalesStdVAT - v.PurchStdVAT, N'N', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
