UNION ALL
SELECT 12, N'تسويات وتصحيحات من الفترات السابقة', Null, Null, v.Corrections, N'N', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
