SELECT 13, N'الرصيد الدائن المرحَّل من الشهر السابق', Null, Null, v.CarriedCredit, N'N', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
