CREATE OR ALTER VIEW [dbo].[IntegrityCheckQuery] AS
-- فحص سلامة البيانات: أي سطر هنا مشكلة يجب مراجعتها (النتيجة الفارغة = سليم)
SELECT N'STOCK_MISMATCH' AS IssueCode, N'الكمية المسجلة لا تطابق حركات المخزون' AS IssueText,
       N'Products' AS SourceTable, p.ProductID AS RecordID,
       CAST(COALESCE(l.LedgerQty, 0) AS MONEY) AS ExpectedValue, CAST(p.CurrentQuantity AS MONEY) AS ActualValue
FROM [dbo].[Products] AS p LEFT JOIN [dbo].[qryProductLedger] AS l ON p.ProductID = l.ProductID
WHERE p.CurrentQuantity <> CAST(COALESCE(l.LedgerQty, 0) AS MONEY)
UNION ALL
SELECT N'NEGATIVE_STOCK', N'رصيد المنتج سالب', N'Products', p.ProductID, CAST(0 AS MONEY),
       CAST(p.CurrentQuantity AS MONEY)
FROM [dbo].[Products] AS p
WHERE p.CurrentQuantity < 0
UNION ALL
SELECT N'CUSTOMER_BALANCE', N'رصيد العميل المسجل لا يطابق الحركات', N'Customers', b.CustomerID,
       CAST(b.Balance AS MONEY), CAST(b.CachedBalance AS MONEY)
FROM [dbo].[CustomerBalanceQuery] AS b
WHERE b.Balance <> b.CachedBalance
UNION ALL
SELECT N'SUPPLIER_BALANCE', N'رصيد المورد المسجل لا يطابق الحركات', N'Suppliers', b.SupplierID,
       CAST(b.Balance AS MONEY), CAST(b.CachedBalance AS MONEY)
FROM [dbo].[SupplierBalanceQuery] AS b
WHERE b.Balance <> b.CachedBalance
UNION ALL
SELECT N'SALE_TOTAL', N'إجمالي فاتورة البيع لا يساوي مجموع أسطرها', N'SalesInvoices',
       h.SalesInvoiceID, CAST(COALESCE(t.LinesTotal, 0) AS MONEY), CAST(h.TotalAmount AS MONEY)
FROM [dbo].[SalesInvoices] AS h LEFT JOIN [dbo].[qrySalesInvoiceLineTotals] AS t
     ON h.SalesInvoiceID = t.SalesInvoiceID
WHERE h.TotalAmount <> CAST(COALESCE(t.LinesTotal, 0) AS MONEY) OR t.SalesInvoiceID Is Null
UNION ALL
SELECT N'PURCHASE_TOTAL', N'إجمالي فاتورة الشراء لا يساوي مجموع أسطرها', N'PurchaseInvoices',
       h.PurchaseInvoiceID, CAST(COALESCE(t.LinesTotal, 0) AS MONEY), CAST(h.TotalAmount AS MONEY)
FROM [dbo].[PurchaseInvoices] AS h LEFT JOIN [dbo].[qryPurchaseInvoiceLineTotals] AS t
     ON h.PurchaseInvoiceID = t.PurchaseInvoiceID
WHERE h.TotalAmount <> CAST(COALESCE(t.LinesTotal, 0) AS MONEY) OR t.PurchaseInvoiceID Is Null
UNION ALL
SELECT N'CREDIT_NOT_ALLOWED', N'بيع آجل لعميل غير مسموح له بالآجل', N'SalesInvoices',
       h.SalesInvoiceID, CAST(0 AS MONEY), CAST(h.RemainingAmount AS MONEY)
FROM [dbo].[SalesInvoices] AS h INNER JOIN [dbo].[Customers] AS c ON h.CustomerID = c.CustomerID
WHERE h.RemainingAmount > 0 AND c.AllowCredit = 0
UNION ALL
SELECT N'RETURN_CUSTOMER', N'عميل المرتجع يختلف عن عميل الفاتورة الأصلية', N'SalesReturns',
       r.SalesReturnID, CAST(h.CustomerID AS MONEY), CAST(r.CustomerID AS MONEY)
FROM [dbo].[SalesReturns] AS r INNER JOIN [dbo].[SalesInvoices] AS h ON r.SalesInvoiceID = h.SalesInvoiceID
WHERE r.CustomerID <> h.CustomerID
UNION ALL
SELECT N'RETURN_LINE_INVOICE', N'سطر المرتجع من فاتورة غير فاتورة المرتجع', N'SalesReturnDetails',
       d.ReturnDetailID, CAST(r.SalesInvoiceID AS MONEY), CAST(o.SalesInvoiceID AS MONEY)
FROM ([dbo].[SalesReturnDetails] AS d INNER JOIN [dbo].[SalesReturns] AS r ON d.SalesReturnID = r.SalesReturnID)
     INNER JOIN [dbo].[SalesInvoiceDetails] AS o ON d.SalesDetailID = o.SalesDetailID
WHERE o.SalesInvoiceID <> r.SalesInvoiceID
UNION ALL
SELECT N'RETURN_LINE_PRODUCT', N'منتج سطر المرتجع يختلف عن منتج السطر الأصلي', N'SalesReturnDetails',
       d.ReturnDetailID, CAST(o.ProductID AS MONEY), CAST(d.ProductID AS MONEY)
FROM [dbo].[SalesReturnDetails] AS d INNER JOIN [dbo].[SalesInvoiceDetails] AS o
     ON d.SalesDetailID = o.SalesDetailID
WHERE d.ProductID <> o.ProductID
UNION ALL
SELECT N'SALE_RETURN_QTY', N'الكمية المرتجعة أكبر من الكمية المباعة', N'SalesInvoiceDetails',
       o.SalesDetailID, CAST(o.Quantity AS MONEY), CAST(q.QtyReturned AS MONEY)
FROM [dbo].[SalesInvoiceDetails] AS o INNER JOIN [dbo].[qrySalesReturnedQty] AS q
     ON o.SalesDetailID = q.SalesDetailID
WHERE q.QtyReturned > o.Quantity
UNION ALL
SELECT N'PURCHASE_RETURN_QTY', N'الكمية المرتجعة للمورد أكبر من الكمية المشتراة', N'PurchaseInvoiceDetails',
       o.PurchaseDetailID, CAST(o.Quantity AS MONEY), CAST(q.QtyReturned AS MONEY)
FROM [dbo].[PurchaseInvoiceDetails] AS o INNER JOIN [dbo].[qryPurchaseReturnedQty] AS q
     ON o.PurchaseDetailID = q.PurchaseDetailID
WHERE q.QtyReturned > o.Quantity;
GO
