CREATE OR ALTER VIEW [en].[qrySalesDocuments] AS
-- مستندات البيع: الفواتير (+) والمرتجعات (−) بقيم موقّعة
SELECT N'SALE' AS DocType, h.SalesInvoiceID AS DocID, h.InvoiceNumber AS DocNumber,
       h.InvoiceDate AS DocDate, h.CustomerID, h.EmployeeID, h.PaymentType,
       h.TaxableAmount AS NetAmount, h.Tax AS VATAmount, h.TotalAmount AS GrossAmount,
       h.PaidAmount AS SettledAmount, h.RemainingAmount AS OnAccount
FROM [dbo].[SalesInvoices] AS h
UNION ALL
SELECT N'RETURN', r.SalesReturnID, r.ReturnNumber, r.ReturnDate, r.CustomerID, r.EmployeeID,
       r.RefundType, -r.TaxableAmount, -r.Tax, -r.TotalAmount, -r.RefundedAmount,
       -(r.TotalAmount - r.RefundedAmount)
FROM [dbo].[SalesReturns] AS r;
GO
CREATE OR ALTER VIEW [en].[qrySalesLineItems] AS
-- أسطر البيع والمرتجعات مع التكلفة (أساس تحليل المنتجات والأرباح)
SELECT N'SALE' AS DocType, h.SalesInvoiceID AS DocID, h.InvoiceNumber AS DocNumber,
       h.InvoiceDate AS DocDate, h.CustomerID, d.ProductID, d.Quantity * d.UnitFactor AS SignedQty,
       d.Quantity * d.UnitFactor AS SoldQty, CAST(0 AS MONEY) AS ReturnedQty, d.NetAmount AS LineNet,
       d.Tax AS LineVAT, d.LineTotal AS LineGross, d.Quantity * d.UnitCost AS LineCost
FROM [dbo].[SalesInvoices] AS h INNER JOIN [dbo].[SalesInvoiceDetails] AS d
     ON h.SalesInvoiceID = d.SalesInvoiceID
UNION ALL
SELECT N'RETURN', r.SalesReturnID, r.ReturnNumber, r.ReturnDate, r.CustomerID, d.ProductID,
       -d.Quantity * d.UnitFactor, CAST(0 AS MONEY), d.Quantity * d.UnitFactor, -d.NetAmount, -d.Tax, -d.LineTotal,
       IIF(d.ReturnToStock <> 0, -d.Quantity * d.UnitCost, 0)
FROM [dbo].[SalesReturns] AS r INNER JOIN [dbo].[SalesReturnDetails] AS d
     ON r.SalesReturnID = d.SalesReturnID;
GO
CREATE OR ALTER VIEW [en].[qrySalesLinesInPeriod] AS
-- أسطر البيع والمرتجعات داخل الفترة
SELECT [en].[qrySalesLineItems].* FROM [en].[qrySalesLineItems] CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE DocDate >= qp.[qp_PeriodStart] AND DocDate < qp.[qp_PeriodEnd];
GO
CREATE OR ALTER VIEW [en].[DailySalesQuery] AS
-- المبيعات اليومية: عدد الفواتير والمرتجعات والصافي والنقدي والآجل
SELECT DATEADD(day, DATEDIFF(day, 0, DocDate), 0) AS SaleDate,
       Sum(IIF(DocType = N'SALE', 1, 0)) AS InvoiceCount,
       Sum(IIF(DocType = N'RETURN', 1, 0)) AS ReturnCount,
       Sum(IIF(DocType = N'SALE', NetAmount, 0)) AS SalesExVAT,
       -Sum(IIF(DocType = N'RETURN', NetAmount, 0)) AS ReturnsExVAT,
       Sum(NetAmount) AS NetSalesExVAT, Sum(VATAmount) AS NetVAT,
       Sum(GrossAmount) AS NetSalesTotal,
       Sum(IIF(DocType = N'SALE' AND PaymentType = N'CASH', GrossAmount, 0)) AS CashSales,
       Sum(IIF(DocType = N'SALE' AND PaymentType = N'CREDIT', GrossAmount, 0)) AS CreditSales,
       Sum(SettledAmount) AS CollectedAmount
FROM [en].[qrySalesDocuments]
GROUP BY DATEADD(day, DATEDIFF(day, 0, DocDate), 0);
GO
CREATE OR ALTER VIEW [en].[qrySalesMonthlyDocs] AS
-- تجميع شهري لمستندات البيع
SELECT YEAR(DocDate) AS SalesYear, MONTH(DocDate) AS SalesMonth,
       Sum(IIF(DocType = N'SALE', 1, 0)) AS InvoiceCount,
       Sum(IIF(DocType = N'RETURN', 1, 0)) AS ReturnCount,
       Sum(NetAmount) AS NetSalesExVAT, Sum(VATAmount) AS NetVAT,
       Sum(GrossAmount) AS NetSalesTotal
FROM [en].[qrySalesDocuments]
GROUP BY YEAR(DocDate), MONTH(DocDate);
GO
CREATE OR ALTER VIEW [en].[qrySalesMonthlyCost] AS
-- تكلفة البضاعة المباعة شهريًا
SELECT YEAR(DocDate) AS SalesYear, MONTH(DocDate) AS SalesMonth, Sum(LineCost) AS MonthCost
FROM [en].[qrySalesLineItems]
GROUP BY YEAR(DocDate), MONTH(DocDate);
GO
CREATE OR ALTER VIEW [en].[MonthlySalesQuery] AS
-- المبيعات الشهرية مع التكلفة ومجمل الربح
SELECT d.SalesYear, d.SalesMonth, d.InvoiceCount, d.ReturnCount, d.NetSalesExVAT,
       d.NetVAT, d.NetSalesTotal, CAST(COALESCE(c.MonthCost, 0) AS MONEY) AS CostOfSales,
       d.NetSalesExVAT - CAST(COALESCE(c.MonthCost, 0) AS MONEY) AS GrossProfit
FROM [en].[qrySalesMonthlyDocs] AS d LEFT JOIN [en].[qrySalesMonthlyCost] AS c
     ON (d.SalesYear = c.SalesYear AND d.SalesMonth = c.SalesMonth);
GO
CREATE OR ALTER VIEW [en].[SalesByPeriodQuery] AS
-- فواتير ومرتجعات البيع خلال فترة مع العميل والكاشير
SELECT s.DocType, s.DocID, s.DocNumber, s.DocDate, s.CustomerID, c.CustomerName,
       e.EmployeeName, s.PaymentType, s.NetAmount, s.VATAmount, s.GrossAmount,
       s.SettledAmount, s.OnAccount
FROM ([en].[qrySalesDocuments] AS s INNER JOIN [en].[qryLocCustomers] AS c ON s.CustomerID = c.CustomerID)
     INNER JOIN [dbo].[Employees] AS e ON s.EmployeeID = e.EmployeeID CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE s.DocDate >= qp.[qp_PeriodStart] AND s.DocDate < qp.[qp_PeriodEnd];
GO
CREATE OR ALTER VIEW [en].[SalesByProductQuery] AS
-- المبيعات حسب المنتج خلال فترة (كمية، صافي، تكلفة، ربح)
SELECT p.ProductID, p.ProductCode, p.ProductName, c.CategoryName,
       Sum(l.SoldQty) AS QtySold, Sum(l.ReturnedQty) AS QtyReturned, Sum(l.SignedQty) AS NetQty,
       Sum(l.LineNet) AS NetSales, Sum(l.LineVAT) AS SalesVAT, Sum(l.LineGross) AS SalesTotal,
       Sum(l.LineCost) AS CostOfSales, Sum(l.LineNet) - Sum(l.LineCost) AS GrossProfit
FROM ([en].[qrySalesLinesInPeriod] AS l INNER JOIN [dbo].[Products] AS p ON l.ProductID = p.ProductID)
     INNER JOIN [en].[qryLocCategories] AS c ON p.CategoryID = c.CategoryID
GROUP BY p.ProductID, p.ProductCode, p.ProductName, c.CategoryName;
GO
CREATE OR ALTER VIEW [en].[BestSellingProductsQuery] AS
-- أفضل المنتجات مبيعًا خلال فترة (حسب صافي الكمية)
SELECT * FROM [en].[SalesByProductQuery];
GO
CREATE OR ALTER VIEW [en].[SalesByCategoryQuery] AS
-- المبيعات حسب التصنيف خلال فترة (للرسم الدائري)
SELECT CategoryName, Count(*) AS ProductCount, Sum(NetQty) AS CategoryQty,
       Sum(NetSales) AS CategoryNet, Sum(SalesTotal) AS CategoryTotal, Sum(GrossProfit) AS CategoryProfit
FROM [en].[SalesByProductQuery]
GROUP BY CategoryName;
GO
CREATE OR ALTER VIEW [en].[LeastSellingProductsQuery] AS
-- أقل المنتجات مبيعًا خلال فترة (تشمل المنتجات التي لم تُبع)
SELECT p.ProductID, p.ProductCode, p.ProductName, c.CategoryName, p.CurrentQuantity,
       CAST(COALESCE(s.NetQty, 0) AS MONEY) AS NetQtySold, CAST(COALESCE(s.NetSales, 0) AS MONEY) AS NetSalesAmount
FROM ([dbo].[Products] AS p INNER JOIN [en].[qryLocCategories] AS c ON p.CategoryID = c.CategoryID)
     LEFT JOIN [en].[SalesByProductQuery] AS s ON p.ProductID = s.ProductID
WHERE p.IsActive <> 0;
GO
CREATE OR ALTER VIEW [en].[qryPurchaseDocuments] AS
-- مستندات الشراء: الفواتير (+) والمرتجعات (−)
SELECT N'PURCHASE' AS DocType, h.PurchaseInvoiceID AS DocID, h.InvoiceNumber AS DocNumber,
       h.SupplierInvoiceNo AS SupplierRef, h.InvoiceDate AS DocDate, h.SupplierID,
       h.PaymentType, h.TaxableAmount AS NetAmount, h.Tax AS VATAmount,
       h.TotalAmount AS GrossAmount, h.PaidAmount AS SettledAmount,
       h.RemainingAmount AS OnAccount
FROM [dbo].[PurchaseInvoices] AS h
UNION ALL
SELECT N'RETURN', r.PurchaseReturnID, r.ReturnNumber, Null, r.ReturnDate, r.SupplierID,
       r.RefundType, -r.TaxableAmount, -r.Tax, -r.TotalAmount, -r.RefundedAmount,
       -(r.TotalAmount - r.RefundedAmount)
FROM [dbo].[PurchaseReturns] AS r;
GO
CREATE OR ALTER VIEW [en].[PurchasesQuery] AS
-- فواتير ومرتجعات الشراء خلال فترة مع المورد
SELECT d.DocType, d.DocID, d.DocNumber, d.SupplierRef, d.DocDate, d.SupplierID,
       s.SupplierName, d.PaymentType, d.NetAmount, d.VATAmount, d.GrossAmount,
       d.SettledAmount, d.OnAccount
FROM [en].[qryPurchaseDocuments] AS d INNER JOIN [en].[qryLocSuppliers] AS s ON d.SupplierID = s.SupplierID CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE d.DocDate >= qp.[qp_PeriodStart] AND d.DocDate < qp.[qp_PeriodEnd];
GO
CREATE OR ALTER VIEW [en].[qryProductLedger] AS
-- رصيد كل منتج من دفتر حركة المخزون
SELECT ProductID, Sum(Quantity) AS LedgerQty, Max(TransactionDate) AS LastMovementDate
FROM [dbo].[InventoryTransactions]
GROUP BY ProductID;
GO
CREATE OR ALTER VIEW [en].[qryWarehouseStock] AS
-- رصيد كل منتج في كل مخزن من دفتر حركة المخزون (docs/57)
SELECT ProductID, WarehouseID, Sum(Quantity) AS StockQty, Max(TransactionDate) AS LastMovementDate
FROM [dbo].[InventoryTransactions]
GROUP BY ProductID, WarehouseID;
GO
CREATE OR ALTER VIEW [en].[StockByWarehouseQuery] AS
-- أرصدة الأصناف لكل مخزن: الكمية والقيمة بمتوسط التكلفة
SELECT q.WarehouseID, w.WarehouseName, p.ProductID, p.ProductCode, p.ProductName, c.CategoryName,
       q.StockQty, p.AverageCost, q.StockQty * p.AverageCost AS StockCostValue, q.LastMovementDate
FROM (([en].[qryWarehouseStock] AS q INNER JOIN [en].[qryLocWarehouses] AS w ON q.WarehouseID = w.WarehouseID)
      INNER JOIN [dbo].[Products] AS p ON q.ProductID = p.ProductID)
     INNER JOIN [en].[qryLocCategories] AS c ON p.CategoryID = c.CategoryID
WHERE q.StockQty <> 0;
GO
CREATE OR ALTER VIEW [en].[qryProductLastSale] AS
-- تاريخ آخر بيع لكل منتج
SELECT d.ProductID, Max(h.InvoiceDate) AS LastSaleDate
FROM [dbo].[SalesInvoiceDetails] AS d INNER JOIN [dbo].[SalesInvoices] AS h
     ON d.SalesInvoiceID = h.SalesInvoiceID
GROUP BY d.ProductID;
GO
CREATE OR ALTER VIEW [en].[StockBalanceQuery] AS
-- المخزون الحالي: الكمية والقيمة بالتكلفة وبسعر البيع ومطابقتها مع الحركات
SELECT p.ProductID, p.ProductCode, p.Barcode, p.ProductName, c.CategoryName, u.UnitName,
       p.ProductLocation, p.CurrentQuantity, p.MinimumQuantity, p.AverageCost, p.SellingPrice,
       p.CurrentQuantity * p.AverageCost AS StockCostValue,
       p.CurrentQuantity * p.SellingPrice AS StockSalesValue,
       CAST(COALESCE(l.LedgerQty, 0) AS MONEY) AS LedgerQuantity,
       p.CurrentQuantity - CAST(COALESCE(l.LedgerQty, 0) AS MONEY) AS QuantityMismatch,
       IIF(p.CurrentQuantity <= p.MinimumQuantity, CAST(1 AS BIT), CAST(0 AS BIT)) AS IsLowStock, p.IsActive
FROM (([dbo].[Products] AS p INNER JOIN [en].[qryLocCategories] AS c ON p.CategoryID = c.CategoryID)
      INNER JOIN [en].[qryLocUnits] AS u ON p.UnitID = u.UnitID)
     LEFT JOIN [en].[qryProductLedger] AS l ON p.ProductID = l.ProductID;
GO
CREATE OR ALTER VIEW [en].[LowStockQuery] AS
-- المنتجات منخفضة المخزون: CurrentQuantity <= MinimumQuantity
SELECT p.ProductID, p.ProductCode, p.Barcode, p.ProductName, c.CategoryName,
       p.CurrentQuantity, p.MinimumQuantity, p.MinimumQuantity - p.CurrentQuantity AS ShortageQty,
       s.SupplierName, s.Mobile AS SupplierMobile
FROM ([dbo].[Products] AS p INNER JOIN [en].[qryLocCategories] AS c ON p.CategoryID = c.CategoryID)
     LEFT JOIN [en].[qryLocSuppliers] AS s ON p.SupplierID = s.SupplierID
WHERE p.IsActive <> 0 AND p.TrackStock <> 0 AND p.CurrentQuantity <= p.MinimumQuantity;
GO
CREATE OR ALTER VIEW [en].[ProductMovementQuery] AS
-- حركة منتج خلال فترة مع رصيد أول المدة (الرصيد التراكمي في التقرير)
SELECT 1 AS SortKey, t.TransactionID, t.TransactionDate AS MovementDate,
       tt.TypeName AS MovementType, t.ReferenceNumber,
       IIF(t.Quantity > 0, t.Quantity, 0) AS QtyIn, IIF(t.Quantity < 0, -t.Quantity, 0) AS QtyOut,
       t.Quantity AS NetQty, t.UnitCost, t.Notes
FROM [dbo].[InventoryTransactions] AS t INNER JOIN [en].[qryLocTransactionTypes] AS tt
     ON t.TransactionTypeID = tt.TransactionTypeID CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE t.ProductID = qp.[qp_ProductID] AND t.TransactionDate >= qp.[qp_PeriodStart] AND t.TransactionDate < qp.[qp_PeriodEnd]
UNION ALL
SELECT 0, 0, (SELECT p.[qp_PeriodStart] FROM [dbo].[QueryParamsNow] AS p), N'Opening balance', Null,
       IIF(CAST(COALESCE(Sum(o.Quantity), 0) AS MONEY) > 0, CAST(COALESCE(Sum(o.Quantity), 0) AS MONEY), 0),
       IIF(CAST(COALESCE(Sum(o.Quantity), 0) AS MONEY) < 0, -CAST(COALESCE(Sum(o.Quantity), 0) AS MONEY), 0),
       CAST(COALESCE(Sum(o.Quantity), 0) AS MONEY), Null, Null
FROM [dbo].[InventoryTransactions] AS o CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE o.ProductID = qp.[qp_ProductID] AND o.TransactionDate < qp.[qp_PeriodStart];
GO
CREATE OR ALTER VIEW [en].[qryStockMoveParty] AS
-- الجهة الأخرى لكل حركة مخزون: العميل، أو المورد، أو جهة السند، أو المخزن الآخر في التحويل
SELECT t.TransactionID, c.CustomerName AS PartyName
FROM ([dbo].[InventoryTransactions] AS t INNER JOIN [dbo].[SalesInvoices] AS h ON t.ReferenceID = h.SalesInvoiceID)
     INNER JOIN [en].[qryLocCustomers] AS c ON h.CustomerID = c.CustomerID
WHERE t.ReferenceType = N'SALE'
UNION ALL
SELECT t.TransactionID, c.CustomerName
FROM ([dbo].[InventoryTransactions] AS t INNER JOIN [dbo].[SalesReturns] AS r ON t.ReferenceID = r.SalesReturnID)
     INNER JOIN [en].[qryLocCustomers] AS c ON r.CustomerID = c.CustomerID
WHERE t.ReferenceType = N'SALES_RETURN'
UNION ALL
SELECT t.TransactionID, s.SupplierName
FROM ([dbo].[InventoryTransactions] AS t INNER JOIN [dbo].[PurchaseInvoices] AS h ON t.ReferenceID = h.PurchaseInvoiceID)
     INNER JOIN [en].[qryLocSuppliers] AS s ON h.SupplierID = s.SupplierID
WHERE t.ReferenceType = N'PURCHASE'
UNION ALL
SELECT t.TransactionID, s.SupplierName
FROM ([dbo].[InventoryTransactions] AS t INNER JOIN [dbo].[PurchaseReturns] AS r ON t.ReferenceID = r.PurchaseReturnID)
     INNER JOIN [en].[qryLocSuppliers] AS s ON r.SupplierID = s.SupplierID
WHERE t.ReferenceType = N'PURCHASE_RETURN'
UNION ALL
SELECT t.TransactionID, p.PartyName
FROM ([dbo].[InventoryTransactions] AS t INNER JOIN [dbo].[StockDocuments] AS d ON t.ReferenceID = d.StockDocumentID)
     INNER JOIN [en].[qryLocStockParties] AS p ON d.StockPartyID = p.StockPartyID
WHERE t.ReferenceType = N'STOCK_DOC'
UNION ALL
SELECT t.TransactionID, c.CustomerName
FROM ([dbo].[InventoryTransactions] AS t INNER JOIN [dbo].[StockNotes] AS n ON t.ReferenceID = n.StockNoteID)
     INNER JOIN [en].[qryLocCustomers] AS c ON n.CustomerID = c.CustomerID
WHERE t.ReferenceType = N'STOCK_NOTE' AND n.NoteType = N'DELIVERY'
UNION ALL
SELECT t.TransactionID, s.SupplierName
FROM ([dbo].[InventoryTransactions] AS t INNER JOIN [dbo].[StockNotes] AS n ON t.ReferenceID = n.StockNoteID)
     INNER JOIN [en].[qryLocSuppliers] AS s ON n.SupplierID = s.SupplierID
WHERE t.ReferenceType = N'STOCK_NOTE' AND n.NoteType = N'RECEIPT'
UNION ALL
SELECT t.TransactionID, w.WarehouseName
FROM ([dbo].[InventoryTransactions] AS t INNER JOIN [dbo].[StockTransfers] AS x ON t.ReferenceID = x.StockTransferID)
     INNER JOIN [en].[qryLocWarehouses] AS w ON x.ToWarehouseID = w.WarehouseID
WHERE t.ReferenceType = N'TRANSFER' AND t.Quantity < 0
UNION ALL
SELECT t.TransactionID, w.WarehouseName
FROM ([dbo].[InventoryTransactions] AS t INNER JOIN [dbo].[StockTransfers] AS x ON t.ReferenceID = x.StockTransferID)
     INNER JOIN [en].[qryLocWarehouses] AS w ON x.FromWarehouseID = w.WarehouseID
WHERE t.ReferenceType = N'TRANSFER' AND t.Quantity > 0;
GO
CREATE OR ALTER VIEW [en].[ItemCardQuery] AS
-- كارت الصنف: رصيد أول المدة بالكمية والقيمة، ثم كل حركة في مخزن (أو كل المخازن) خلال فترة
SELECT 1 AS SortKey, t.TransactionID AS MoveID, t.TransactionDate AS MovementDate, tt.TypeName AS MovementType,
       t.ReferenceNumber, w.WarehouseName, m.PartyName,
       IIF(t.Quantity > 0, t.Quantity, 0) AS QtyIn, IIF(t.Quantity < 0, -t.Quantity, 0) AS QtyOut,
       t.Quantity AS NetQty, CAST(COALESCE(t.UnitCost, 0) AS MONEY) AS MoveCost,
       IIF(t.Quantity > 0, CAST(t.Quantity * CAST(COALESCE(t.UnitCost, 0) AS MONEY) AS MONEY), 0) AS ValueIn,
       IIF(t.Quantity < 0, CAST(-t.Quantity * CAST(COALESCE(t.UnitCost, 0) AS MONEY) AS MONEY), 0) AS ValueOut,
       CAST(t.Quantity * CAST(COALESCE(t.UnitCost, 0) AS MONEY) AS MONEY) AS NetValue, t.Notes
FROM (([dbo].[InventoryTransactions] AS t INNER JOIN [en].[qryLocTransactionTypes] AS tt ON t.TransactionTypeID = tt.TransactionTypeID)
      INNER JOIN [en].[qryLocWarehouses] AS w ON t.WarehouseID = w.WarehouseID)
     LEFT JOIN [en].[qryStockMoveParty] AS m ON t.TransactionID = m.TransactionID CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE t.ProductID = qp.[qp_ProductID] AND t.TransactionDate >= qp.[qp_PeriodStart] AND t.TransactionDate < qp.[qp_PeriodEnd]
  AND (qp.[qp_WarehouseID] = 0 OR t.WarehouseID = qp.[qp_WarehouseID])
UNION ALL
SELECT 0, 0, (SELECT p.[qp_PeriodStart] FROM [dbo].[QueryParamsNow] AS p), N'Opening balance', Null, Null, Null,
       IIF(CAST(COALESCE(Sum(o.Quantity), 0) AS MONEY) > 0, CAST(COALESCE(Sum(o.Quantity), 0) AS MONEY), 0),
       IIF(CAST(COALESCE(Sum(o.Quantity), 0) AS MONEY) < 0, -CAST(COALESCE(Sum(o.Quantity), 0) AS MONEY), 0),
       CAST(COALESCE(Sum(o.Quantity), 0) AS MONEY), Null,
       IIF(CAST(COALESCE(Sum(CAST(o.Quantity * o.UnitCost AS MONEY)), 0) AS MONEY) > 0, CAST(COALESCE(Sum(CAST(o.Quantity * o.UnitCost AS MONEY)), 0) AS MONEY), 0),
       IIF(CAST(COALESCE(Sum(CAST(o.Quantity * o.UnitCost AS MONEY)), 0) AS MONEY) < 0, -CAST(COALESCE(Sum(CAST(o.Quantity * o.UnitCost AS MONEY)), 0) AS MONEY), 0),
       CAST(COALESCE(Sum(CAST(o.Quantity * o.UnitCost AS MONEY)), 0) AS MONEY), Null
FROM [dbo].[InventoryTransactions] AS o CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE o.ProductID = qp.[qp_ProductID] AND o.TransactionDate < qp.[qp_PeriodStart]
  AND (qp.[qp_WarehouseID] = 0 OR o.WarehouseID = qp.[qp_WarehouseID]);
GO
CREATE OR ALTER VIEW [en].[StockValueByWarehouseQuery] AS
-- تقييم المخزون لكل مخزن: عدد الأصناف والكمية والقيمة بالتكلفة وبسعر البيع
SELECT q.WarehouseID, w.WarehouseName, Min(IIF(q.WarehouseID = 1, 1400, 140000 + q.WarehouseID)) AS StockAccount,
       Count(*) AS ProductCount, Sum(q.StockQty) AS TotalQuantity,
       Sum(q.StockQty * p.AverageCost) AS StockCostValue, Sum(q.StockQty * p.SellingPrice) AS StockSalesValue
FROM ([en].[qryWarehouseStock] AS q INNER JOIN [en].[qryLocWarehouses] AS w ON q.WarehouseID = w.WarehouseID)
     INNER JOIN [dbo].[Products] AS p ON q.ProductID = p.ProductID
WHERE q.StockQty <> 0
GROUP BY q.WarehouseID, w.WarehouseName;
GO
CREATE OR ALTER VIEW [en].[StockCountDiffQuery] AS
-- فروقات الجرد المرحّلة لكل مخزن: العجز والزيادة وقيمتهما كما رُحّلت
SELECT c.StockCountID, c.CountNumber, c.CountDate, c.WarehouseID, w.WarehouseName, p.ProductID, p.ProductCode,
       p.ProductName, IIF(t.Quantity < 0, -t.Quantity, 0) AS ShortQty, IIF(t.Quantity > 0, t.Quantity, 0) AS ExtraQty,
       t.UnitCost, CAST(t.Quantity * t.UnitCost AS MONEY) AS DiffValue
FROM (([dbo].[InventoryTransactions] AS t INNER JOIN [dbo].[StockCounts] AS c ON t.ReferenceID = c.StockCountID)
      INNER JOIN [en].[qryLocWarehouses] AS w ON c.WarehouseID = w.WarehouseID)
     INNER JOIN [dbo].[Products] AS p ON t.ProductID = p.ProductID
WHERE t.ReferenceType = N'STOCK_COUNT';
GO
CREATE OR ALTER VIEW [en].[SlowMovingProductsQuery] AS
-- المنتجات غير المتحركة: لها رصيد ولم تُبع منذ عدد الأيام المحدد في الإعدادات
SELECT p.ProductID, p.ProductCode, p.ProductName, c.CategoryName, p.CurrentQuantity,
       p.AverageCost, p.CurrentQuantity * p.AverageCost AS StockCostValue, ls.LastSaleDate,
       DATEDIFF(day, COALESCE(ls.LastSaleDate, p.CreatedAt), DATEADD(day, DATEDIFF(day, 0, GETDATE()), 0)) AS DaysWithoutSale
FROM ([dbo].[Products] AS p INNER JOIN [en].[qryLocCategories] AS c ON p.CategoryID = c.CategoryID)
     LEFT JOIN [en].[qryProductLastSale] AS ls ON p.ProductID = ls.ProductID
WHERE p.IsActive <> 0 AND p.CurrentQuantity > 0
  AND DATEDIFF(day, COALESCE(ls.LastSaleDate, p.CreatedAt), DATEADD(day, DATEDIFF(day, 0, GETDATE()), 0)) >=
      (SELECT SlowMovingDays FROM [dbo].[Settings]);
GO
CREATE OR ALTER VIEW [en].[StockByCategoryQuery] AS
-- المخزون حسب التصنيف: عدد المنتجات والكمية والقيمة
SELECT c.CategoryID, c.CategoryName, Count(*) AS ProductCount,
       Sum(p.CurrentQuantity) AS TotalQuantity,
       Sum(p.CurrentQuantity * p.AverageCost) AS StockCostValue,
       Sum(p.CurrentQuantity * p.SellingPrice) AS StockSalesValue
FROM [dbo].[Products] AS p INNER JOIN [en].[qryLocCategories] AS c ON p.CategoryID = c.CategoryID
WHERE p.IsActive <> 0
GROUP BY c.CategoryID, c.CategoryName;
GO
CREATE OR ALTER VIEW [en].[StockCountQuery] AS
-- تفاصيل جلسات الجرد: الكمية المسجلة والفعلية والفرق وقيمته
SELECT c.StockCountID, c.CountNumber, c.CountDate, c.Status, c.CategoryID, g.CategoryName,
       c.WarehouseID, w.WarehouseName,
       d.ProductID, p.ProductCode, p.ProductName, d.SystemQuantity, d.ActualQuantity, d.Difference,
       d.UnitCost, d.DifferenceValue, d.Notes
FROM ((([dbo].[StockCountDetails] AS d INNER JOIN [dbo].[StockCounts] AS c ON d.StockCountID = c.StockCountID)
       INNER JOIN [dbo].[Products] AS p ON d.ProductID = p.ProductID)
      LEFT JOIN [en].[qryLocCategories] AS g ON c.CategoryID = g.CategoryID)
     LEFT JOIN [en].[qryLocWarehouses] AS w ON c.WarehouseID = w.WarehouseID;
GO
CREATE OR ALTER VIEW [en].[qryCustomerOpening] AS
-- الرصيد الافتتاحي لكل عميل بتاريخ بدء التشغيل
SELECT c.CustomerID, c.CustomerName, c.OpeningBalance,
       IIF(st.OpeningDate Is Null, c.CreatedAt, st.OpeningDate) AS OpeningOn
FROM [en].[qryLocCustomers] AS c, [dbo].[Settings] AS st
WHERE st.SettingID = 1 AND c.OpeningBalance <> 0;
GO
CREATE OR ALTER VIEW [en].[qrySupplierOpening] AS
-- الرصيد الافتتاحي لكل مورد بتاريخ بدء التشغيل
SELECT s.SupplierID, s.SupplierName, s.OpeningBalance,
       IIF(st.OpeningDate Is Null, s.CreatedAt, st.OpeningDate) AS OpeningOn
FROM [en].[qryLocSuppliers] AS s, [dbo].[Settings] AS st
WHERE st.SettingID = 1 AND s.OpeningBalance <> 0;
GO
CREATE OR ALTER VIEW [en].[qryOpeningAccountLines] AS
-- الأرصدة الافتتاحية للحسابات العامة بتاريخ بدء التشغيل (لا شيء قبل حفظ التاريخ)
SELECT o.OpeningLineID, o.AccountCode AS LineAccount, o.Debit AS LineDebit, o.Credit AS LineCredit, a.AccountName,
       st.OpeningDate AS OpeningOn
FROM ([dbo].[OpeningBalances] AS o INNER JOIN [en].[qryLocAccounts] AS a ON o.AccountCode = a.AccountCode), [dbo].[Settings] AS st
WHERE st.SettingID = 1 AND st.OpeningDate Is Not Null;
GO
CREATE OR ALTER VIEW [en].[qryOpeningTotals] AS
-- حساب إجمالي الأرصدة الافتتاحية (3900): مدينه ودائنه حسب مصدر الرصيد
SELECT e.SourceType, t.TypeName, Sum(l.Debit) AS SumDebit, Sum(l.Credit) AS SumCredit
FROM ([dbo].[JournalLines] AS l INNER JOIN [dbo].[JournalEntries] AS e ON l.EntryID = e.EntryID)
     INNER JOIN [en].[qryLocJournalSourceTypes] AS t ON e.SourceType = t.SourceType
WHERE l.AccountCode = 3900
GROUP BY e.SourceType, t.TypeName;
GO
CREATE OR ALTER VIEW [en].[qryCustomerLedger] AS
-- دفتر حساب العملاء: مدين (عليه) / دائن (له)
SELECT h.CustomerID, h.InvoiceDate AS EntryDate, N'SALE' AS EntryType,
       N'Sales invoice' AS EntryTypeName, h.SalesInvoiceID AS DocID, h.InvoiceNumber AS DocNumber,
       h.TotalAmount AS Debit, h.PaidAmount AS Credit
FROM [dbo].[SalesInvoices] AS h
UNION ALL
SELECT r.CustomerID, r.ReturnDate, N'SALES_RETURN', N'Sales return', r.SalesReturnID, r.ReturnNumber,
       r.RefundedAmount, r.TotalAmount
FROM [dbo].[SalesReturns] AS r
UNION ALL
SELECT p.CustomerID, p.PaymentDate, N'PAYMENT', N'Receipt voucher', p.PaymentID, p.PaymentNumber,
       CAST(0 AS MONEY), p.Amount
FROM [dbo].[CustomerPayments] AS p
UNION ALL
SELECT c.CustomerID, c.OpeningOn, N'OPENING', N'Opening balance', 0, N'-',
       IIF(c.OpeningBalance > 0, c.OpeningBalance, 0),
       IIF(c.OpeningBalance < 0, -c.OpeningBalance, 0)
FROM [en].[qryCustomerOpening] AS c
UNION ALL
SELECT q.CustomerID, q.IssueDate, N'CHEQUE', N'Received cheque', q.ChequeID, q.ChequeNo, CAST(0 AS MONEY), q.Amount
FROM [dbo].[Cheques] AS q
WHERE q.Direction = N'IN'
UNION ALL
SELECT q.CustomerID, q.StatusDate, N'CHEQUE_BOUNCE', N'Bounced cheque', q.ChequeID, q.ChequeNo, q.Amount, CAST(0 AS MONEY)
FROM [dbo].[Cheques] AS q
WHERE q.Direction = N'IN' AND q.Status = N'BOUNCED';
GO
CREATE OR ALTER VIEW [en].[qryCustomerLedgerTotals] AS
-- مجاميع حساب كل عميل
SELECT CustomerID, Sum(Debit) AS TotalDebit, Sum(Credit) AS TotalCredit,
       Max(EntryDate) AS LastEntryDate
FROM [en].[qryCustomerLedger]
GROUP BY CustomerID;
GO
CREATE OR ALTER VIEW [en].[CustomerBalanceQuery] AS
-- رصيد كل عميل محسوبًا من الحركات (موجب = عليه للمحل)
SELECT c.CustomerID, c.CustomerName, c.Mobile, c.CreditLimit, c.AllowCredit, c.IsActive,
       CAST(COALESCE(l.TotalDebit, 0) AS MONEY) AS DebitTotal, CAST(COALESCE(l.TotalCredit, 0) AS MONEY) AS CreditTotal,
       CAST(COALESCE(l.TotalDebit, 0) AS MONEY) - CAST(COALESCE(l.TotalCredit, 0) AS MONEY) AS Balance,
       c.CurrentBalance AS CachedBalance, l.LastEntryDate
FROM [en].[qryLocCustomers] AS c LEFT JOIN [en].[qryCustomerLedgerTotals] AS l ON c.CustomerID = l.CustomerID;
GO
CREATE OR ALTER VIEW [en].[CustomersWithDebtQuery] AS
-- العملاء الذين عليهم مبالغ مستحقة
SELECT * FROM [en].[CustomerBalanceQuery]
WHERE Balance > 0;
GO
CREATE OR ALTER VIEW [en].[CustomerStatementQuery] AS
-- كشف حساب عميل لفترة: رصيد سابق ثم الحركات
SELECT 1 AS SortKey, l.EntryDate, l.EntryType, l.EntryTypeName, l.DocNumber, l.Debit, l.Credit
FROM [en].[qryCustomerLedger] AS l CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE l.CustomerID = qp.[qp_CustomerID] AND l.EntryDate >= qp.[qp_PeriodStart] AND l.EntryDate < qp.[qp_PeriodEnd]
UNION ALL
SELECT 0, (SELECT p.[qp_PeriodStart] FROM [dbo].[QueryParamsNow] AS p), N'BALANCE_FWD', N'Previous balance', N'-',
       IIF(CAST(COALESCE(Sum(o.Debit), 0) AS MONEY) - CAST(COALESCE(Sum(o.Credit), 0) AS MONEY) > 0, CAST(COALESCE(Sum(o.Debit), 0) AS MONEY) - CAST(COALESCE(Sum(o.Credit), 0) AS MONEY), 0),
       IIF(CAST(COALESCE(Sum(o.Debit), 0) AS MONEY) - CAST(COALESCE(Sum(o.Credit), 0) AS MONEY) < 0, CAST(COALESCE(Sum(o.Credit), 0) AS MONEY) - CAST(COALESCE(Sum(o.Debit), 0) AS MONEY), 0)
FROM [en].[qryCustomerLedger] AS o CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE o.CustomerID = qp.[qp_CustomerID] AND o.EntryDate < qp.[qp_PeriodStart];
GO
CREATE OR ALTER VIEW [en].[qrySupplierLedger] AS
-- دفتر حساب الموردين: دائن (للمورد) / مدين (سُدِّد له)
SELECT h.SupplierID, h.InvoiceDate AS EntryDate, N'PURCHASE' AS EntryType,
       N'Purchase invoice' AS EntryTypeName, h.PurchaseInvoiceID AS DocID, h.InvoiceNumber AS DocNumber,
       h.PaidAmount AS Debit, h.TotalAmount AS Credit
FROM [dbo].[PurchaseInvoices] AS h
UNION ALL
SELECT r.SupplierID, r.ReturnDate, N'PURCHASE_RETURN', N'Purchase return', r.PurchaseReturnID,
       r.ReturnNumber, r.TotalAmount, r.RefundedAmount
FROM [dbo].[PurchaseReturns] AS r
UNION ALL
SELECT p.SupplierID, p.PaymentDate, N'PAYMENT', N'Payment voucher', p.PaymentID, p.PaymentNumber,
       p.Amount, CAST(0 AS MONEY)
FROM [dbo].[SupplierPayments] AS p
UNION ALL
SELECT s.SupplierID, s.OpeningOn, N'OPENING', N'Opening balance', 0, N'-',
       IIF(s.OpeningBalance < 0, -s.OpeningBalance, 0),
       IIF(s.OpeningBalance > 0, s.OpeningBalance, 0)
FROM [en].[qrySupplierOpening] AS s
UNION ALL
SELECT q.SupplierID, q.IssueDate, N'CHEQUE', N'Issued cheque', q.ChequeID, q.ChequeNo, q.Amount, CAST(0 AS MONEY)
FROM [dbo].[Cheques] AS q
WHERE q.Direction = N'OUT'
UNION ALL
SELECT q.SupplierID, q.StatusDate, N'CHEQUE_BOUNCE', N'Bounced cheque', q.ChequeID, q.ChequeNo, CAST(0 AS MONEY), q.Amount
FROM [dbo].[Cheques] AS q
WHERE q.Direction = N'OUT' AND q.Status = N'BOUNCED';
GO
CREATE OR ALTER VIEW [en].[qrySupplierLedgerTotals] AS
-- مجاميع حساب كل مورد
SELECT SupplierID, Sum(Debit) AS TotalDebit, Sum(Credit) AS TotalCredit,
       Max(EntryDate) AS LastEntryDate
FROM [en].[qrySupplierLedger]
GROUP BY SupplierID;
GO
CREATE OR ALTER VIEW [en].[SupplierBalanceQuery] AS
-- رصيد كل مورد محسوبًا من الحركات (موجب = مستحق للمورد)
SELECT s.SupplierID, s.SupplierName, s.ContactPerson, s.Mobile, s.IsActive,
       CAST(COALESCE(l.TotalDebit, 0) AS MONEY) AS DebitTotal, CAST(COALESCE(l.TotalCredit, 0) AS MONEY) AS CreditTotal,
       CAST(COALESCE(l.TotalCredit, 0) AS MONEY) - CAST(COALESCE(l.TotalDebit, 0) AS MONEY) AS Balance,
       s.CurrentBalance AS CachedBalance, l.LastEntryDate
FROM [en].[qryLocSuppliers] AS s LEFT JOIN [en].[qrySupplierLedgerTotals] AS l ON s.SupplierID = l.SupplierID;
GO
CREATE OR ALTER VIEW [en].[qrySupplierFxMoves] AS
-- حركات أرصدة الموردين بعملة كل مستند (الرصيد الافتتاحي والشيكات بعملة البرنامج)
SELECT h.SupplierID, h.CurrencyCode, h.TotalAmount - h.PaidAmount AS BaseAmount,
       ROUND((h.TotalAmount - h.PaidAmount) * 1e0 / h.ExchangeRate, 2) AS FxAmount
FROM [dbo].[PurchaseInvoices] AS h
UNION ALL
SELECT r.SupplierID, r.CurrencyCode, r.RefundedAmount - r.TotalAmount, ROUND((r.RefundedAmount - r.TotalAmount) * 1e0 / r.ExchangeRate, 2)
FROM [dbo].[PurchaseReturns] AS r
UNION ALL
SELECT p.SupplierID, p.CurrencyCode, -p.Amount, ROUND(-p.Amount * 1e0 / p.ExchangeRate, 2)
FROM [dbo].[SupplierPayments] AS p
UNION ALL
SELECT s.SupplierID, z.CurrencyCode, s.OpeningBalance, s.OpeningBalance
FROM [dbo].[Suppliers] AS s, [dbo].[Settings] AS z
WHERE z.SettingID = 1 AND s.OpeningBalance <> 0
UNION ALL
SELECT q.SupplierID, z.CurrencyCode, IIF(q.Status = N'BOUNCED', 0, -q.Amount), IIF(q.Status = N'BOUNCED', 0, -q.Amount)
FROM [dbo].[Cheques] AS q, [dbo].[Settings] AS z
WHERE z.SettingID = 1 AND q.Direction = N'OUT';
GO
CREATE OR ALTER VIEW [en].[qryLatestRateDates] AS
-- تاريخ آخر سعر لكل عملة
SELECT CurrencyCode, Max(RateDate) AS LastRateDate
FROM [dbo].[CurrencyRates]
GROUP BY CurrencyCode;
GO
CREATE OR ALTER VIEW [en].[qryLatestRates] AS
-- آخر معامل لكل عملة
SELECT r.CurrencyCode, r.RateDate, r.Rate
FROM [dbo].[CurrencyRates] AS r INNER JOIN [en].[qryLatestRateDates] AS d
     ON (r.CurrencyCode = d.CurrencyCode AND r.RateDate = d.LastRateDate);
GO
CREATE OR ALTER VIEW [en].[qrySupplierFxTotals] AS
-- رصيد كل مورد بكل عملة
SELECT SupplierID, CurrencyCode, Sum(BaseAmount) AS BookBalance, Sum(FxAmount) AS FxBalance
FROM [en].[qrySupplierFxMoves]
GROUP BY SupplierID, CurrencyCode;
GO
CREATE OR ALTER VIEW [en].[SupplierFxBalanceQuery] AS
-- أرصدة الموردين بالعملات الأجنبية: بالدفاتر، وبآخر سعر، وفرق العملة غير المحقق
SELECT s.SupplierName, t.SupplierID, t.CurrencyCode, t.FxBalance, t.BookBalance, l.Rate AS LastRate, l.RateDate AS LastRateDate,
       ROUND(t.FxBalance * CAST(COALESCE(l.Rate, 0) AS MONEY), 2) AS RevaluedBalance,
       ROUND(t.FxBalance * CAST(COALESCE(l.Rate, 0) AS MONEY), 2) - t.BookBalance AS FxDifference
FROM ([en].[qrySupplierFxTotals] AS t INNER JOIN [en].[qryLocSuppliers] AS s ON t.SupplierID = s.SupplierID)
      LEFT JOIN [en].[qryLatestRates] AS l ON t.CurrencyCode = l.CurrencyCode
WHERE t.CurrencyCode <> (SELECT st.CurrencyCode FROM [dbo].[Settings] AS st WHERE st.SettingID = 1) AND (t.FxBalance <> 0 OR t.BookBalance <> 0);
GO
CREATE OR ALTER VIEW [en].[SupplierStatementQuery] AS
-- كشف حساب مورد لفترة: رصيد سابق ثم الحركات
SELECT 1 AS SortKey, l.EntryDate, l.EntryType, l.EntryTypeName, l.DocNumber, l.Debit, l.Credit
FROM [en].[qrySupplierLedger] AS l CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE l.SupplierID = qp.[qp_SupplierID] AND l.EntryDate >= qp.[qp_PeriodStart] AND l.EntryDate < qp.[qp_PeriodEnd]
UNION ALL
SELECT 0, (SELECT p.[qp_PeriodStart] FROM [dbo].[QueryParamsNow] AS p), N'BALANCE_FWD', N'Previous balance', N'-',
       IIF(CAST(COALESCE(Sum(o.Debit), 0) AS MONEY) - CAST(COALESCE(Sum(o.Credit), 0) AS MONEY) > 0, CAST(COALESCE(Sum(o.Debit), 0) AS MONEY) - CAST(COALESCE(Sum(o.Credit), 0) AS MONEY), 0),
       IIF(CAST(COALESCE(Sum(o.Debit), 0) AS MONEY) - CAST(COALESCE(Sum(o.Credit), 0) AS MONEY) < 0, CAST(COALESCE(Sum(o.Credit), 0) AS MONEY) - CAST(COALESCE(Sum(o.Debit), 0) AS MONEY), 0)
FROM [en].[qrySupplierLedger] AS o CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE o.SupplierID = qp.[qp_SupplierID] AND o.EntryDate < qp.[qp_PeriodStart];
GO
CREATE OR ALTER VIEW [en].[qryCustomerAllocSums] AS
-- مجموع ما رُبط من كل سند بالفواتير
SELECT PaymentID, Sum(Amount) AS SumAllocated
FROM [dbo].[CustomerAllocations]
GROUP BY PaymentID;
GO
CREATE OR ALTER VIEW [en].[qryCustomerPaymentFree] AS
-- سندات القبض: المربوط بالفواتير والباقي غير المربوط
SELECT p.PaymentID, p.CustomerID AS PartyID, p.PaymentNumber, p.PaymentDate, p.Amount,
       CAST(COALESCE(s.SumAllocated, 0) AS MONEY) AS Allocated, p.Amount - CAST(COALESCE(s.SumAllocated, 0) AS MONEY) AS Free
FROM [dbo].[CustomerPayments] AS p LEFT JOIN [en].[qryCustomerAllocSums] AS s ON p.PaymentID = s.PaymentID;
GO
CREATE OR ALTER VIEW [en].[qryCustomerInvoiceAlloc] AS
-- مجموع ما رُبط بكل فاتورة من السندات
SELECT SalesInvoiceID, Sum(Amount) AS SumAllocated
FROM [dbo].[CustomerAllocations]
GROUP BY SalesInvoiceID;
GO
CREATE OR ALTER VIEW [en].[qryCustomerInvoiceReturns] AS
-- مرتجعات كل فاتورة المخصومة من رصيد الحساب
SELECT SalesInvoiceID, Sum(TotalAmount - RefundedAmount) AS SumReturned
FROM [dbo].[SalesReturns]
GROUP BY SalesInvoiceID;
GO
CREATE OR ALTER VIEW [en].[qryCustomerInvoiceFree] AS
-- الفواتير الآجلة: المتبقي وما رُبط بها وما يمكن ربطه
SELECT h.SalesInvoiceID AS InvoiceID, h.CustomerID AS PartyID, h.InvoiceNumber, h.InvoiceDate, h.DueDate,
       h.RemainingAmount, CAST(COALESCE(a.SumAllocated, 0) AS MONEY) AS Allocated, CAST(COALESCE(r.SumReturned, 0) AS MONEY) AS Returned,
       h.RemainingAmount - CAST(COALESCE(a.SumAllocated, 0) AS MONEY) - CAST(COALESCE(r.SumReturned, 0) AS MONEY) AS Free
FROM ([dbo].[SalesInvoices] AS h LEFT JOIN [en].[qryCustomerInvoiceAlloc] AS a ON h.SalesInvoiceID = a.SalesInvoiceID)
     LEFT JOIN [en].[qryCustomerInvoiceReturns] AS r ON h.SalesInvoiceID = r.SalesInvoiceID
WHERE h.RemainingAmount > 0;
GO
CREATE OR ALTER VIEW [en].[qrySupplierAllocSums] AS
-- مجموع ما رُبط من كل سند بالفواتير
SELECT PaymentID, Sum(Amount) AS SumAllocated
FROM [dbo].[SupplierAllocations]
GROUP BY PaymentID;
GO
CREATE OR ALTER VIEW [en].[qrySupplierPaymentFree] AS
-- سندات الصرف: المربوط بالفواتير والباقي غير المربوط
SELECT p.PaymentID, p.SupplierID AS PartyID, p.PaymentNumber, p.PaymentDate, p.Amount,
       CAST(COALESCE(s.SumAllocated, 0) AS MONEY) AS Allocated, p.Amount - CAST(COALESCE(s.SumAllocated, 0) AS MONEY) AS Free
FROM [dbo].[SupplierPayments] AS p LEFT JOIN [en].[qrySupplierAllocSums] AS s ON p.PaymentID = s.PaymentID;
GO
CREATE OR ALTER VIEW [en].[qrySupplierInvoiceAlloc] AS
-- مجموع ما رُبط بكل فاتورة من السندات
SELECT PurchaseInvoiceID, Sum(Amount) AS SumAllocated
FROM [dbo].[SupplierAllocations]
GROUP BY PurchaseInvoiceID;
GO
CREATE OR ALTER VIEW [en].[qrySupplierInvoiceReturns] AS
-- مرتجعات كل فاتورة المخصومة من رصيد الحساب
SELECT PurchaseInvoiceID, Sum(TotalAmount - RefundedAmount) AS SumReturned
FROM [dbo].[PurchaseReturns]
GROUP BY PurchaseInvoiceID;
GO
CREATE OR ALTER VIEW [en].[qrySupplierInvoiceFree] AS
-- الفواتير الآجلة: المتبقي وما رُبط بها وما يمكن ربطه
SELECT h.PurchaseInvoiceID AS InvoiceID, h.SupplierID AS PartyID, h.InvoiceNumber, h.InvoiceDate, h.DueDate,
       h.RemainingAmount, CAST(COALESCE(a.SumAllocated, 0) AS MONEY) AS Allocated, CAST(COALESCE(r.SumReturned, 0) AS MONEY) AS Returned,
       h.RemainingAmount - CAST(COALESCE(a.SumAllocated, 0) AS MONEY) - CAST(COALESCE(r.SumReturned, 0) AS MONEY) AS Free
FROM ([dbo].[PurchaseInvoices] AS h LEFT JOIN [en].[qrySupplierInvoiceAlloc] AS a ON h.PurchaseInvoiceID = a.PurchaseInvoiceID)
     LEFT JOIN [en].[qrySupplierInvoiceReturns] AS r ON h.PurchaseInvoiceID = r.PurchaseInvoiceID
WHERE h.RemainingAmount > 0;
GO
CREATE OR ALTER VIEW [en].[qryAgingDebits] AS
-- المستحق على كل عميل وللمورد بالمستند: الفواتير الآجلة والرصيد الافتتاحي
SELECT N'C' AS PartyKind, h.CustomerID AS PartyID, N'INVOICE' AS DocType, h.SalesInvoiceID AS DocID,
       h.InvoiceNumber AS DocNo, h.InvoiceDate AS DocDate, h.DueDate, c.PaymentTermsDays AS TermsDays,
       h.RemainingAmount AS Amount
FROM [dbo].[SalesInvoices] AS h INNER JOIN [en].[qryLocCustomers] AS c ON h.CustomerID = c.CustomerID
WHERE h.RemainingAmount > 0
UNION ALL
SELECT N'C', c.CustomerID, N'OPENING', c.CustomerID, N'Opening balance', c.OpeningOn, c.OpeningOn, 0, c.OpeningBalance
FROM [en].[qryCustomerOpening] AS c
WHERE c.OpeningBalance > 0
UNION ALL
SELECT N'S', h.SupplierID, N'INVOICE', h.PurchaseInvoiceID, h.InvoiceNumber, h.InvoiceDate, h.DueDate,
       s.PaymentTermsDays, h.RemainingAmount
FROM [dbo].[PurchaseInvoices] AS h INNER JOIN [en].[qryLocSuppliers] AS s ON h.SupplierID = s.SupplierID
WHERE h.RemainingAmount > 0
UNION ALL
SELECT N'S', s.SupplierID, N'OPENING', s.SupplierID, N'Opening balance', s.OpeningOn, s.OpeningOn, 0, s.OpeningBalance
FROM [en].[qrySupplierOpening] AS s
WHERE s.OpeningBalance > 0;
GO
CREATE OR ALTER VIEW [en].[qryAgingCredits] AS
-- ما يسدد المستحق: المرتجعات (على فاتورتها أولًا) والسندات والرصيد الافتتاحي الدائن
SELECT N'C' AS PartyKind, r.CustomerID AS PartyID, N'RETURN' AS CreditType, r.SalesReturnID AS CreditID,
       r.ReturnNumber AS CreditNo, r.ReturnDate AS CreditDate, r.TotalAmount - r.RefundedAmount AS Amount,
       r.SalesInvoiceID AS TargetID
FROM [dbo].[SalesReturns] AS r
WHERE r.TotalAmount - r.RefundedAmount > 0
UNION ALL
SELECT N'C', p.CustomerID, N'PAYMENT', p.PaymentID, p.PaymentNumber, p.PaymentDate, p.Amount, 0
FROM [dbo].[CustomerPayments] AS p
UNION ALL
SELECT N'C', c.CustomerID, N'OPENING', c.CustomerID, N'Opening balance', c.OpeningOn, -c.OpeningBalance, 0
FROM [en].[qryCustomerOpening] AS c
WHERE c.OpeningBalance < 0
UNION ALL
SELECT N'S', r.SupplierID, N'RETURN', r.PurchaseReturnID, r.ReturnNumber, r.ReturnDate, r.TotalAmount - r.RefundedAmount,
       r.PurchaseInvoiceID
FROM [dbo].[PurchaseReturns] AS r
WHERE r.TotalAmount - r.RefundedAmount > 0
UNION ALL
SELECT N'S', p.SupplierID, N'PAYMENT', p.PaymentID, p.PaymentNumber, p.PaymentDate, p.Amount, 0
FROM [dbo].[SupplierPayments] AS p
UNION ALL
SELECT N'S', s.SupplierID, N'OPENING', s.SupplierID, N'Opening balance', s.OpeningOn, -s.OpeningBalance, 0
FROM [en].[qrySupplierOpening] AS s
WHERE s.OpeningBalance < 0
UNION ALL
SELECT N'C', q.CustomerID, N'CHEQUE', q.ChequeID, q.ChequeNo, q.IssueDate, q.Amount, 0
FROM [dbo].[Cheques] AS q
WHERE q.Direction = N'IN' AND q.Status <> N'BOUNCED'
UNION ALL
SELECT N'S', q.SupplierID, N'CHEQUE', q.ChequeID, q.ChequeNo, q.IssueDate, q.Amount, 0
FROM [dbo].[Cheques] AS q
WHERE q.Direction = N'OUT' AND q.Status <> N'BOUNCED';
GO
CREATE OR ALTER VIEW [en].[qryAgingAllocations] AS
-- ربط السندات بالفواتير (ومنها السند المسجل عن فاتورة قبل الربط)
SELECT N'C' AS PartyKind, p.CustomerID AS PartyID, a.PaymentID, a.SalesInvoiceID AS InvoiceID, a.Amount
FROM [dbo].[CustomerAllocations] AS a INNER JOIN [dbo].[CustomerPayments] AS p ON a.PaymentID = p.PaymentID
UNION ALL
SELECT N'C', p.CustomerID, p.PaymentID, p.SalesInvoiceID, p.Amount
FROM [dbo].[CustomerPayments] AS p LEFT JOIN [en].[qryCustomerAllocSums] AS s ON p.PaymentID = s.PaymentID
WHERE p.SalesInvoiceID Is Not Null AND s.PaymentID Is Null
UNION ALL
SELECT N'S', p.SupplierID, a.PaymentID, a.PurchaseInvoiceID, a.Amount
FROM [dbo].[SupplierAllocations] AS a INNER JOIN [dbo].[SupplierPayments] AS p ON a.PaymentID = p.PaymentID
UNION ALL
SELECT N'S', p.SupplierID, p.PaymentID, p.PurchaseInvoiceID, p.Amount
FROM [dbo].[SupplierPayments] AS p LEFT JOIN [en].[qrySupplierAllocSums] AS s ON p.PaymentID = s.PaymentID
WHERE p.PurchaseInvoiceID Is Not Null AND s.PaymentID Is Null;
GO
CREATE OR ALTER VIEW [en].[ExpensesQuery] AS
-- المصروفات خلال فترة
SELECT e.ExpenseID, e.ExpenseNumber, e.ExpenseDate, t.ExpenseTypeName, e.Amount, e.Tax,
       e.TotalAmount, pm.MethodName, e.Description, em.EmployeeName, e.ExpenseTypeID
FROM (([dbo].[Expenses] AS e INNER JOIN [en].[qryLocExpenseTypes] AS t ON e.ExpenseTypeID = t.ExpenseTypeID)
      INNER JOIN [dbo].[Employees] AS em ON e.EmployeeID = em.EmployeeID)
     LEFT JOIN [en].[qryLocPaymentMethods] AS pm ON e.PaymentMethodID = pm.PaymentMethodID CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE e.ExpenseDate >= qp.[qp_PeriodStart] AND e.ExpenseDate < qp.[qp_PeriodEnd];
GO
CREATE OR ALTER VIEW [en].[ExpensesByTypeQuery] AS
-- المصروفات مجمّعة حسب النوع خلال فترة
SELECT t.ExpenseTypeName, Count(*) AS ExpenseCount, Sum(e.Amount) AS AmountExVAT,
       Sum(e.Tax) AS InputVAT, Sum(e.TotalAmount) AS AmountTotal
FROM [dbo].[Expenses] AS e INNER JOIN [en].[qryLocExpenseTypes] AS t ON e.ExpenseTypeID = t.ExpenseTypeID CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE e.ExpenseDate >= qp.[qp_PeriodStart] AND e.ExpenseDate < qp.[qp_PeriodEnd]
GROUP BY t.ExpenseTypeName;
GO
CREATE OR ALTER VIEW [en].[qryProfitSales] AS
-- صافي المبيعات وتكلفتها خلال الفترة
SELECT CAST(COALESCE(Sum(LineNet), 0) AS MONEY) AS PeriodNetSales, CAST(COALESCE(Sum(LineCost), 0) AS MONEY) AS PeriodCost
FROM [en].[qrySalesLinesInPeriod];
GO
CREATE OR ALTER VIEW [en].[qryProfitAdjustments] AS
-- قيمة فروقات المخزون (جرد، إضافة، خصم) خلال الفترة
SELECT CAST(COALESCE(Sum(t.Quantity * t.UnitCost), 0) AS MONEY) AS PeriodAdjustments
FROM [dbo].[InventoryTransactions] AS t INNER JOIN [dbo].[TransactionTypes] AS tt
     ON t.TransactionTypeID = tt.TransactionTypeID CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE tt.TypeCode IN (N'STOCK_IN', N'STOCK_OUT', N'ADJUSTMENT') AND t.TransactionDate >= qp.[qp_PeriodStart] AND t.TransactionDate < qp.[qp_PeriodEnd];
GO
CREATE OR ALTER VIEW [en].[qryProfitExpenses] AS
-- المصروفات (بدون ضريبة) خلال الفترة
SELECT CAST(COALESCE(Sum(Amount), 0) AS MONEY) AS PeriodExpenses
FROM [dbo].[Expenses] CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE ExpenseDate >= qp.[qp_PeriodStart] AND ExpenseDate < qp.[qp_PeriodEnd];
GO
CREATE OR ALTER VIEW [en].[ProfitQuery] AS
-- الأرباح: صافي المبيعات − التكلفة = مجمل الربح؛ ثم ± فروقات المخزون − المصروفات = صافي الربح
SELECT (SELECT p.[qp_PeriodStart] FROM [dbo].[QueryParamsNow] AS p) AS PeriodFrom, DATEADD(day, -1, (SELECT p.[qp_PeriodEnd] FROM [dbo].[QueryParamsNow] AS p)) AS PeriodTo,
       s.PeriodNetSales AS NetSales, s.PeriodCost AS CostOfSales,
       s.PeriodNetSales - s.PeriodCost AS GrossProfit,
       a.PeriodAdjustments AS InventoryAdjustments, x.PeriodExpenses AS TotalExpenses,
       s.PeriodNetSales - s.PeriodCost + a.PeriodAdjustments - x.PeriodExpenses AS NetProfit
FROM [en].[qryProfitSales] AS s, [en].[qryProfitAdjustments] AS a, [en].[qryProfitExpenses] AS x;
GO
CREATE OR ALTER VIEW [en].[qryVatOutput] AS
-- ضريبة المخرجات (المبيعات ناقص المرتجعات)
SELECT CAST(COALESCE(Sum(LineNet), 0) AS MONEY) AS TaxableSales, CAST(COALESCE(Sum(LineVAT), 0) AS MONEY) AS OutputVAT
FROM [en].[qrySalesLinesInPeriod];
GO
CREATE OR ALTER VIEW [en].[qryVatInputPurchases] AS
-- ضريبة المدخلات من المشتريات (ناقص المرتجعات)
SELECT CAST(COALESCE(Sum(NetAmount), 0) AS MONEY) AS TaxablePurchases, CAST(COALESCE(Sum(VATAmount), 0) AS MONEY) AS PurchaseVAT
FROM [en].[qryPurchaseDocuments] CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE DocDate >= qp.[qp_PeriodStart] AND DocDate < qp.[qp_PeriodEnd];
GO
CREATE OR ALTER VIEW [en].[qryVatInputExpenses] AS
-- ضريبة المدخلات من المصروفات
SELECT CAST(COALESCE(Sum(Tax), 0) AS MONEY) AS ExpenseVAT
FROM [dbo].[Expenses] CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE ExpenseDate >= qp.[qp_PeriodStart] AND ExpenseDate < qp.[qp_PeriodEnd];
GO
CREATE OR ALTER VIEW [en].[VatSummaryQuery] AS
-- ملخص ضريبة القيمة المضافة للفترة (للإقرار الضريبي)
SELECT (SELECT p.[qp_PeriodStart] FROM [dbo].[QueryParamsNow] AS p) AS PeriodFrom, DATEADD(day, -1, (SELECT p.[qp_PeriodEnd] FROM [dbo].[QueryParamsNow] AS p)) AS PeriodTo,
       o.TaxableSales, o.OutputVAT, p.TaxablePurchases, p.PurchaseVAT, e.ExpenseVAT,
       p.PurchaseVAT + e.ExpenseVAT AS InputVAT,
       o.OutputVAT - p.PurchaseVAT - e.ExpenseVAT AS NetVATDue
FROM [en].[qryVatOutput] AS o, [en].[qryVatInputPurchases] AS p, [en].[qryVatInputExpenses] AS e;
GO
CREATE OR ALTER VIEW [en].[qryVatReturnLines] AS
-- أسطر الإقرار الضريبي: المبيعات والمشتريات والمصروفات بفئتها الضريبية
SELECT N'S' AS Side, d.VATCategory AS Category, h.InvoiceDate AS DocDate, d.NetAmount AS Amount,
       CAST(0 AS MONEY) AS Adjust, d.Tax AS VAT
FROM [dbo].[SalesInvoices] AS h INNER JOIN [dbo].[SalesInvoiceDetails] AS d ON h.SalesInvoiceID = d.SalesInvoiceID
UNION ALL
SELECT N'S', d.VATCategory, r.ReturnDate, CAST(0 AS MONEY), -d.NetAmount, -d.Tax
FROM [dbo].[SalesReturns] AS r INNER JOIN [dbo].[SalesReturnDetails] AS d ON r.SalesReturnID = d.SalesReturnID
UNION ALL
SELECT N'P', IIF(d.VATRate > 0, N'S', N'Z'), h.InvoiceDate, d.NetAmount, CAST(0 AS MONEY), d.Tax
FROM [dbo].[PurchaseInvoices] AS h INNER JOIN [dbo].[PurchaseInvoiceDetails] AS d ON h.PurchaseInvoiceID = d.PurchaseInvoiceID
UNION ALL
SELECT N'P', IIF(d.VATRate > 0, N'S', N'Z'), r.ReturnDate, CAST(0 AS MONEY), -d.NetAmount, -d.Tax
FROM [dbo].[PurchaseReturns] AS r INNER JOIN [dbo].[PurchaseReturnDetails] AS d ON r.PurchaseReturnID = d.PurchaseReturnID
UNION ALL
SELECT N'P', N'S', e.ExpenseDate, e.Amount, CAST(0 AS MONEY), e.Tax
FROM [dbo].[Expenses] AS e
WHERE e.Tax <> 0
UNION ALL
SELECT N'P', N'S', a.PurchaseDate, a.Cost, CAST(0 AS MONEY), a.InputVAT
FROM [dbo].[FixedAssets] AS a
WHERE a.InputVAT <> 0 AND a.SourceType <> N'OPENING'
UNION ALL
SELECT N'S', N'S', a.DisposalDate, a.DisposalProceeds, CAST(0 AS MONEY), a.DisposalVAT
FROM [dbo].[FixedAssets] AS a
WHERE a.Status = N'DISPOSED' AND a.DisposalVAT <> 0;
GO
CREATE OR ALTER VIEW [en].[qryVatReturnTotals] AS
-- خانات الإقرار الضريبي للفترة محسوبة من المستندات (صف واحد)
SELECT CAST(COALESCE(Sum(IIF(Side = N'S' AND Category = N'S', Amount, 0)), 0) AS MONEY) AS SalesStdAmount,
       CAST(COALESCE(Sum(IIF(Side = N'S' AND Category = N'S', Adjust, 0)), 0) AS MONEY) AS SalesStdAdjust,
       CAST(COALESCE(Sum(IIF(Side = N'S' AND Category = N'S', VAT, 0)), 0) AS MONEY) AS SalesStdVAT,
       CAST(COALESCE(Sum(IIF(Side = N'S' AND Category = N'Z', Amount, 0)), 0) AS MONEY) AS SalesZeroAmount,
       CAST(COALESCE(Sum(IIF(Side = N'S' AND Category = N'Z', Adjust, 0)), 0) AS MONEY) AS SalesZeroAdjust,
       CAST(COALESCE(Sum(IIF(Side = N'S' AND Category = N'E', Amount, 0)), 0) AS MONEY) AS SalesExemptAmount,
       CAST(COALESCE(Sum(IIF(Side = N'S' AND Category = N'E', Adjust, 0)), 0) AS MONEY) AS SalesExemptAdjust,
       CAST(COALESCE(Sum(IIF(Side = N'P' AND Category = N'S', Amount, 0)), 0) AS MONEY) AS PurchStdAmount,
       CAST(COALESCE(Sum(IIF(Side = N'P' AND Category = N'S', Adjust, 0)), 0) AS MONEY) AS PurchStdAdjust,
       CAST(COALESCE(Sum(IIF(Side = N'P' AND Category = N'S', VAT, 0)), 0) AS MONEY) AS PurchStdVAT,
       CAST(COALESCE(Sum(IIF(Side = N'P' AND Category = N'Z', Amount, 0)), 0) AS MONEY) AS PurchZeroAmount,
       CAST(COALESCE(Sum(IIF(Side = N'P' AND Category = N'Z', Adjust, 0)), 0) AS MONEY) AS PurchZeroAdjust
FROM [en].[qryVatReturnLines] CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE DocDate >= qp.[qp_PeriodStart] AND DocDate < qp.[qp_PeriodEnd];
GO
CREATE OR ALTER VIEW [en].[qryVatReturnHead] AS
-- الإقرار الضريبي المختار
SELECT [dbo].[VatReturns].* FROM [dbo].[VatReturns] CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE VatReturnID = qp.[qp_VatReturnID];
GO
CREATE OR ALTER VIEW [en].[VatReturnQuery] AS
-- إقرار ضريبة القيمة المضافة بخانات نموذج الهيئة (1 إلى 16)
SELECT 1 AS BoxNo, N'Sales at the standard rate (15%)' AS BoxText, v.SalesStdAmount AS Amount, v.SalesStdAdjust AS Adjust, v.SalesStdVAT AS VAT, N'L' AS RowKind, v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 2, N'Sales to citizens (private health care, private education and first home)', CAST(0 AS MONEY), CAST(0 AS MONEY), CAST(0 AS MONEY), N'L', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 3, N'Domestic zero-rated sales', v.SalesZeroAmount, v.SalesZeroAdjust, CAST(0 AS MONEY), N'L', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 4, N'Exports', CAST(0 AS MONEY), CAST(0 AS MONEY), CAST(0 AS MONEY), N'L', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 5, N'Exempt sales', v.SalesExemptAmount, v.SalesExemptAdjust, CAST(0 AS MONEY), N'L', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 6, N'Total sales', v.SalesStdAmount + v.SalesZeroAmount + v.SalesExemptAmount, v.SalesStdAdjust + v.SalesZeroAdjust + v.SalesExemptAdjust, v.SalesStdVAT, N'T', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 7, N'Purchases at the standard rate (with expenses with a tax invoice)', v.PurchStdAmount, v.PurchStdAdjust, v.PurchStdVAT, N'L', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 8, N'Imports subject to the standard rate with VAT paid at customs', CAST(0 AS MONEY), CAST(0 AS MONEY), CAST(0 AS MONEY), N'L', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 9, N'Imports subject to VAT under the reverse charge', CAST(0 AS MONEY), CAST(0 AS MONEY), CAST(0 AS MONEY), N'L', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 10, N'Zero-rated purchases', v.PurchZeroAmount, v.PurchZeroAdjust, CAST(0 AS MONEY), N'L', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 11, N'Exempt purchases', CAST(0 AS MONEY), CAST(0 AS MONEY), CAST(0 AS MONEY), N'L', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 12, N'Total purchases', v.PurchStdAmount + v.PurchZeroAmount, v.PurchStdAdjust + v.PurchZeroAdjust, v.PurchStdVAT, N'T', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 13, N'Total VAT due for the current period', Null, Null, v.SalesStdVAT - v.PurchStdVAT, N'N', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 14, N'Corrections from previous periods', Null, Null, v.Corrections, N'N', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 15, N'VAT carried from previous periods (credit balance)', Null, Null, v.CarriedCredit, N'N', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 16, N'Net VAT due (negative = Refunded)', Null, Null, v.NetDue, N'N', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v;
GO
CREATE OR ALTER VIEW [en].[VatReturnQueryEG] AS
-- إقرار ضريبة القيمة المضافة المصري (نموذج 10) بنفس أرقام الإقرار
SELECT 1 AS BoxNo, N'Local sales taxed at the general rate' AS BoxText, v.SalesStdAmount AS Amount, v.SalesStdAdjust AS Adjust, v.SalesStdVAT AS VAT, N'L' AS RowKind, v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 2, N'Sales of schedule goods and services', CAST(0 AS MONEY), CAST(0 AS MONEY), CAST(0 AS MONEY), N'L', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 3, N'Exports (zero rate)', v.SalesZeroAmount, v.SalesZeroAdjust, CAST(0 AS MONEY), N'L', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 4, N'Exempt sales', v.SalesExemptAmount, v.SalesExemptAdjust, CAST(0 AS MONEY), N'L', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 5, N'Total sales', v.SalesStdAmount + v.SalesZeroAmount + v.SalesExemptAmount, v.SalesStdAdjust + v.SalesZeroAdjust + v.SalesExemptAdjust, v.SalesStdVAT, N'T', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 6, N'Local purchases taxed at the general rate (with expenses on a tax invoice)', v.PurchStdAmount, v.PurchStdAdjust, v.PurchStdVAT, N'L', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 7, N'Imported goods (VAT paid at customs)', CAST(0 AS MONEY), CAST(0 AS MONEY), CAST(0 AS MONEY), N'L', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 8, N'Services imported from abroad', CAST(0 AS MONEY), CAST(0 AS MONEY), CAST(0 AS MONEY), N'L', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 9, N'Exempt and non-taxable purchases', v.PurchZeroAmount, v.PurchZeroAdjust, CAST(0 AS MONEY), N'L', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 10, N'Total purchases', v.PurchStdAmount + v.PurchZeroAmount, v.PurchStdAdjust + v.PurchZeroAdjust, v.PurchStdVAT, N'T', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 11, N'Output VAT less deductible input VAT of the month', Null, Null, v.SalesStdVAT - v.PurchStdVAT, N'N', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 12, N'Adjustments and corrections of earlier periods', Null, Null, v.Corrections, N'N', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 13, N'Credit balance carried from the previous month', Null, Null, v.CarriedCredit, N'N', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v
UNION ALL
SELECT 14, N'Net VAT due (negative = a credit balance carried to the next month)', Null, Null, v.NetDue, N'N', v.VatReturnID, v.ReturnNumber, v.PeriodFrom, v.PeriodTo, v.Status, v.FiledDate, v.FilingRef, v.PaidDate, v.PaidAmount
FROM [en].[qryVatReturnHead] AS v;
GO
CREATE OR ALTER VIEW [en].[DashboardQuery] AS
-- مؤشرات لوحة التحكم في سجل واحد (اليوم، الشهر، الأرصدة، المخزون)
SELECT (SELECT CAST(COALESCE(Sum(d.GrossAmount), 0) AS MONEY) FROM [en].[qrySalesDocuments] AS d CROSS JOIN [dbo].[QueryParamsNow] AS qp
        WHERE d.DocDate >= qp.[qp_DashDay] AND d.DocDate < qp.[qp_DashEnd]) AS TodaySales,
       (SELECT Count(*) FROM [dbo].[SalesInvoices] AS h CROSS JOIN [dbo].[QueryParamsNow] AS qp
        WHERE h.InvoiceDate >= qp.[qp_DashDay] AND h.InvoiceDate < qp.[qp_DashEnd]) AS TodayInvoices,
       (SELECT CAST(COALESCE(Sum(d.GrossAmount), 0) AS MONEY) FROM [en].[qrySalesDocuments] AS d CROSS JOIN [dbo].[QueryParamsNow] AS qp
        WHERE d.DocDate >= qp.[qp_DashMonth] AND d.DocDate < qp.[qp_DashEnd]) AS MonthSales,
       (SELECT CAST(COALESCE(Sum(d.VATAmount), 0) AS MONEY) FROM [en].[qrySalesDocuments] AS d CROSS JOIN [dbo].[QueryParamsNow] AS qp
        WHERE d.DocDate >= qp.[qp_DashMonth] AND d.DocDate < qp.[qp_DashEnd]) AS MonthVAT,
       (SELECT Count(*) FROM [dbo].[SalesInvoices] AS h CROSS JOIN [dbo].[QueryParamsNow] AS qp
        WHERE h.InvoiceDate >= qp.[qp_DashMonth] AND h.InvoiceDate < qp.[qp_DashEnd]) AS MonthInvoices,
       (SELECT CAST(COALESCE(Sum(e.Amount), 0) AS MONEY) FROM [dbo].[Expenses] AS e CROSS JOIN [dbo].[QueryParamsNow] AS qp
        WHERE e.ExpenseDate >= qp.[qp_DashMonth] AND e.ExpenseDate < qp.[qp_DashEnd]) AS MonthExpenses,
       (SELECT CAST(COALESCE(Sum(c.CurrentBalance), 0) AS MONEY) FROM [dbo].[Customers] AS c WHERE c.CurrentBalance > 0) AS CustomerDebt,
       (SELECT Count(*) FROM [dbo].[Customers] AS c WHERE c.CurrentBalance > 0) AS DebtorCount,
       (SELECT CAST(COALESCE(Sum(s.CurrentBalance), 0) AS MONEY) FROM [dbo].[Suppliers] AS s WHERE s.CurrentBalance > 0) AS SupplierDue,
       (SELECT CAST(COALESCE(Sum(p.CurrentQuantity * p.AverageCost), 0) AS MONEY) FROM [dbo].[Products] AS p
        WHERE p.IsActive <> 0 AND p.CurrentQuantity > 0) AS StockValue,
       (SELECT Count(*) FROM [en].[LowStockQuery]) AS LowStockCount
FROM [dbo].[Settings] AS st
WHERE st.SettingID = 1;
GO
CREATE OR ALTER VIEW [en].[qryRepDocs] AS
-- عمليات المندوبين: صافي المبيعات بدون الضريبة والتحصيل
SELECT h.SalesRepID, h.InvoiceDate AS DocDate, h.TaxableAmount AS NetSales, h.PaidAmount AS Collected
FROM [dbo].[SalesInvoices] AS h
WHERE h.SalesRepID Is Not Null
UNION ALL
SELECT r.SalesRepID, r.ReturnDate, -r.TaxableAmount, -r.RefundedAmount
FROM [dbo].[SalesReturns] AS r
WHERE r.SalesRepID Is Not Null
UNION ALL
SELECT p.SalesRepID, p.PaymentDate, CAST(0 AS MONEY), p.Amount
FROM [dbo].[CustomerPayments] AS p
WHERE p.SalesRepID Is Not Null;
GO
CREATE OR ALTER VIEW [en].[qryRepPeriodTotals] AS
-- مبيعات وتحصيل كل مندوب في الفترة
SELECT SalesRepID, Sum(NetSales) AS SumSales, Sum(Collected) AS SumCollected
FROM [en].[qryRepDocs] CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE DocDate >= qp.[qp_PeriodStart] AND DocDate < qp.[qp_PeriodEnd]
GROUP BY SalesRepID;
GO
CREATE OR ALTER VIEW [en].[qryRepTargetTotals] AS
-- أهداف كل مندوب في أشهر الفترة
SELECT SalesRepID, Sum(TargetAmount) AS SumTarget
FROM [dbo].[SalesRepTargets] CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE TargetYear * 100 + TargetMonth >= YEAR(qp.[qp_PeriodStart]) * 100 + MONTH(qp.[qp_PeriodStart])
  AND TargetYear * 100 + TargetMonth <= YEAR(DATEADD(day, -1, qp.[qp_PeriodEnd])) * 100
                                        + MONTH(DATEADD(day, -1, qp.[qp_PeriodEnd]))
GROUP BY SalesRepID;
GO
CREATE OR ALTER VIEW [en].[qryRepCommissionPaid] AS
-- ما صُرف لكل مندوب من عمولاته (سندات صرف النقدية)
SELECT SalesRepID, Sum(Amount) AS SumPaid
FROM [dbo].[CashVouchers]
WHERE Category = N'COMMISSION' AND SalesRepID Is Not Null
GROUP BY SalesRepID;
GO
CREATE OR ALTER VIEW [en].[qryRepCommissionPosted] AS
-- العمولات المرحَّلة لكل مندوب
SELECT l.SalesRepID, Sum(l.Commission) AS SumPosted
FROM [dbo].[CommissionLines] AS l INNER JOIN [dbo].[CommissionRuns] AS r ON l.CommissionRunID = r.CommissionRunID
WHERE r.Status = N'POSTED'
GROUP BY l.SalesRepID;
GO
CREATE OR ALTER VIEW [en].[RepPerformanceQuery] AS
-- أداء المندوبين في الفترة: المبيعات والتحصيل والهدف والإنجاز والعمولة المتوقعة
SELECT s.SalesRepID, s.RepCode, s.RepName, s.Region, s.IsActive, s.CommissionRate, s.CommissionBase,
       CAST(COALESCE(t.SumSales, 0) AS MONEY) AS NetSales, CAST(COALESCE(t.SumCollected, 0) AS MONEY) AS Collections, CAST(COALESCE(g.SumTarget, 0) AS MONEY) AS Target,
       IIF(CAST(COALESCE(g.SumTarget, 0) AS MONEY) = 0, Null, CAST(COALESCE(t.SumSales, 0) AS MONEY) * 1e0 / CAST(COALESCE(g.SumTarget, 0) AS MONEY)) AS Achievement,
       IIF(s.CommissionBase = N'COLLECTION', CAST(COALESCE(t.SumCollected, 0) AS MONEY), CAST(COALESCE(t.SumSales, 0) AS MONEY)) AS BaseAmount,
       IIF(IIF(s.CommissionBase = N'COLLECTION', CAST(COALESCE(t.SumCollected, 0) AS MONEY), CAST(COALESCE(t.SumSales, 0) AS MONEY)) > 0, ROUND(IIF(s.CommissionBase = N'COLLECTION', CAST(COALESCE(t.SumCollected, 0) AS MONEY), CAST(COALESCE(t.SumSales, 0) AS MONEY)) * s.CommissionRate, 2), 0) AS Commission
FROM ([en].[qryLocSalesReps] AS s LEFT JOIN [en].[qryRepPeriodTotals] AS t ON s.SalesRepID = t.SalesRepID)
     LEFT JOIN [en].[qryRepTargetTotals] AS g ON s.SalesRepID = g.SalesRepID
WHERE s.IsActive <> 0 OR CAST(COALESCE(t.SumSales, 0) AS MONEY) <> 0 OR CAST(COALESCE(t.SumCollected, 0) AS MONEY) <> 0;
GO
CREATE OR ALTER VIEW [en].[RepCustomersQuery] AS
-- عملاء كل مندوب وأرصدتهم
SELECT s.SalesRepID, s.RepName, c.CustomerID, c.CustomerName, c.Mobile, b.Balance
FROM ([en].[qryLocCustomers] AS c INNER JOIN [en].[qryLocSalesReps] AS s ON c.SalesRepID = s.SalesRepID)
     INNER JOIN [en].[CustomerBalanceQuery] AS b ON c.CustomerID = b.CustomerID;
GO
CREATE OR ALTER VIEW [en].[RepCommissionBalanceQuery] AS
-- العمولات المستحقة لكل مندوب: المرحَّل والمصروف والباقي
SELECT s.SalesRepID, s.RepCode, s.RepName, CAST(COALESCE(p.SumPosted, 0) AS MONEY) AS Posted, CAST(COALESCE(d.SumPaid, 0) AS MONEY) AS Paid,
       CAST(COALESCE(p.SumPosted, 0) AS MONEY) - CAST(COALESCE(d.SumPaid, 0) AS MONEY) AS Payable
FROM ([en].[qryLocSalesReps] AS s LEFT JOIN [en].[qryRepCommissionPosted] AS p ON s.SalesRepID = p.SalesRepID)
     LEFT JOIN [en].[qryRepCommissionPaid] AS d ON s.SalesRepID = d.SalesRepID;
GO
CREATE OR ALTER VIEW [en].[CommissionSheetQuery] AS
-- مسير العمولات المختار بأسطر المندوبين
SELECT r.CommissionRunID, r.RunNumber, r.RunMonth, r.Status, l.SalesRepID, l.RepName, l.NetSales, l.Collections,
       IIF(l.CommissionBase = N'COLLECTION', N'Collections', N'Sales') AS BaseName, l.BaseAmount, l.CommissionRate,
       l.Adjustment, l.Commission, l.Notes
FROM [dbo].[CommissionRuns] AS r INNER JOIN [dbo].[CommissionLines] AS l ON r.CommissionRunID = l.CommissionRunID CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE r.CommissionRunID = qp.[qp_CommissionRunID];
GO
CREATE OR ALTER VIEW [en].[qryIndicatorLines] AS
-- أسطر القيود مع مجموعة الحساب (المستوى 2) لحساب المؤشرات المالية
SELECT l.AccountCode, a.Level2Code, e.EntryDate, e.SourceType, l.Debit, l.Credit
FROM ([dbo].[JournalLines] AS l INNER JOIN [dbo].[JournalEntries] AS e ON l.EntryID = e.EntryID)
     INNER JOIN [dbo].[Accounts] AS a ON l.AccountCode = a.AccountCode;
GO
CREATE OR ALTER VIEW [en].[FinancialIndicatorsQuery] AS
-- المؤشرات المالية (صف واحد): هامش الربح، دوران المخزون، فترة التحصيل، السيولة
SELECT CAST(COALESCE(Sum(IIF(i.Level2Code = 41 AND i.EntryDate >= qp.[qp_IndMonth] AND i.EntryDate < qp.[qp_IndEnd] AND i.SourceType <> N'YEAR_CLOSE', i.Credit - i.Debit, 0)), 0) AS MONEY) AS MonthSales,
       CAST(COALESCE(Sum(IIF(i.Level2Code = 51 AND i.EntryDate >= qp.[qp_IndMonth] AND i.EntryDate < qp.[qp_IndEnd] AND i.SourceType <> N'YEAR_CLOSE', i.Debit - i.Credit, 0)), 0) AS MONEY) AS MonthCost,
       CAST(COALESCE(Sum(IIF(i.Level2Code = 41 AND i.EntryDate >= qp.[qp_IndPrevMonth] AND i.EntryDate < qp.[qp_IndMonth] AND i.SourceType <> N'YEAR_CLOSE', i.Credit - i.Debit, 0)), 0) AS MONEY) AS PrevSales,
       CAST(COALESCE(Sum(IIF(i.Level2Code = 51 AND i.EntryDate >= qp.[qp_IndPrevMonth] AND i.EntryDate < qp.[qp_IndMonth] AND i.SourceType <> N'YEAR_CLOSE', i.Debit - i.Credit, 0)), 0) AS MONEY) AS PrevCost,
       CAST(COALESCE(Sum(IIF(i.Level2Code = 51 AND i.EntryDate >= qp.[qp_IndYear] AND i.EntryDate < qp.[qp_IndEnd] AND i.SourceType <> N'YEAR_CLOSE', i.Debit - i.Credit, 0)), 0) AS MONEY) AS YearCost,
       CAST(COALESCE(Sum(IIF((i.AccountCode = 1400 OR i.AccountCode BETWEEN 140001 AND 149999) AND i.EntryDate < qp.[qp_IndYear], i.Debit - i.Credit, 0)), 0) AS MONEY) AS StockStart,
       CAST(COALESCE(Sum(IIF((i.AccountCode = 1400 OR i.AccountCode BETWEEN 140001 AND 149999) AND i.EntryDate < qp.[qp_IndEnd], i.Debit - i.Credit, 0)), 0) AS MONEY) AS StockEnd,
       CAST(COALESCE(Sum(IIF(i.AccountCode = 1300 AND i.EntryDate < qp.[qp_IndEnd], i.Debit - i.Credit, 0)), 0) AS MONEY) AS Receivables,
       CAST(COALESCE(Sum(IIF(i.AccountCode = 1300 AND i.SourceType = N'SALE' AND i.EntryDate >= qp.[qp_Ind90] AND i.EntryDate < qp.[qp_IndEnd], i.Debit, 0)), 0) AS MONEY) AS CreditSales,
       CAST(COALESCE(Sum(IIF(i.Level2Code = 11 AND i.EntryDate < qp.[qp_IndEnd], i.Debit - i.Credit, 0)), 0) AS MONEY) AS CurrentAssets,
       CAST(COALESCE(Sum(IIF(i.Level2Code = 21 AND i.EntryDate < qp.[qp_IndEnd], i.Credit - i.Debit, 0)), 0) AS MONEY) AS CurrentLiabilities
FROM [en].[qryIndicatorLines] AS i CROSS JOIN [dbo].[QueryParamsNow] AS qp;
GO
CREATE OR ALTER VIEW [en].[qryDashboardTopProducts] AS
-- صافي الكمية المباعة لكل منتج منذ بداية الشهر (لوحة التحكم)
SELECT l.ProductID, p.ProductName, Sum(l.SignedQty) AS NetQty, Sum(l.LineGross) AS NetSales
FROM [en].[qrySalesLineItems] AS l INNER JOIN [dbo].[Products] AS p ON l.ProductID = p.ProductID CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE l.DocDate >= qp.[qp_DashMonth] AND l.DocDate < qp.[qp_DashEnd]
GROUP BY l.ProductID, p.ProductName
HAVING Sum(l.SignedQty) > 0;
GO
CREATE OR ALTER VIEW [en].[qryEInvoiceDocs] AS
-- مستندات البيع وحالة الفاتورة الإلكترونية (الفواتير والمرتجعات)
SELECT N'SALE' AS DocKind, h.SalesInvoiceID AS DocID, h.InvoiceNumber AS DocNumber, h.InvoiceDate AS DocDate,
       N'Sales invoice' AS DocKindName, c.CustomerName, h.TotalAmount, h.ZatcaStatus AS EStatus,
       IIF(h.ZatcaStatus = N'PENDING', N'Waiting to be sent', IIF(h.ZatcaStatus = N'REPORTED', N'Reported', IIF(h.ZatcaStatus = N'CLEARED', N'Approved', IIF(h.ZatcaStatus = N'WARNING', N'Accepted with a warning', IIF(h.ZatcaStatus = N'REJECTED', N'Rejected', IIF(h.ZatcaStatus = N'SUBMITTED', N'Submitted', IIF(h.ZatcaStatus = N'VALID', N'Valid', IIF(h.ZatcaStatus = N'INVALID', N'Invalid', IIF(h.ZatcaStatus = N'CANCELLED', N'Cancelled', N'Not sent'))))))))) AS StatusName,
       COALESCE(h.EInvoiceAttempts, 0) AS Attempts, h.EInvoiceError AS LastError, h.ICV, h.InvoiceSubType
FROM [dbo].[SalesInvoices] AS h INNER JOIN [en].[qryLocCustomers] AS c ON h.CustomerID = c.CustomerID
UNION ALL
SELECT N'RETURN', r.SalesReturnID, r.ReturnNumber, r.ReturnDate, N'Sales return', c.CustomerName, r.TotalAmount,
       r.ZatcaStatus, IIF(r.ZatcaStatus = N'PENDING', N'Waiting to be sent', IIF(r.ZatcaStatus = N'REPORTED', N'Reported', IIF(r.ZatcaStatus = N'CLEARED', N'Approved', IIF(r.ZatcaStatus = N'WARNING', N'Accepted with a warning', IIF(r.ZatcaStatus = N'REJECTED', N'Rejected', IIF(r.ZatcaStatus = N'SUBMITTED', N'Submitted', IIF(r.ZatcaStatus = N'VALID', N'Valid', IIF(r.ZatcaStatus = N'INVALID', N'Invalid', IIF(r.ZatcaStatus = N'CANCELLED', N'Cancelled', N'Not sent'))))))))),
       COALESCE(r.EInvoiceAttempts, 0), r.EInvoiceError, r.ICV, r.InvoiceSubType
FROM [dbo].[SalesReturns] AS r INNER JOIN [en].[qryLocCustomers] AS c ON r.CustomerID = c.CustomerID;
GO
CREATE OR ALTER VIEW [en].[EInvoiceReportQuery] AS
-- تقرير مستندات الفاتورة الإلكترونية: الحالة ومجموعتها والمبلغ بإشارته
SELECT d.DocKind, d.DocID, d.DocNumber, d.DocDate, d.DocKindName, d.CustomerName, d.TotalAmount,
       IIF(d.DocKind = N'RETURN', -d.TotalAmount, d.TotalAmount) AS SignedTotal, d.EStatus, d.StatusName,
       d.Attempts, d.LastError,
       IIF(d.EStatus IN (N'REJECTED', N'INVALID'), 1, IIF(d.EStatus IN (N'PENDING', N'SUBMITTED'), 2, IIF(d.EStatus IN (N'REPORTED', N'CLEARED', N'WARNING', N'VALID'), 3, IIF(d.EStatus = N'CANCELLED', 4, 5)))) AS GroupNo
FROM [en].[qryEInvoiceDocs] AS d;
GO
CREATE OR ALTER VIEW [en].[qrySalesDocPrint] AS
-- بيانات طباعة فواتير البيع والإشعارات الدائنة (سطر لكل صنف)
SELECT N'SALE' AS DocKind, h.SalesInvoiceID AS DocID, h.InvoiceNumber AS DocNumber,
       h.InvoiceDate AS DocDate, N'' AS OriginalNumber, h.InvoiceSubType, h.PaymentType,
       h.CustomerID, c.CustomerName, c.VATNumber AS CustomerVAT, c.City AS CustomerCity,
       c.District AS CustomerDistrict, c.StreetName AS CustomerStreet,
       c.BuildingNo AS CustomerBuilding, c.PostalCode AS CustomerPostal, e.EmployeeName,
       h.SubTotal AS DocSubTotal, h.Discount AS DocDiscount, h.TaxableAmount, h.Tax AS DocTax,
       h.TotalAmount, h.PaidAmount, h.RemainingAmount, h.AmountTendered, h.ChangeDue,
       d.LineNumber, p.ProductName, p.ProductCode, u.UnitName, v.UnitName AS LineUnit,
       d.Quantity, d.UnitPrice,
       d.Discount AS LineDiscount, d.NetAmount, d.VATRate, d.Tax AS LineTax, d.LineTotal,
       h.OrderType, h.TableNo, h.OrderName, d.LineNote
FROM ((((([dbo].[SalesInvoices] AS h INNER JOIN [dbo].[SalesInvoiceDetails] AS d ON h.SalesInvoiceID = d.SalesInvoiceID)
       INNER JOIN [dbo].[Products] AS p ON d.ProductID = p.ProductID)
      INNER JOIN [dbo].[Units] AS u ON p.UnitID = u.UnitID)
     INNER JOIN [dbo].[Customers] AS c ON h.CustomerID = c.CustomerID)
    INNER JOIN [dbo].[Employees] AS e ON h.EmployeeID = e.EmployeeID)
    LEFT JOIN [dbo].[Units] AS v ON d.UnitID = v.UnitID
UNION ALL
SELECT N'RETURN', r.SalesReturnID, r.ReturnNumber, r.ReturnDate, o.InvoiceNumber, r.InvoiceSubType,
       r.RefundType, r.CustomerID, c.CustomerName, c.VATNumber, c.City, c.District, c.StreetName,
       c.BuildingNo, c.PostalCode, e.EmployeeName, r.SubTotal, r.Discount, r.TaxableAmount, r.Tax,
       r.TotalAmount, r.RefundedAmount, r.TotalAmount - r.RefundedAmount, CAST(0 AS MONEY), CAST(0 AS MONEY),
       rd.ReturnDetailID, p.ProductName, p.ProductCode, u.UnitName, v.UnitName,
       rd.Quantity, rd.UnitPrice,
       rd.Discount, rd.NetAmount, rd.VATRate, rd.Tax, rd.LineTotal, o.OrderType, o.TableNo, o.OrderName,
       od.LineNote
FROM ((((((([dbo].[SalesReturns] AS r INNER JOIN [dbo].[SalesReturnDetails] AS rd ON r.SalesReturnID = rd.SalesReturnID)
        INNER JOIN [dbo].[SalesInvoices] AS o ON r.SalesInvoiceID = o.SalesInvoiceID)
        INNER JOIN [dbo].[SalesInvoiceDetails] AS od ON rd.SalesDetailID = od.SalesDetailID)
       INNER JOIN [dbo].[Products] AS p ON rd.ProductID = p.ProductID)
      INNER JOIN [dbo].[Units] AS u ON p.UnitID = u.UnitID)
     INNER JOIN [dbo].[Customers] AS c ON r.CustomerID = c.CustomerID)
    INNER JOIN [dbo].[Employees] AS e ON r.EmployeeID = e.EmployeeID)
    LEFT JOIN [dbo].[Units] AS v ON rd.UnitID = v.UnitID;
GO
CREATE OR ALTER VIEW [en].[qryPurchaseDocPrint] AS
-- بيانات طباعة فواتير الشراء ومرتجعاتها (سطر لكل صنف)
SELECT N'PURCHASE' AS DocKind, h.PurchaseInvoiceID AS DocID, h.InvoiceNumber AS DocNumber,
       h.InvoiceDate AS DocDate, h.SupplierInvoiceNo, N'' AS OriginalNumber, h.PaymentType,
       N'' AS Reason, h.SupplierID, s.SupplierName, s.VATNumber AS SupplierVAT,
       s.Mobile AS SupplierMobile, e.EmployeeName, h.SubTotal AS DocSubTotal,
       h.Discount AS DocDiscount, h.TaxableAmount, h.Tax AS DocTax, h.TotalAmount,
       h.PaidAmount, h.RemainingAmount, d.LineNumber, p.ProductCode, p.ProductName,
       u.UnitName, v.UnitName AS LineUnit,
       d.Quantity, d.UnitCost, d.Discount AS LineDiscount, d.NetAmount, d.VATRate,
       d.Tax AS LineTax, d.LineTotal
FROM ((((([dbo].[PurchaseInvoices] AS h INNER JOIN [dbo].[PurchaseInvoiceDetails] AS d
         ON h.PurchaseInvoiceID = d.PurchaseInvoiceID)
       INNER JOIN [dbo].[Products] AS p ON d.ProductID = p.ProductID)
      INNER JOIN [en].[qryLocUnits] AS u ON p.UnitID = u.UnitID)
     INNER JOIN [en].[qryLocSuppliers] AS s ON h.SupplierID = s.SupplierID)
    INNER JOIN [dbo].[Employees] AS e ON h.EmployeeID = e.EmployeeID)
    LEFT JOIN [en].[qryLocUnits] AS v ON d.UnitID = v.UnitID
UNION ALL
SELECT N'RETURN', r.PurchaseReturnID, r.ReturnNumber, r.ReturnDate, o.SupplierInvoiceNo,
       o.InvoiceNumber, r.RefundType, r.Reason, r.SupplierID, s.SupplierName, s.VATNumber,
       s.Mobile, e.EmployeeName, r.SubTotal, r.Discount, r.TaxableAmount, r.Tax, r.TotalAmount,
       r.RefundedAmount, r.TotalAmount - r.RefundedAmount, od.LineNumber, p.ProductCode,
       p.ProductName, u.UnitName, v.UnitName, rd.Quantity, rd.UnitCost, rd.Discount, rd.NetAmount,
       rd.VATRate, rd.Tax, rd.LineTotal
FROM ((((((([dbo].[PurchaseReturns] AS r INNER JOIN [dbo].[PurchaseReturnDetails] AS rd
           ON r.PurchaseReturnID = rd.PurchaseReturnID)
         INNER JOIN [dbo].[PurchaseInvoiceDetails] AS od ON rd.PurchaseDetailID = od.PurchaseDetailID)
        INNER JOIN [dbo].[PurchaseInvoices] AS o ON r.PurchaseInvoiceID = o.PurchaseInvoiceID)
       INNER JOIN [dbo].[Products] AS p ON rd.ProductID = p.ProductID)
      INNER JOIN [en].[qryLocUnits] AS u ON p.UnitID = u.UnitID)
     INNER JOIN [en].[qryLocSuppliers] AS s ON r.SupplierID = s.SupplierID)
    INNER JOIN [dbo].[Employees] AS e ON r.EmployeeID = e.EmployeeID)
    LEFT JOIN [en].[qryLocUnits] AS v ON rd.UnitID = v.UnitID;
GO
CREATE OR ALTER VIEW [en].[qryVoucherPrint] AS
-- بيانات طباعة سندات القبض (من العملاء) وسندات الصرف (للموردين)
SELECT N'RECEIPT' AS DocKind, p.PaymentID AS DocID, p.PaymentNumber AS DocNumber,
       p.PaymentDate AS DocDate, 1 AS LineNumber, c.CustomerName AS PartyName,
       c.Mobile AS PartyMobile, p.Amount, m.MethodName, p.Notes, e.EmployeeName,
       c.CurrentBalance AS PartyBalance
FROM (([dbo].[CustomerPayments] AS p INNER JOIN [en].[qryLocCustomers] AS c ON p.CustomerID = c.CustomerID)
      INNER JOIN [en].[qryLocPaymentMethods] AS m ON p.PaymentMethodID = m.PaymentMethodID)
     INNER JOIN [dbo].[Employees] AS e ON p.EmployeeID = e.EmployeeID
UNION ALL
SELECT N'PAYMENT', p.PaymentID, p.PaymentNumber, p.PaymentDate, 1, s.SupplierName, s.Mobile,
       p.Amount, m.MethodName, p.Notes, e.EmployeeName, s.CurrentBalance
FROM (([dbo].[SupplierPayments] AS p INNER JOIN [en].[qryLocSuppliers] AS s ON p.SupplierID = s.SupplierID)
      INNER JOIN [en].[qryLocPaymentMethods] AS m ON p.PaymentMethodID = m.PaymentMethodID)
     INNER JOIN [dbo].[Employees] AS e ON p.EmployeeID = e.EmployeeID;
GO
CREATE OR ALTER VIEW [en].[qryCashMovements] AS
-- كل حركات النقدية في الخزينة والصناديق: داخل (+) وخارج (−)
SELECT h.CashBoxID, h.InvoiceDate AS MoveDate, N'SALE' AS MoveType, N'Sales invoice' AS MoveTypeName,
       h.InvoiceNumber AS DocNumber, c.CustomerName AS PartyName, h.Notes AS Details,
       h.PaidAmount AS AmountIn, CAST(0 AS MONEY) AS AmountOut, h.EmployeeID
FROM [dbo].[SalesInvoices] AS h INNER JOIN [en].[qryLocCustomers] AS c ON h.CustomerID = c.CustomerID
WHERE h.CashBoxID Is Not Null AND h.PaidAmount <> 0
UNION ALL
SELECT r.CashBoxID, r.ReturnDate, N'SALES_RETURN', N'Sales return (cash refund)', r.ReturnNumber,
       c.CustomerName, r.Reason, CAST(0 AS MONEY), r.RefundedAmount, r.EmployeeID
FROM [dbo].[SalesReturns] AS r INNER JOIN [en].[qryLocCustomers] AS c ON r.CustomerID = c.CustomerID
WHERE r.CashBoxID Is Not Null AND r.RefundedAmount <> 0
UNION ALL
SELECT p.CashBoxID, p.PaymentDate, N'CUSTOMER_PAYMENT', N'Customer receipt voucher', p.PaymentNumber,
       c.CustomerName, p.Notes, p.Amount, CAST(0 AS MONEY), p.EmployeeID
FROM [dbo].[CustomerPayments] AS p INNER JOIN [en].[qryLocCustomers] AS c ON p.CustomerID = c.CustomerID
WHERE p.CashBoxID Is Not Null
UNION ALL
SELECT h.CashBoxID, h.InvoiceDate, N'PURCHASE', N'Purchase invoice', h.InvoiceNumber,
       s.SupplierName, h.Notes, CAST(0 AS MONEY), h.PaidAmount, h.EmployeeID
FROM [dbo].[PurchaseInvoices] AS h INNER JOIN [en].[qryLocSuppliers] AS s ON h.SupplierID = s.SupplierID
WHERE h.CashBoxID Is Not Null AND h.PaidAmount <> 0
UNION ALL
SELECT r.CashBoxID, r.ReturnDate, N'PURCHASE_RETURN', N'Purchase return (cash refund)', r.ReturnNumber,
       s.SupplierName, r.Reason, r.RefundedAmount, CAST(0 AS MONEY), r.EmployeeID
FROM [dbo].[PurchaseReturns] AS r INNER JOIN [en].[qryLocSuppliers] AS s ON r.SupplierID = s.SupplierID
WHERE r.CashBoxID Is Not Null AND r.RefundedAmount <> 0
UNION ALL
SELECT p.CashBoxID, p.PaymentDate, N'SUPPLIER_PAYMENT', N'Supplier payment voucher', p.PaymentNumber,
       s.SupplierName, p.Notes, CAST(0 AS MONEY), p.Amount, p.EmployeeID
FROM [dbo].[SupplierPayments] AS p INNER JOIN [en].[qryLocSuppliers] AS s ON p.SupplierID = s.SupplierID
WHERE p.CashBoxID Is Not Null
UNION ALL
SELECT e.CashBoxID, e.ExpenseDate, N'EXPENSE', N'Expense', e.ExpenseNumber,
       t.ExpenseTypeName, e.Description, CAST(0 AS MONEY), e.TotalAmount, e.EmployeeID
FROM [dbo].[Expenses] AS e INNER JOIN [en].[qryLocExpenseTypes] AS t ON e.ExpenseTypeID = t.ExpenseTypeID
WHERE e.CashBoxID Is Not Null
UNION ALL
SELECT v.CashBoxID, v.VoucherDate, N'CASH_IN',
       IIF(v.Category = N'OWNER', N'Deposit from the owner', IIF(v.Category = N'OVERAGE', N'Overage in the box', N'Cash receipt voucher')),
       v.VoucherNumber, v.PartyName, v.Description, v.Amount, CAST(0 AS MONEY), v.EmployeeID
FROM [dbo].[CashVouchers] AS v
WHERE v.VoucherType = N'IN'
UNION ALL
SELECT v.CashBoxID, v.VoucherDate, N'CASH_OUT',
       IIF(v.Category = N'OWNER', N'Settlement with the owner', IIF(v.Category = N'EXPENSE', N'Expense (payment voucher)', IIF(v.Category = N'ADVANCE', N'Employee advance', IIF(v.Category = N'SHORTAGE', N'Shortage in the box', N'Cash payment voucher')))),
       v.VoucherNumber, v.PartyName, v.Description, CAST(0 AS MONEY), v.Amount, v.EmployeeID
FROM [dbo].[CashVouchers] AS v
WHERE v.VoucherType = N'OUT'
UNION ALL
SELECT v.CashBoxID, v.VoucherDate, N'TRANSFER_OUT', N'Transfer to another box', v.VoucherNumber,
       b.BoxName, v.Description, CAST(0 AS MONEY), v.Amount, v.EmployeeID
FROM [dbo].[CashVouchers] AS v INNER JOIN [en].[qryLocCashBoxes] AS b ON v.ToCashBoxID = b.CashBoxID
WHERE v.VoucherType = N'TRANSFER'
UNION ALL
SELECT v.ToCashBoxID, IIF(v.InTransit <> 0, v.ReceivedAt, v.VoucherDate), N'TRANSFER_IN', N'Transfer from another box',
       v.VoucherNumber, b.BoxName, v.Description, v.Amount, CAST(0 AS MONEY), v.EmployeeID
FROM [dbo].[CashVouchers] AS v INNER JOIN [en].[qryLocCashBoxes] AS b ON v.CashBoxID = b.CashBoxID
WHERE v.VoucherType = N'TRANSFER' AND (v.InTransit = 0 OR v.ReceivedAt Is Not Null)
UNION ALL
SELECT t.CashBoxID, t.TxDate, N'BANK_DEPOSIT', N'Deposit in the bank', t.TxNumber, k.BankName, t.Description,
       CAST(0 AS MONEY), t.Amount, t.EmployeeID
FROM [dbo].[BankTransactions] AS t INNER JOIN [en].[qryLocBanks] AS k ON t.BankID = k.BankID
WHERE t.TxType = N'DEPOSIT'
UNION ALL
SELECT t.CashBoxID, t.TxDate, N'BANK_WITHDRAW', N'Withdrawal from the bank', t.TxNumber, k.BankName, t.Description,
       t.Amount, CAST(0 AS MONEY), t.EmployeeID
FROM [dbo].[BankTransactions] AS t INNER JOIN [en].[qryLocBanks] AS k ON t.BankID = k.BankID
WHERE t.TxType = N'WITHDRAW'
UNION ALL
SELECT r.CashBoxID, r.PaidDate, N'PAYROLL', N'Salary payment', r.RunNumber, N'-', r.Notes, CAST(0 AS MONEY), r.PaidAmount,
       r.EmployeeID
FROM [dbo].[PayrollRuns] AS r
WHERE r.Status = N'POSTED' AND r.PaidFrom = N'CASHBOX' AND r.PaidAmount <> 0
UNION ALL
SELECT a.CashBoxID, a.PurchaseDate, N'ASSET', N'Purchase of a fixed asset', a.AssetCode, a.AssetName, a.Notes,
       CAST(0 AS MONEY), a.Cost + a.InputVAT, a.EmployeeID
FROM [dbo].[FixedAssets] AS a
WHERE a.SourceType = N'CASHBOX'
UNION ALL
SELECT a.DisposalCashBoxID, a.DisposalDate, N'ASSET_SALE', N'Sale of a fixed asset', a.AssetCode, a.AssetName, a.Notes,
       a.DisposalProceeds + a.DisposalVAT, CAST(0 AS MONEY), a.EmployeeID
FROM [dbo].[FixedAssets] AS a
WHERE a.Status = N'DISPOSED' AND a.DisposalTo = N'CASHBOX' AND a.DisposalProceeds <> 0
UNION ALL
SELECT b.CashBoxID, b.OpeningDate, N'OPENING', N'Opening balance', N'-', b.BoxName, b.Notes,
       b.OpeningBalance, CAST(0 AS MONEY), Null
FROM [en].[qryLocCashBoxes] AS b
WHERE b.OpeningBalance <> 0;
GO
CREATE OR ALTER VIEW [en].[qryCashBoxTotals] AS
-- إجمالي الداخل والخارج لكل صندوق
SELECT CashBoxID, Sum(AmountIn) AS BoxIn, Sum(AmountOut) AS BoxOut, Max(MoveDate) AS LastMoveDate
FROM [en].[qryCashMovements]
GROUP BY CashBoxID;
GO
CREATE OR ALTER VIEW [en].[CashBoxBalanceQuery] AS
-- أرصدة الخزينة والصناديق الآن
SELECT b.CashBoxID, b.BoxName, b.BoxType,
       IIF(b.BoxType = N'MAIN', N'Main treasury', IIF(b.BoxType = N'CUSTODY', N'Sales rep custody', N'Cashier box')) AS BoxTypeName,
       b.IsActive,
       CAST(COALESCE(t.BoxIn, 0) AS MONEY) AS TotalIn, CAST(COALESCE(t.BoxOut, 0) AS MONEY) AS TotalOut,
       CAST(COALESCE(t.BoxIn, 0) AS MONEY) - CAST(COALESCE(t.BoxOut, 0) AS MONEY) AS Balance, t.LastMoveDate
FROM [en].[qryLocCashBoxes] AS b LEFT JOIN [en].[qryCashBoxTotals] AS t ON b.CashBoxID = t.CashBoxID;
GO
CREATE OR ALTER VIEW [en].[CashStatementQuery] AS
-- حركة الخزينة / الصندوق لفترة: رصيد أول المدة ثم الحركات (0 = كل الصناديق)
SELECT 1 AS SortKey, m.MoveDate, m.MoveType, m.MoveTypeName, m.DocNumber, m.PartyName, m.Details,
       b.BoxName, m.AmountIn, m.AmountOut, m.CashBoxID
FROM [en].[qryCashMovements] AS m INNER JOIN [en].[qryLocCashBoxes] AS b ON m.CashBoxID = b.CashBoxID CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE (qp.[qp_CashBoxID] = 0 OR m.CashBoxID = qp.[qp_CashBoxID]) AND m.MoveDate >= qp.[qp_PeriodStart] AND m.MoveDate < qp.[qp_PeriodEnd]
UNION ALL
SELECT 0, (SELECT p.[qp_PeriodStart] FROM [dbo].[QueryParamsNow] AS p), N'BALANCE_FWD', N'Opening balance', N'-', Null, Null, Null,
       IIF(CAST(COALESCE(Sum(o.AmountIn), 0) AS MONEY) - CAST(COALESCE(Sum(o.AmountOut), 0) AS MONEY) > 0, CAST(COALESCE(Sum(o.AmountIn), 0) AS MONEY) - CAST(COALESCE(Sum(o.AmountOut), 0) AS MONEY), 0),
       IIF(CAST(COALESCE(Sum(o.AmountIn), 0) AS MONEY) - CAST(COALESCE(Sum(o.AmountOut), 0) AS MONEY) < 0, CAST(COALESCE(Sum(o.AmountOut), 0) AS MONEY) - CAST(COALESCE(Sum(o.AmountIn), 0) AS MONEY), 0),
       (SELECT p.[qp_CashBoxID] FROM [dbo].[QueryParamsNow] AS p)
FROM [en].[qryCashMovements] AS o CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE (qp.[qp_CashBoxID] = 0 OR o.CashBoxID = qp.[qp_CashBoxID]) AND o.MoveDate < qp.[qp_PeriodStart];
GO
CREATE OR ALTER VIEW [en].[qryCashDays] AS
-- مقبوضات ومدفوعات كل يوم داخل الفترة
SELECT DATEADD(day, DATEDIFF(day, 0, m.MoveDate), 0) AS CashDay, Sum(m.AmountIn) AS Receipts, Sum(m.AmountOut) AS Payments,
       Count(*) AS MoveCount
FROM [en].[qryCashMovements] AS m CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE (qp.[qp_CashBoxID] = 0 OR m.CashBoxID = qp.[qp_CashBoxID]) AND m.MoveDate >= qp.[qp_PeriodStart] AND m.MoveDate < qp.[qp_PeriodEnd]
GROUP BY DATEADD(day, DATEDIFF(day, 0, m.MoveDate), 0);
GO
CREATE OR ALTER VIEW [en].[qryCashDayOpening] AS
-- رصيد أول كل يوم من أيام الحركة (كل الحركات قبل ذلك اليوم)
SELECT d.CashDay, Sum(x.AmountIn - x.AmountOut) AS DayOpening
FROM [en].[qryCashDays] AS d, [en].[qryCashMovements] AS x CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE (qp.[qp_CashBoxID] = 0 OR x.CashBoxID = qp.[qp_CashBoxID]) AND x.MoveDate < d.CashDay
GROUP BY d.CashDay;
GO
CREATE OR ALTER VIEW [en].[CashDailyQuery] AS
-- حركة الخزينة اليومية: رصيد أول اليوم والمقبوضات والمدفوعات ورصيد آخر اليوم
SELECT d.CashDay, CAST(COALESCE(o.DayOpening, 0) AS MONEY) AS OpeningBalance, d.Receipts, d.Payments,
       CAST(COALESCE(o.DayOpening, 0) AS MONEY) + d.Receipts - d.Payments AS ClosingBalance, d.MoveCount
FROM [en].[qryCashDays] AS d LEFT JOIN [en].[qryCashDayOpening] AS o ON d.CashDay = o.CashDay;
GO
CREATE OR ALTER VIEW [en].[qryCashBoxMoves] AS
-- حركات النقدية داخل الفترة لكل صندوق، بيومها
SELECT m.CashBoxID, DATEADD(day, DATEDIFF(day, 0, m.MoveDate), 0) AS CashDay, m.MoveDate, m.MoveType, m.MoveTypeName, m.DocNumber,
       m.PartyName, m.Details, m.AmountIn, m.AmountOut
FROM [en].[qryCashMovements] AS m CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE (qp.[qp_CashBoxID] = 0 OR m.CashBoxID = qp.[qp_CashBoxID]) AND m.MoveDate >= qp.[qp_PeriodStart] AND m.MoveDate < qp.[qp_PeriodEnd];
GO
CREATE OR ALTER VIEW [en].[qryCashBoxDays] AS
-- أيام الحركة لكل صندوق داخل الفترة
SELECT d.CashBoxID, d.CashDay
FROM [en].[qryCashBoxMoves] AS d
GROUP BY d.CashBoxID, d.CashDay;
GO
CREATE OR ALTER VIEW [en].[qryCashBoxDayOpening] AS
-- رصيد أول كل يوم لكل صندوق (كل حركاته قبل ذلك اليوم)
SELECT d.CashBoxID, d.CashDay, Sum(x.AmountIn - x.AmountOut) AS BoxOpening
FROM [en].[qryCashBoxDays] AS d, [en].[qryCashMovements] AS x
WHERE x.CashBoxID = d.CashBoxID AND x.MoveDate < d.CashDay
GROUP BY d.CashBoxID, d.CashDay;
GO
CREATE OR ALTER VIEW [en].[qryCashBoxDayClosings] AS
-- تصفيات الكاشير لكل صندوق في كل يوم: عددها والنقدية بالعدّ والفرق
SELECT c.CashBoxID, DATEADD(day, DATEDIFF(day, 0, c.ClosingDate), 0) AS CashDay, Count(*) AS DayClosings,
       Sum(c.CountedAmount) AS DayCounted, Sum(c.Difference) AS DayDifference
FROM [dbo].[CashClosings] AS c
GROUP BY c.CashBoxID, DATEADD(day, DATEDIFF(day, 0, c.ClosingDate), 0);
GO
CREATE OR ALTER VIEW [en].[CashDayBookQuery] AS
-- يومية الصندوق التفصيلية: لكل صندوق ويوم رصيد أول اليوم ثم المقبوضات ثم المصروفات
SELECT m.CashBoxID * 100000 + DATEDIFF(day, (SELECT p.[qp_PeriodStart] FROM [dbo].[QueryParamsNow] AS p), m.CashDay) AS DayKey, m.CashBoxID, b.BoxName, m.CashDay,
       IIF(m.AmountIn > 0, 1, 2) AS SideNo, m.MoveDate, m.MoveType, m.MoveTypeName, m.DocNumber, m.PartyName,
       m.Details, m.AmountIn, m.AmountOut, CAST(COALESCE(o.BoxOpening, 0) AS MONEY) AS DayOpening,
       COALESCE(k.DayClosings, 0) AS ClosingCount, CAST(COALESCE(k.DayCounted, 0) AS MONEY) AS CountedTotal,
       CAST(COALESCE(k.DayDifference, 0) AS MONEY) AS DifferenceTotal
FROM (([en].[qryCashBoxMoves] AS m INNER JOIN [en].[qryLocCashBoxes] AS b ON m.CashBoxID = b.CashBoxID)
      LEFT JOIN [en].[qryCashBoxDayOpening] AS o ON (m.CashBoxID = o.CashBoxID AND m.CashDay = o.CashDay))
     LEFT JOIN [en].[qryCashBoxDayClosings] AS k ON (m.CashBoxID = k.CashBoxID AND m.CashDay = k.CashDay);
GO
CREATE OR ALTER VIEW [en].[CashClosingsQuery] AS
-- تصفيات يومية الكاشير خلال فترة (0 = كل الصناديق)
SELECT c.ClosingID, c.ClosingNumber, c.ClosingDate, b.BoxName, e.EmployeeName, c.PeriodStart,
       c.OpeningBalance, c.CashIn, c.CashOut, c.ExpectedBalance, c.CountedAmount, c.Difference,
       IIF(c.Destination = N'MAIN', N'Main treasury', IIF(c.Destination = N'OWNER', N'Settlement with the owner', N'Stays in the box')) AS DestinationName,
       t.BoxName AS ToBoxName, c.TransferAmount, c.KeptAmount, c.Notes, c.CashBoxID
FROM (([dbo].[CashClosings] AS c INNER JOIN [en].[qryLocCashBoxes] AS b ON c.CashBoxID = b.CashBoxID)
      INNER JOIN [dbo].[Employees] AS e ON c.EmployeeID = e.EmployeeID)
     LEFT JOIN [en].[qryLocCashBoxes] AS t ON c.ToCashBoxID = t.CashBoxID CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE (qp.[qp_CashBoxID] = 0 OR c.CashBoxID = qp.[qp_CashBoxID]) AND c.ClosingDate >= qp.[qp_PeriodStart] AND c.ClosingDate < qp.[qp_PeriodEnd];
GO
CREATE OR ALTER VIEW [en].[qryCashClosingPrint] AS
-- بيانات طباعة تصفية الكاشير
SELECT c.ClosingID, c.ClosingNumber, c.ClosingDate, b.BoxName, e.EmployeeName, c.PeriodStart,
       c.OpeningBalance, c.CashIn, c.CashOut, c.ExpectedBalance, c.CountedAmount, c.Difference,
       IIF(c.Destination = N'MAIN', N'Main treasury', IIF(c.Destination = N'OWNER', N'Settlement with the owner', N'Stays in the box')) AS DestinationName,
       t.BoxName AS ToBoxName, c.TransferAmount, c.KeptAmount, c.Notes
FROM (([dbo].[CashClosings] AS c INNER JOIN [en].[qryLocCashBoxes] AS b ON c.CashBoxID = b.CashBoxID)
      INNER JOIN [dbo].[Employees] AS e ON c.EmployeeID = e.EmployeeID)
     LEFT JOIN [en].[qryLocCashBoxes] AS t ON c.ToCashBoxID = t.CashBoxID;
GO
CREATE OR ALTER VIEW [en].[qryCashVoucherPrint] AS
-- بيانات طباعة سندات قبض وصرف وتحويل النقدية
SELECT v.CashVoucherID AS DocID, v.VoucherNumber, v.VoucherDate, v.VoucherType,
       IIF(v.VoucherType = N'IN', N'Cash receipt voucher', IIF(v.VoucherType = N'OUT', N'Cash payment voucher', N'Cash transfer voucher')) AS VoucherTitle,
       IIF(v.Category = N'OWNER', IIF(v.VoucherType = N'IN', N'Deposit from the owner', N'Settlement with the owner'), IIF(v.Category = N'EXPENSE', N'Expense', IIF(v.Category = N'ADVANCE', N'Employee advance', IIF(v.Category = N'SHORTAGE', N'Shortage in the box', IIF(v.Category = N'OVERAGE', N'Overage in the box', IIF(v.Category = N'TRANSFER', N'Transfer between boxes', N'Other')))))) AS CategoryName,
       b.BoxName, t.BoxName AS ToBoxName, v.Amount, v.PartyName, v.Description,
       x.ExpenseTypeName, e.EmployeeName
FROM (((([dbo].[CashVouchers] AS v INNER JOIN [en].[qryLocCashBoxes] AS b ON v.CashBoxID = b.CashBoxID)
        INNER JOIN [dbo].[Employees] AS e ON v.EmployeeID = e.EmployeeID)
       LEFT JOIN [en].[qryLocCashBoxes] AS t ON v.ToCashBoxID = t.CashBoxID)
      LEFT JOIN [dbo].[Expenses] AS ex ON v.ExpenseID = ex.ExpenseID)
     LEFT JOIN [en].[qryLocExpenseTypes] AS x ON ex.ExpenseTypeID = x.ExpenseTypeID;
GO
CREATE OR ALTER VIEW [en].[qrySaleCost] AS
-- تكلفة كل فاتورة بيع
SELECT SalesInvoiceID, Sum(Quantity * UnitCost) AS SaleCost
FROM [dbo].[SalesInvoiceDetails]
GROUP BY SalesInvoiceID;
GO
CREATE OR ALTER VIEW [en].[qryReturnCost] AS
-- تكلفة ما عاد للمخزون من كل مرتجع بيع
SELECT SalesReturnID, Sum(IIF(ReturnToStock <> 0, Quantity * UnitCost, 0)) AS ReturnCost
FROM [dbo].[SalesReturnDetails]
GROUP BY SalesReturnID;
GO
CREATE OR ALTER VIEW [en].[qryStockCountValue] AS
-- قيمة فروقات كل جرد مُرحّل
SELECT ReferenceID AS StockCountID, Max(ReferenceNumber) AS CountNumber, Max(TransactionDate) AS CountDate,
       Max(WarehouseID) AS CountWarehouse, Sum(Quantity * UnitCost) AS CountValue
FROM [dbo].[InventoryTransactions]
WHERE ReferenceType = N'STOCK_COUNT'
GROUP BY ReferenceID;
GO
CREATE OR ALTER VIEW [en].[qryStockTransferValue] AS
-- قيمة كل تحويل بين المخازن بتكلفة الترحيل
SELECT StockTransferID, Sum(CAST(Quantity * UnitCost AS MONEY)) AS TransferValue
FROM [dbo].[StockTransferLines]
GROUP BY StockTransferID;
GO
CREATE OR ALTER VIEW [en].[qryStockNoteValue] AS
-- قيمة كل إذن تسليم أو استلام بتكلفته
SELECT StockNoteID, Sum(Quantity * UnitCost) AS NoteValue
FROM [dbo].[StockNoteLines]
GROUP BY StockNoteID;
GO
CREATE OR ALTER VIEW [en].[qryInvoicedNotes] AS
-- الأذونات التي صدرت منها فواتير: فاتورة البيع أو الشراء وقيمة الإذن
SELECT n.StockNoteID, n.SalesInvoiceID, n.PurchaseInvoiceID, v.NoteValue
FROM [dbo].[StockNotes] AS n INNER JOIN [en].[qryStockNoteValue] AS v ON n.StockNoteID = v.StockNoteID
WHERE n.Status = N'INVOICED';
GO
CREATE OR ALTER VIEW [en].[NotesNotInvoicedQuery] AS
-- أذونات التسليم والاستلام المرحّلة التي لم تصدر فواتيرها بعد
SELECT n.StockNoteID, n.NoteNumber, n.NoteType, n.NoteDate, n.WarehouseID, w.WarehouseName,
       IIF(n.NoteType = N'DELIVERY', c.CustomerName, s.SupplierName) AS PartyName, v.NoteValue,
       DATEDIFF(day, n.NoteDate, DATEADD(day, DATEDIFF(day, 0, GETDATE()), 0)) AS DaysOpen, n.Notes
FROM ((([dbo].[StockNotes] AS n INNER JOIN [en].[qryStockNoteValue] AS v ON n.StockNoteID = v.StockNoteID)
       INNER JOIN [en].[qryLocWarehouses] AS w ON n.WarehouseID = w.WarehouseID)
      LEFT JOIN [en].[qryLocCustomers] AS c ON n.CustomerID = c.CustomerID)
     LEFT JOIN [en].[qryLocSuppliers] AS s ON n.SupplierID = s.SupplierID
WHERE n.Status = N'POSTED';
GO
CREATE OR ALTER VIEW [en].[qryOrderLineNotes] AS
-- ما سُلِّم وما فُوتر من كل سطر طلبية: أسطر أذونات التسليم المرحّلة المرتبطة به (docs/62)
SELECT nl.SalesOrderLineID, Sum(nl.Quantity) AS NoteQty,
       Sum(IIF(n.Status = N'INVOICED', nl.Quantity, 0)) AS InvQty
FROM [dbo].[StockNoteLines] AS nl INNER JOIN [dbo].[StockNotes] AS n ON nl.StockNoteID = n.StockNoteID
WHERE n.Status <> N'DRAFT' AND nl.SalesOrderLineID Is Not Null
GROUP BY nl.SalesOrderLineID;
GO
CREATE OR ALTER VIEW [en].[qrySalesOrderLineStatus] AS
-- كل سطر طلبية: المطلوب والمُسلَّم والمفوتر والباقي، ومخزن الطلبية وحالتها
SELECT l.SalesOrderLineID, l.SalesOrderID, l.ProductID, o.WarehouseID, o.CustomerID, o.Status AS OrderStatus,
       l.Quantity, l.UnitPrice, COALESCE(d.NoteQty, 0) AS DeliveredQty, COALESCE(d.InvQty, 0) AS InvoicedQty,
       IIF(l.Quantity > COALESCE(d.NoteQty, 0), l.Quantity - COALESCE(d.NoteQty, 0), 0) AS RemainingQty
FROM ([dbo].[SalesOrderLines] AS l INNER JOIN [dbo].[SalesOrders] AS o ON l.SalesOrderID = o.SalesOrderID)
     LEFT JOIN [en].[qryOrderLineNotes] AS d ON l.SalesOrderLineID = d.SalesOrderLineID;
GO
CREATE OR ALTER VIEW [en].[qryReservedStock] AS
-- الكمية المحجوزة لكل صنف في كل مخزن: باقي الطلبيات المعتمدة التي لم تُسلَّم
SELECT ProductID, WarehouseID, Sum(RemainingQty) AS ReservedQty
FROM [en].[qrySalesOrderLineStatus]
WHERE OrderStatus In (N'APPROVED', N'PREPARING', N'PARTIAL') AND RemainingQty > 0
GROUP BY ProductID, WarehouseID;
GO
CREATE OR ALTER VIEW [en].[ReservedStockQuery] AS
-- الأصناف المحجوزة لطلبيات العملاء: الرصيد والمحجوز والمتاح للبيع في كل مخزن
SELECT r.WarehouseID, w.WarehouseName, p.ProductID, p.ProductCode, p.ProductName,
       COALESCE(q.StockQty, 0) AS OnHandQty, r.ReservedQty, COALESCE(q.StockQty, 0) - r.ReservedQty AS FreeQty
FROM (([en].[qryReservedStock] AS r INNER JOIN [en].[qryLocWarehouses] AS w ON r.WarehouseID = w.WarehouseID)
      INNER JOIN [dbo].[Products] AS p ON r.ProductID = p.ProductID)
     LEFT JOIN [en].[qryWarehouseStock] AS q ON (r.ProductID = q.ProductID AND r.WarehouseID = q.WarehouseID);
GO
CREATE OR ALTER VIEW [en].[PendingOrdersQuery] AS
-- أسطر طلبيات العملاء المفتوحة التي لم تُسلَّم كلها: الباقي وقيمته والتأخير عن الموعد
SELECT o.SalesOrderID, o.OrderNumber, o.OrderDate, o.RequiredDate, o.CustomerID, c.CustomerName, r.RepName,
       o.WarehouseID, w.WarehouseName, p.ProductCode, p.ProductName, s.Quantity, s.DeliveredQty, s.RemainingQty,
       s.RemainingQty * s.UnitPrice AS RemainingValue,
       IIF(o.Status = N'PARTIAL', N'Partly delivered', IIF(o.Status = N'PREPARING', N'Being prepared', N'Approved')) AS StatusName,
       IIF(o.RequiredDate Is Null, 0, IIF(DATEADD(day, DATEDIFF(day, 0, GETDATE()), 0) > o.RequiredDate, DATEDIFF(day, o.RequiredDate, DATEADD(day, DATEDIFF(day, 0, GETDATE()), 0)), 0)) AS DaysLate
FROM (((([en].[qrySalesOrderLineStatus] AS s INNER JOIN [dbo].[SalesOrders] AS o ON s.SalesOrderID = o.SalesOrderID)
        INNER JOIN [en].[qryLocCustomers] AS c ON o.CustomerID = c.CustomerID)
       INNER JOIN [en].[qryLocWarehouses] AS w ON o.WarehouseID = w.WarehouseID)
      INNER JOIN [dbo].[Products] AS p ON s.ProductID = p.ProductID)
     LEFT JOIN [en].[qryLocSalesReps] AS r ON o.SalesRepID = r.SalesRepID
WHERE o.Status In (N'APPROVED', N'PREPARING', N'PARTIAL') AND s.RemainingQty > 0;
GO
CREATE OR ALTER VIEW [en].[qryRepDayStock] AS
-- حركة مخزن سيارة المندوب في يومه بالتكلفة: المحمَّل والمفرَّغ والمباع والمرتجع وفرق الجرد (docs/63)
SELECT d.RepDayID,
       Sum(IIF(t.ReferenceType = N'TRANSFER' AND t.Quantity > 0, t.Quantity * t.UnitCost, 0)) AS LoadedVal,
       Sum(IIF(t.ReferenceType = N'TRANSFER' AND t.Quantity < 0, -t.Quantity * t.UnitCost, 0)) AS UnloadedVal,
       Sum(IIF(t.ReferenceType = N'SALE', -t.Quantity * t.UnitCost, 0)) AS SoldVal,
       Sum(IIF(t.ReferenceType = N'SALES_RETURN', t.Quantity * t.UnitCost, 0)) AS ReturnedVal,
       Sum(IIF(t.ReferenceType = N'STOCK_COUNT', t.Quantity * t.UnitCost, 0)) AS CountDiffVal
FROM [dbo].[RepDays] AS d, [dbo].[InventoryTransactions] AS t
WHERE t.WarehouseID = d.WarehouseID AND t.TransactionDate >= d.OpenedAt AND (d.SettledAt Is Null OR t.TransactionDate <= d.SettledAt)
GROUP BY d.RepDayID;
GO
CREATE OR ALTER VIEW [en].[qryRepDaySales] AS
-- فواتير البيع من سيارة المندوب في يومه: العدد والقيمة وما قُبض نقدًا في صندوق العهدة
SELECT d.RepDayID, Count(s.SalesInvoiceID) AS InvCount, Sum(s.TotalAmount) AS SalesAmt,
       Sum(IIF(s.CashBoxID = d.CashBoxID, s.PaidAmount, 0)) AS CashSalesAmt
FROM [dbo].[RepDays] AS d, [dbo].[SalesInvoices] AS s
WHERE s.WarehouseID = d.WarehouseID AND s.InvoiceDate >= d.OpenedAt AND (d.SettledAt Is Null OR s.InvoiceDate <= d.SettledAt)
GROUP BY d.RepDayID;
GO
CREATE OR ALTER VIEW [en].[qryRepDayReturns] AS
-- مرتجعات المبيعات إلى سيارة المندوب في يومه، وما رُدّ نقدًا من صندوق العهدة
SELECT d.RepDayID, Sum(r.TotalAmount) AS ReturnsAmt,
       Sum(IIF(r.CashBoxID = d.CashBoxID, r.RefundedAmount, 0)) AS RefundsAmt
FROM [dbo].[RepDays] AS d, [dbo].[SalesReturns] AS r
WHERE r.WarehouseID = d.WarehouseID AND r.ReturnDate >= d.OpenedAt AND (d.SettledAt Is Null OR r.ReturnDate <= d.SettledAt)
GROUP BY d.RepDayID;
GO
CREATE OR ALTER VIEW [en].[qryRepDayCollections] AS
-- سندات القبض من العملاء في صندوق عهدة المندوب في يومه
SELECT d.RepDayID, Count(p.PaymentID) AS PayCount, Sum(p.Amount) AS CollectedAmt
FROM [dbo].[RepDays] AS d, [dbo].[CustomerPayments] AS p
WHERE p.CashBoxID = d.CashBoxID AND p.PaymentDate >= d.OpenedAt AND (d.SettledAt Is Null OR p.PaymentDate <= d.SettledAt)
GROUP BY d.RepDayID;
GO
CREATE OR ALTER VIEW [en].[RepDaySummaryQuery] AS
-- تسوية يوم المندوب: البضاعة (المحمَّل والمباع والمرتجع والمفرَّغ وفرق الجرد) والنقدية (المبيعات والتحصيل والمتوقع والفعلي والفرق)
SELECT d.RepDayID, d.DayNumber, d.DayDate, d.SalesRepID, r.RepName, d.WarehouseID, w.WarehouseName, d.CashBoxID,
       b.BoxName, d.Status, IIF(d.Status = N'OPEN', N'Open', N'Settled') AS StatusName,
       COALESCE(k.LoadedVal, 0) AS LoadedValue, COALESCE(k.SoldVal, 0) AS SoldCost, COALESCE(k.ReturnedVal, 0) AS ReturnedCost,
       COALESCE(k.UnloadedVal, 0) AS UnloadedValue, COALESCE(k.CountDiffVal, 0) AS CountDiffValue,
       COALESCE(s.InvCount, 0) AS InvoiceCount, COALESCE(s.SalesAmt, 0) AS SalesTotal, COALESCE(s.CashSalesAmt, 0) AS CashSales,
       COALESCE(t.ReturnsAmt, 0) AS ReturnsTotal, COALESCE(t.RefundsAmt, 0) AS CashRefunds,
       COALESCE(p.CollectedAmt, 0) AS Collections, c.ExpectedBalance AS CashExpected, c.CountedAmount AS CashCounted,
       c.Difference AS CashDifference, c.TransferAmount AS CashHandedOver, d.ClosingID, d.GoodsShortage
FROM ((((((([dbo].[RepDays] AS d INNER JOIN [en].[qryLocSalesReps] AS r ON d.SalesRepID = r.SalesRepID)
            INNER JOIN [en].[qryLocWarehouses] AS w ON d.WarehouseID = w.WarehouseID)
           INNER JOIN [en].[qryLocCashBoxes] AS b ON d.CashBoxID = b.CashBoxID)
          LEFT JOIN [en].[qryRepDayStock] AS k ON d.RepDayID = k.RepDayID)
         LEFT JOIN [en].[qryRepDaySales] AS s ON d.RepDayID = s.RepDayID)
        LEFT JOIN [en].[qryRepDayReturns] AS t ON d.RepDayID = t.RepDayID)
       LEFT JOIN [en].[qryRepDayCollections] AS p ON d.RepDayID = p.RepDayID)
      LEFT JOIN [dbo].[CashClosings] AS c ON d.ClosingID = c.ClosingID;
GO
CREATE OR ALTER VIEW [en].[RepVisitListQuery] AS
-- زيارات المندوبين: المخططة من خط السير وخارجه ونتيجة كل زيارة (docs/64)
SELECT v.RepVisitID, v.VisitDate, v.SalesRepID, r.RepName, v.CustomerID, c.CustomerName, v.StopOrder, v.IsPlanned,
       IIF(v.IsPlanned <> 0, N'From the route', N'Off the route') AS PlanName, v.Result,
       IIF(v.Result = N'PENDING', N'Not done', IIF(v.Result = N'ORDER', N'Order', IIF(v.Result = N'SALE', N'Sale', IIF(v.Result = N'PAYMENT', N'Collection', IIF(v.Result = N'NO_SALE', N'No result', N'Shop closed'))))) AS ResultName,
       v.VisitedAt, v.Notes
FROM ([dbo].[RepVisits] AS v INNER JOIN [en].[qryLocSalesReps] AS r ON v.SalesRepID = r.SalesRepID)
     INNER JOIN [en].[qryLocCustomers] AS c ON v.CustomerID = c.CustomerID;
GO
CREATE OR ALTER VIEW [en].[RouteExecutionQuery] AS
-- تنفيذ خط السير لكل مندوب ويوم: المخطط والمنفذ والفائت ونتائج الزيارات (docs/64)
SELECT v.VisitDate, v.SalesRepID, r.RepName, Count(*) AS VisitCount,
       Sum(IIF(v.IsPlanned <> 0, 1, 0)) AS PlannedCount,
       Sum(IIF(v.Result <> N'PENDING', 1, 0)) AS DoneCount,
       Sum(IIF(v.Result = N'PENDING', 1, 0)) AS MissedCount,
       Sum(IIF(v.Result = N'ORDER', 1, 0)) AS OrderCount,
       Sum(IIF(v.Result = N'SALE', 1, 0)) AS SaleCount,
       Sum(IIF(v.Result = N'PAYMENT', 1, 0)) AS PaymentCount,
       Sum(IIF(v.Result = N'NO_SALE', 1, 0)) AS NoSaleCount,
       Sum(IIF(v.Result = N'CLOSED', 1, 0)) AS ClosedCount,
       Sum(IIF(v.Result <> N'PENDING', 1.0, 0)) * 1e0 / Count(*) AS DoneRate
FROM [dbo].[RepVisits] AS v INNER JOIN [en].[qryLocSalesReps] AS r ON v.SalesRepID = r.SalesRepID
GROUP BY v.VisitDate, v.SalesRepID, r.RepName;
GO
CREATE OR ALTER VIEW [en].[RepVanStockQuery] AS
-- رصيد سيارة كل مندوب: الكمية والقيمة بمتوسط التكلفة (docs/64)
SELECT q.WarehouseID, w.SalesRepID, r.RepName, w.WarehouseName, p.ProductID, p.ProductCode, p.ProductName,
       q.StockQty, p.AverageCost, q.StockQty * p.AverageCost AS StockCostValue
FROM (([en].[qryWarehouseStock] AS q INNER JOIN [en].[qryLocWarehouses] AS w ON q.WarehouseID = w.WarehouseID)
      INNER JOIN [en].[qryLocSalesReps] AS r ON w.SalesRepID = r.SalesRepID)
     INNER JOIN [dbo].[Products] AS p ON q.ProductID = p.ProductID
WHERE w.WarehouseType = N'VAN' AND q.StockQty <> 0;
GO
CREATE OR ALTER VIEW [en].[qryJournalStockTransfer] AS
-- أسطر قيود التحويل بين المخازن واستلامها
SELECT N'STOCK_TRANSFER' AS SourceType, t.StockTransferID AS SourceID, t.TransferNumber AS SourceNumber, t.TransferDate AS SourceDate, N'Transfer between warehouses' AS Party, 1 AS LineOrder, IIF(t.InTransit <> 0, 1410, IIF(t.ToWarehouseID = 1, 1400, 140000 + t.ToWarehouseID)) AS AccountCode, v.TransferValue AS Debit, CAST(0 AS MONEY) AS Credit, t.Notes AS LineText, 0 AS CostCenter
FROM [dbo].[StockTransfers] AS t INNER JOIN [en].[qryStockTransferValue] AS v ON t.StockTransferID = v.StockTransferID
WHERE t.Status <> N'DRAFT' AND v.TransferValue <> 0
UNION ALL
SELECT N'STOCK_TRANSFER' AS SourceType, t.StockTransferID AS SourceID, t.TransferNumber AS SourceNumber, t.TransferDate AS SourceDate, N'Transfer between warehouses' AS Party, 2 AS LineOrder, IIF(t.FromWarehouseID = 1, 1400, 140000 + t.FromWarehouseID) AS AccountCode, CAST(0 AS MONEY) AS Debit, v.TransferValue AS Credit, t.Notes AS LineText, 0 AS CostCenter
FROM [dbo].[StockTransfers] AS t INNER JOIN [en].[qryStockTransferValue] AS v ON t.StockTransferID = v.StockTransferID
WHERE t.Status <> N'DRAFT' AND v.TransferValue <> 0
UNION ALL
SELECT N'STOCK_RECEIVE' AS SourceType, t.StockTransferID AS SourceID, t.TransferNumber AS SourceNumber, t.ReceivedAt AS SourceDate, N'Stock transfer received' AS Party, 1 AS LineOrder, IIF(t.ToWarehouseID = 1, 1400, 140000 + t.ToWarehouseID) AS AccountCode, v.TransferValue AS Debit, CAST(0 AS MONEY) AS Credit, t.Notes AS LineText, 0 AS CostCenter
FROM [dbo].[StockTransfers] AS t INNER JOIN [en].[qryStockTransferValue] AS v ON t.StockTransferID = v.StockTransferID
WHERE t.Status = N'RECEIVED' AND t.InTransit <> 0 AND v.TransferValue <> 0
UNION ALL
SELECT N'STOCK_RECEIVE' AS SourceType, t.StockTransferID AS SourceID, t.TransferNumber AS SourceNumber, t.ReceivedAt AS SourceDate, N'Stock transfer received' AS Party, 2 AS LineOrder, 1410 AS AccountCode, CAST(0 AS MONEY) AS Debit, v.TransferValue AS Credit, N'Goods in transit' AS LineText, 0 AS CostCenter
FROM [dbo].[StockTransfers] AS t INNER JOIN [en].[qryStockTransferValue] AS v ON t.StockTransferID = v.StockTransferID
WHERE t.Status = N'RECEIVED' AND t.InTransit <> 0 AND v.TransferValue <> 0;
GO
CREATE OR ALTER VIEW [en].[qryJournalStockNote] AS
-- أسطر قيود أذونات التسليم والاستلام (1430 و2150)
SELECT N'DELIVERY_NOTE' AS SourceType, n.StockNoteID AS SourceID, n.NoteNumber AS SourceNumber, n.NoteDate AS SourceDate, c.CustomerName AS Party, 1 AS LineOrder, 1430 AS AccountCode, v.NoteValue AS Debit, CAST(0 AS MONEY) AS Credit, c.CustomerName AS LineText, 0 AS CostCenter
FROM ([dbo].[StockNotes] AS n INNER JOIN [en].[qryStockNoteValue] AS v ON n.StockNoteID = v.StockNoteID) INNER JOIN [en].[qryLocCustomers] AS c ON n.CustomerID = c.CustomerID
WHERE n.Status <> N'DRAFT' AND n.NoteType = N'DELIVERY' AND v.NoteValue <> 0
UNION ALL
SELECT N'DELIVERY_NOTE' AS SourceType, n.StockNoteID AS SourceID, n.NoteNumber AS SourceNumber, n.NoteDate AS SourceDate, c.CustomerName AS Party, 2 AS LineOrder, IIF(n.WarehouseID = 1, 1400, 140000 + n.WarehouseID) AS AccountCode, CAST(0 AS MONEY) AS Debit, v.NoteValue AS Credit, N'Stock' AS LineText, 0 AS CostCenter
FROM ([dbo].[StockNotes] AS n INNER JOIN [en].[qryStockNoteValue] AS v ON n.StockNoteID = v.StockNoteID) INNER JOIN [en].[qryLocCustomers] AS c ON n.CustomerID = c.CustomerID
WHERE n.Status <> N'DRAFT' AND n.NoteType = N'DELIVERY' AND v.NoteValue <> 0
UNION ALL
SELECT N'RECEIPT_NOTE' AS SourceType, n.StockNoteID AS SourceID, n.NoteNumber AS SourceNumber, n.NoteDate AS SourceDate, s.SupplierName AS Party, 1 AS LineOrder, IIF(n.WarehouseID = 1, 1400, 140000 + n.WarehouseID) AS AccountCode, v.NoteValue AS Debit, CAST(0 AS MONEY) AS Credit, N'Stock' AS LineText, 0 AS CostCenter
FROM ([dbo].[StockNotes] AS n INNER JOIN [en].[qryStockNoteValue] AS v ON n.StockNoteID = v.StockNoteID) INNER JOIN [en].[qryLocSuppliers] AS s ON n.SupplierID = s.SupplierID
WHERE n.Status <> N'DRAFT' AND n.NoteType = N'RECEIPT' AND v.NoteValue <> 0
UNION ALL
SELECT N'RECEIPT_NOTE' AS SourceType, n.StockNoteID AS SourceID, n.NoteNumber AS SourceNumber, n.NoteDate AS SourceDate, s.SupplierName AS Party, 2 AS LineOrder, 2150 AS AccountCode, CAST(0 AS MONEY) AS Debit, v.NoteValue AS Credit, s.SupplierName AS LineText, 0 AS CostCenter
FROM ([dbo].[StockNotes] AS n INNER JOIN [en].[qryStockNoteValue] AS v ON n.StockNoteID = v.StockNoteID) INNER JOIN [en].[qryLocSuppliers] AS s ON n.SupplierID = s.SupplierID
WHERE n.Status <> N'DRAFT' AND n.NoteType = N'RECEIPT' AND v.NoteValue <> 0;
GO
CREATE OR ALTER VIEW [en].[TransfersInTransitQuery] AS
-- التحويلات بين المخازن المرسلة ولم تُستلم بعد، بقيمتها وعدد أيامها بالطريق
SELECT t.StockTransferID, t.TransferNumber, t.TransferDate, t.FromWarehouseID, f.WarehouseName AS FromName,
       t.ToWarehouseID, d.WarehouseName AS ToName, v.TransferValue,
       DATEDIFF(day, t.TransferDate, DATEADD(day, DATEDIFF(day, 0, GETDATE()), 0)) AS DaysInTransit, t.Notes
FROM (([dbo].[StockTransfers] AS t INNER JOIN [en].[qryLocWarehouses] AS f ON t.FromWarehouseID = f.WarehouseID)
      INNER JOIN [en].[qryLocWarehouses] AS d ON t.ToWarehouseID = d.WarehouseID)
     INNER JOIN [en].[qryStockTransferValue] AS v ON t.StockTransferID = v.StockTransferID
WHERE t.Status = N'SENT';
GO
CREATE OR ALTER VIEW [en].[qryStockPartyAccounts] AS
-- حساب كل جهة صرف واستلام: حسابها، وإلا حساب نوعها
SELECT p.StockPartyID, p.PartyName, p.CostCenterID,
       IIF(p.AccountCode Is Null, IIF(p.PartyType = N'PRODUCTION', 1420, IIF(p.PartyType = N'WASTE', 5250, IIF(p.PartyType = N'DEPARTMENT', 5640, 5900))), p.AccountCode) AS PartyAccount
FROM [en].[qryLocStockParties] AS p;
GO
CREATE OR ALTER VIEW [en].[qryStockDocumentValue] AS
-- قيمة كل سند صرف أو استلام مخزني
SELECT StockDocumentID, Sum(CAST(Quantity * UnitCost AS MONEY)) AS DocValue
FROM [dbo].[StockDocumentLines]
GROUP BY StockDocumentID;
GO
CREATE OR ALTER VIEW [en].[qryJournalStockDocument] AS
-- أسطر قيود سندات الصرف والاستلام المخزني
SELECT N'STOCK_ISSUE' AS SourceType, d.StockDocumentID AS SourceID, d.DocNumber AS SourceNumber, d.DocDate AS SourceDate, p.PartyName AS Party, 1 AS LineOrder, p.PartyAccount AS AccountCode, v.DocValue AS Debit, CAST(0 AS MONEY) AS Credit, d.Notes AS LineText, IIF(p.CostCenterID Is Null, 0, p.CostCenterID) AS CostCenter
FROM ([dbo].[StockDocuments] AS d INNER JOIN [en].[qryStockDocumentValue] AS v ON d.StockDocumentID = v.StockDocumentID) INNER JOIN [en].[qryStockPartyAccounts] AS p ON d.StockPartyID = p.StockPartyID
WHERE d.Status = N'POSTED' AND d.DocType = N'ISSUE' AND v.DocValue <> 0
UNION ALL
SELECT N'STOCK_ISSUE' AS SourceType, d.StockDocumentID AS SourceID, d.DocNumber AS SourceNumber, d.DocDate AS SourceDate, p.PartyName AS Party, 2 AS LineOrder, IIF(d.WarehouseID = 1, 1400, 140000 + d.WarehouseID) AS AccountCode, CAST(0 AS MONEY) AS Debit, v.DocValue AS Credit, N'Stock' AS LineText, IIF(p.CostCenterID Is Null, 0, p.CostCenterID) AS CostCenter
FROM ([dbo].[StockDocuments] AS d INNER JOIN [en].[qryStockDocumentValue] AS v ON d.StockDocumentID = v.StockDocumentID) INNER JOIN [en].[qryStockPartyAccounts] AS p ON d.StockPartyID = p.StockPartyID
WHERE d.Status = N'POSTED' AND d.DocType = N'ISSUE' AND v.DocValue <> 0
UNION ALL
SELECT N'STOCK_RECEIPT' AS SourceType, d.StockDocumentID AS SourceID, d.DocNumber AS SourceNumber, d.DocDate AS SourceDate, p.PartyName AS Party, 1 AS LineOrder, IIF(d.WarehouseID = 1, 1400, 140000 + d.WarehouseID) AS AccountCode, v.DocValue AS Debit, CAST(0 AS MONEY) AS Credit, N'Stock' AS LineText, IIF(p.CostCenterID Is Null, 0, p.CostCenterID) AS CostCenter
FROM ([dbo].[StockDocuments] AS d INNER JOIN [en].[qryStockDocumentValue] AS v ON d.StockDocumentID = v.StockDocumentID) INNER JOIN [en].[qryStockPartyAccounts] AS p ON d.StockPartyID = p.StockPartyID
WHERE d.Status = N'POSTED' AND d.DocType = N'RECEIPT' AND v.DocValue <> 0
UNION ALL
SELECT N'STOCK_RECEIPT' AS SourceType, d.StockDocumentID AS SourceID, d.DocNumber AS SourceNumber, d.DocDate AS SourceDate, p.PartyName AS Party, 2 AS LineOrder, p.PartyAccount AS AccountCode, CAST(0 AS MONEY) AS Debit, v.DocValue AS Credit, d.Notes AS LineText, IIF(p.CostCenterID Is Null, 0, p.CostCenterID) AS CostCenter
FROM ([dbo].[StockDocuments] AS d INNER JOIN [en].[qryStockDocumentValue] AS v ON d.StockDocumentID = v.StockDocumentID) INNER JOIN [en].[qryStockPartyAccounts] AS p ON d.StockPartyID = p.StockPartyID
WHERE d.Status = N'POSTED' AND d.DocType = N'RECEIPT' AND v.DocValue <> 0;
GO
CREATE OR ALTER VIEW [en].[qryJournalSale] AS
-- أسطر قيود فواتير البيع
SELECT N'SALE' AS SourceType, h.SalesInvoiceID AS SourceID, h.InvoiceNumber AS SourceNumber, h.InvoiceDate AS SourceDate, c.CustomerName AS Party, 1 AS LineOrder, IIF(h.CashBoxID Is Null, IIF(h.PaymentMethodID Is Null Or h.PaymentMethodID = 1, 1190, IIF(h.BankID Is Null, 1200, 120000 + h.BankID)), 110000 + h.CashBoxID) AS AccountCode, h.PaidAmount AS Debit, CAST(0 AS MONEY) AS Credit, c.CustomerName AS LineText, IIF(h.CostCenterID Is Null, 0, h.CostCenterID) AS CostCenter
FROM [dbo].[SalesInvoices] AS h INNER JOIN [en].[qryLocCustomers] AS c ON h.CustomerID = c.CustomerID
WHERE h.PaidAmount <> 0
UNION ALL
SELECT N'SALE' AS SourceType, h.SalesInvoiceID AS SourceID, h.InvoiceNumber AS SourceNumber, h.InvoiceDate AS SourceDate, c.CustomerName AS Party, 2 AS LineOrder, 1300 AS AccountCode, h.RemainingAmount AS Debit, CAST(0 AS MONEY) AS Credit, c.CustomerName AS LineText, IIF(h.CostCenterID Is Null, 0, h.CostCenterID) AS CostCenter
FROM [dbo].[SalesInvoices] AS h INNER JOIN [en].[qryLocCustomers] AS c ON h.CustomerID = c.CustomerID
WHERE h.RemainingAmount <> 0
UNION ALL
SELECT N'SALE' AS SourceType, h.SalesInvoiceID AS SourceID, h.InvoiceNumber AS SourceNumber, h.InvoiceDate AS SourceDate, c.CustomerName AS Party, 3 AS LineOrder, 4100 AS AccountCode, CAST(0 AS MONEY) AS Debit, h.TaxableAmount AS Credit, N'Sales' AS LineText, IIF(h.CostCenterID Is Null, 0, h.CostCenterID) AS CostCenter
FROM [dbo].[SalesInvoices] AS h INNER JOIN [en].[qryLocCustomers] AS c ON h.CustomerID = c.CustomerID
WHERE h.TaxableAmount <> 0
UNION ALL
SELECT N'SALE' AS SourceType, h.SalesInvoiceID AS SourceID, h.InvoiceNumber AS SourceNumber, h.InvoiceDate AS SourceDate, c.CustomerName AS Party, 4 AS LineOrder, 2200 AS AccountCode, CAST(0 AS MONEY) AS Debit, h.Tax AS Credit, N'Output VAT' AS LineText, IIF(h.CostCenterID Is Null, 0, h.CostCenterID) AS CostCenter
FROM [dbo].[SalesInvoices] AS h INNER JOIN [en].[qryLocCustomers] AS c ON h.CustomerID = c.CustomerID
WHERE h.Tax <> 0
UNION ALL
SELECT N'SALE' AS SourceType, h.SalesInvoiceID AS SourceID, h.InvoiceNumber AS SourceNumber, h.InvoiceDate AS SourceDate, c.CustomerName AS Party, 5 AS LineOrder, 5100 AS AccountCode, k.SaleCost AS Debit, CAST(0 AS MONEY) AS Credit, N'Cost of goods sold' AS LineText, IIF(h.CostCenterID Is Null, 0, h.CostCenterID) AS CostCenter
FROM (([dbo].[SalesInvoices] AS h INNER JOIN [en].[qryLocCustomers] AS c ON h.CustomerID = c.CustomerID) INNER JOIN [en].[qrySaleCost] AS k ON h.SalesInvoiceID = k.SalesInvoiceID) LEFT JOIN [en].[qryInvoicedNotes] AS nv ON h.SalesInvoiceID = nv.SalesInvoiceID
WHERE k.SaleCost <> 0
UNION ALL
SELECT N'SALE' AS SourceType, h.SalesInvoiceID AS SourceID, h.InvoiceNumber AS SourceNumber, h.InvoiceDate AS SourceDate, c.CustomerName AS Party, 6 AS LineOrder, IIF(nv.StockNoteID Is Null, IIF(h.WarehouseID = 1, 1400, 140000 + h.WarehouseID), 1430) AS AccountCode, CAST(0 AS MONEY) AS Debit, k.SaleCost AS Credit, N'Stock' AS LineText, IIF(h.CostCenterID Is Null, 0, h.CostCenterID) AS CostCenter
FROM (([dbo].[SalesInvoices] AS h INNER JOIN [en].[qryLocCustomers] AS c ON h.CustomerID = c.CustomerID) INNER JOIN [en].[qrySaleCost] AS k ON h.SalesInvoiceID = k.SalesInvoiceID) LEFT JOIN [en].[qryInvoicedNotes] AS nv ON h.SalesInvoiceID = nv.SalesInvoiceID
WHERE k.SaleCost <> 0;
GO
CREATE OR ALTER VIEW [en].[qryJournalSalesReturn] AS
-- أسطر قيود مرتجعات البيع
SELECT N'SALES_RETURN' AS SourceType, r.SalesReturnID AS SourceID, r.ReturnNumber AS SourceNumber, r.ReturnDate AS SourceDate, c.CustomerName AS Party, 1 AS LineOrder, 4110 AS AccountCode, r.TaxableAmount AS Debit, CAST(0 AS MONEY) AS Credit, N'Sales returns' AS LineText, IIF(r.CostCenterID Is Null, 0, r.CostCenterID) AS CostCenter
FROM [dbo].[SalesReturns] AS r INNER JOIN [en].[qryLocCustomers] AS c ON r.CustomerID = c.CustomerID
WHERE r.TaxableAmount <> 0
UNION ALL
SELECT N'SALES_RETURN' AS SourceType, r.SalesReturnID AS SourceID, r.ReturnNumber AS SourceNumber, r.ReturnDate AS SourceDate, c.CustomerName AS Party, 2 AS LineOrder, 2200 AS AccountCode, r.Tax AS Debit, CAST(0 AS MONEY) AS Credit, N'Output VAT' AS LineText, IIF(r.CostCenterID Is Null, 0, r.CostCenterID) AS CostCenter
FROM [dbo].[SalesReturns] AS r INNER JOIN [en].[qryLocCustomers] AS c ON r.CustomerID = c.CustomerID
WHERE r.Tax <> 0
UNION ALL
SELECT N'SALES_RETURN' AS SourceType, r.SalesReturnID AS SourceID, r.ReturnNumber AS SourceNumber, r.ReturnDate AS SourceDate, c.CustomerName AS Party, 3 AS LineOrder, IIF(r.CashBoxID Is Null, IIF(r.PaymentMethodID Is Null Or r.PaymentMethodID = 1, 1190, IIF(r.BankID Is Null, 1200, 120000 + r.BankID)), 110000 + r.CashBoxID) AS AccountCode, CAST(0 AS MONEY) AS Debit, r.RefundedAmount AS Credit, c.CustomerName AS LineText, IIF(r.CostCenterID Is Null, 0, r.CostCenterID) AS CostCenter
FROM [dbo].[SalesReturns] AS r INNER JOIN [en].[qryLocCustomers] AS c ON r.CustomerID = c.CustomerID
WHERE r.RefundedAmount <> 0
UNION ALL
SELECT N'SALES_RETURN' AS SourceType, r.SalesReturnID AS SourceID, r.ReturnNumber AS SourceNumber, r.ReturnDate AS SourceDate, c.CustomerName AS Party, 4 AS LineOrder, 1300 AS AccountCode, CAST(0 AS MONEY) AS Debit, r.TotalAmount - r.RefundedAmount AS Credit, c.CustomerName AS LineText, IIF(r.CostCenterID Is Null, 0, r.CostCenterID) AS CostCenter
FROM [dbo].[SalesReturns] AS r INNER JOIN [en].[qryLocCustomers] AS c ON r.CustomerID = c.CustomerID
WHERE r.TotalAmount - r.RefundedAmount <> 0
UNION ALL
SELECT N'SALES_RETURN' AS SourceType, r.SalesReturnID AS SourceID, r.ReturnNumber AS SourceNumber, r.ReturnDate AS SourceDate, c.CustomerName AS Party, 5 AS LineOrder, IIF(r.WarehouseID = 1, 1400, 140000 + r.WarehouseID) AS AccountCode, k.ReturnCost AS Debit, CAST(0 AS MONEY) AS Credit, N'Stock' AS LineText, IIF(r.CostCenterID Is Null, 0, r.CostCenterID) AS CostCenter
FROM ([dbo].[SalesReturns] AS r INNER JOIN [en].[qryLocCustomers] AS c ON r.CustomerID = c.CustomerID) INNER JOIN [en].[qryReturnCost] AS k ON r.SalesReturnID = k.SalesReturnID
WHERE k.ReturnCost <> 0
UNION ALL
SELECT N'SALES_RETURN' AS SourceType, r.SalesReturnID AS SourceID, r.ReturnNumber AS SourceNumber, r.ReturnDate AS SourceDate, c.CustomerName AS Party, 6 AS LineOrder, 5100 AS AccountCode, CAST(0 AS MONEY) AS Debit, k.ReturnCost AS Credit, N'Cost of goods sold' AS LineText, IIF(r.CostCenterID Is Null, 0, r.CostCenterID) AS CostCenter
FROM ([dbo].[SalesReturns] AS r INNER JOIN [en].[qryLocCustomers] AS c ON r.CustomerID = c.CustomerID) INNER JOIN [en].[qryReturnCost] AS k ON r.SalesReturnID = k.SalesReturnID
WHERE k.ReturnCost <> 0;
GO
CREATE OR ALTER VIEW [en].[qryJournalPurchase] AS
-- أسطر قيود فواتير الشراء
SELECT N'PURCHASE' AS SourceType, h.PurchaseInvoiceID AS SourceID, h.InvoiceNumber AS SourceNumber, h.InvoiceDate AS SourceDate, s.SupplierName AS Party, 1 AS LineOrder, IIF(h.WarehouseID = 1, 1400, 140000 + h.WarehouseID) AS AccountCode, h.TaxableAmount - CAST(COALESCE(nv.NoteValue, 0) AS MONEY) AS Debit, CAST(0 AS MONEY) AS Credit, N'Stock' AS LineText, 0 AS CostCenter
FROM ([dbo].[PurchaseInvoices] AS h INNER JOIN [en].[qryLocSuppliers] AS s ON h.SupplierID = s.SupplierID) LEFT JOIN [en].[qryInvoicedNotes] AS nv ON h.PurchaseInvoiceID = nv.PurchaseInvoiceID
WHERE h.TaxableAmount - CAST(COALESCE(nv.NoteValue, 0) AS MONEY) <> 0
UNION ALL
SELECT N'PURCHASE' AS SourceType, h.PurchaseInvoiceID AS SourceID, h.InvoiceNumber AS SourceNumber, h.InvoiceDate AS SourceDate, s.SupplierName AS Party, 5 AS LineOrder, 2150 AS AccountCode, nv.NoteValue AS Debit, CAST(0 AS MONEY) AS Credit, N'Goods received not invoiced' AS LineText, 0 AS CostCenter
FROM ([dbo].[PurchaseInvoices] AS h INNER JOIN [en].[qryLocSuppliers] AS s ON h.SupplierID = s.SupplierID) LEFT JOIN [en].[qryInvoicedNotes] AS nv ON h.PurchaseInvoiceID = nv.PurchaseInvoiceID
WHERE nv.NoteValue Is Not Null AND nv.NoteValue <> 0
UNION ALL
SELECT N'PURCHASE' AS SourceType, h.PurchaseInvoiceID AS SourceID, h.InvoiceNumber AS SourceNumber, h.InvoiceDate AS SourceDate, s.SupplierName AS Party, 2 AS LineOrder, 1500 AS AccountCode, h.Tax AS Debit, CAST(0 AS MONEY) AS Credit, N'Input VAT' AS LineText, 0 AS CostCenter
FROM [dbo].[PurchaseInvoices] AS h INNER JOIN [en].[qryLocSuppliers] AS s ON h.SupplierID = s.SupplierID
WHERE h.Tax <> 0
UNION ALL
SELECT N'PURCHASE' AS SourceType, h.PurchaseInvoiceID AS SourceID, h.InvoiceNumber AS SourceNumber, h.InvoiceDate AS SourceDate, s.SupplierName AS Party, 3 AS LineOrder, IIF(h.CashBoxID Is Null, IIF(h.PaymentMethodID Is Null Or h.PaymentMethodID = 1, 1190, IIF(h.BankID Is Null, 1200, 120000 + h.BankID)), 110000 + h.CashBoxID) AS AccountCode, CAST(0 AS MONEY) AS Debit, h.PaidAmount AS Credit, s.SupplierName AS LineText, 0 AS CostCenter
FROM [dbo].[PurchaseInvoices] AS h INNER JOIN [en].[qryLocSuppliers] AS s ON h.SupplierID = s.SupplierID
WHERE h.PaidAmount <> 0
UNION ALL
SELECT N'PURCHASE' AS SourceType, h.PurchaseInvoiceID AS SourceID, h.InvoiceNumber AS SourceNumber, h.InvoiceDate AS SourceDate, s.SupplierName AS Party, 4 AS LineOrder, 2100 AS AccountCode, CAST(0 AS MONEY) AS Debit, h.RemainingAmount AS Credit, s.SupplierName AS LineText, 0 AS CostCenter
FROM [dbo].[PurchaseInvoices] AS h INNER JOIN [en].[qryLocSuppliers] AS s ON h.SupplierID = s.SupplierID
WHERE h.RemainingAmount <> 0;
GO
CREATE OR ALTER VIEW [en].[qryJournalPurchaseReturn] AS
-- أسطر قيود مرتجعات الشراء
SELECT N'PURCHASE_RETURN' AS SourceType, r.PurchaseReturnID AS SourceID, r.ReturnNumber AS SourceNumber, r.ReturnDate AS SourceDate, s.SupplierName AS Party, 1 AS LineOrder, IIF(r.CashBoxID Is Null, IIF(r.PaymentMethodID Is Null Or r.PaymentMethodID = 1, 1190, IIF(r.BankID Is Null, 1200, 120000 + r.BankID)), 110000 + r.CashBoxID) AS AccountCode, r.RefundedAmount AS Debit, CAST(0 AS MONEY) AS Credit, s.SupplierName AS LineText, 0 AS CostCenter
FROM [dbo].[PurchaseReturns] AS r INNER JOIN [en].[qryLocSuppliers] AS s ON r.SupplierID = s.SupplierID
WHERE r.RefundedAmount <> 0
UNION ALL
SELECT N'PURCHASE_RETURN' AS SourceType, r.PurchaseReturnID AS SourceID, r.ReturnNumber AS SourceNumber, r.ReturnDate AS SourceDate, s.SupplierName AS Party, 2 AS LineOrder, 2100 AS AccountCode, r.TotalAmount - r.RefundedAmount AS Debit, CAST(0 AS MONEY) AS Credit, s.SupplierName AS LineText, 0 AS CostCenter
FROM [dbo].[PurchaseReturns] AS r INNER JOIN [en].[qryLocSuppliers] AS s ON r.SupplierID = s.SupplierID
WHERE r.TotalAmount - r.RefundedAmount <> 0
UNION ALL
SELECT N'PURCHASE_RETURN' AS SourceType, r.PurchaseReturnID AS SourceID, r.ReturnNumber AS SourceNumber, r.ReturnDate AS SourceDate, s.SupplierName AS Party, 3 AS LineOrder, IIF(r.WarehouseID = 1, 1400, 140000 + r.WarehouseID) AS AccountCode, CAST(0 AS MONEY) AS Debit, r.TaxableAmount AS Credit, N'Stock' AS LineText, 0 AS CostCenter
FROM [dbo].[PurchaseReturns] AS r INNER JOIN [en].[qryLocSuppliers] AS s ON r.SupplierID = s.SupplierID
WHERE r.TaxableAmount <> 0
UNION ALL
SELECT N'PURCHASE_RETURN' AS SourceType, r.PurchaseReturnID AS SourceID, r.ReturnNumber AS SourceNumber, r.ReturnDate AS SourceDate, s.SupplierName AS Party, 4 AS LineOrder, 1500 AS AccountCode, CAST(0 AS MONEY) AS Debit, r.Tax AS Credit, N'Input VAT' AS LineText, 0 AS CostCenter
FROM [dbo].[PurchaseReturns] AS r INNER JOIN [en].[qryLocSuppliers] AS s ON r.SupplierID = s.SupplierID
WHERE r.Tax <> 0;
GO
CREATE OR ALTER VIEW [en].[qryJournalPayments] AS
-- أسطر قيود سندات القبض من العملاء والصرف للموردين
SELECT N'CUSTOMER_PAYMENT' AS SourceType, p.PaymentID AS SourceID, p.PaymentNumber AS SourceNumber, p.PaymentDate AS SourceDate, c.CustomerName AS Party, 1 AS LineOrder, IIF(p.CashBoxID Is Null, IIF(p.PaymentMethodID Is Null Or p.PaymentMethodID = 1, 1190, IIF(p.BankID Is Null, 1200, 120000 + p.BankID)), 110000 + p.CashBoxID) AS AccountCode, p.Amount AS Debit, CAST(0 AS MONEY) AS Credit, c.CustomerName AS LineText, 0 AS CostCenter
FROM [dbo].[CustomerPayments] AS p INNER JOIN [en].[qryLocCustomers] AS c ON p.CustomerID = c.CustomerID
WHERE p.Amount <> 0
UNION ALL
SELECT N'CUSTOMER_PAYMENT' AS SourceType, p.PaymentID AS SourceID, p.PaymentNumber AS SourceNumber, p.PaymentDate AS SourceDate, c.CustomerName AS Party, 2 AS LineOrder, 1300 AS AccountCode, CAST(0 AS MONEY) AS Debit, p.Amount AS Credit, c.CustomerName AS LineText, 0 AS CostCenter
FROM [dbo].[CustomerPayments] AS p INNER JOIN [en].[qryLocCustomers] AS c ON p.CustomerID = c.CustomerID
WHERE p.Amount <> 0
UNION ALL
SELECT N'SUPPLIER_PAYMENT' AS SourceType, p.PaymentID AS SourceID, p.PaymentNumber AS SourceNumber, p.PaymentDate AS SourceDate, s.SupplierName AS Party, 1 AS LineOrder, 2100 AS AccountCode, p.Amount AS Debit, CAST(0 AS MONEY) AS Credit, s.SupplierName AS LineText, 0 AS CostCenter
FROM [dbo].[SupplierPayments] AS p INNER JOIN [en].[qryLocSuppliers] AS s ON p.SupplierID = s.SupplierID
WHERE p.Amount <> 0
UNION ALL
SELECT N'SUPPLIER_PAYMENT' AS SourceType, p.PaymentID AS SourceID, p.PaymentNumber AS SourceNumber, p.PaymentDate AS SourceDate, s.SupplierName AS Party, 2 AS LineOrder, IIF(p.CashBoxID Is Null, IIF(p.PaymentMethodID Is Null Or p.PaymentMethodID = 1, 1190, IIF(p.BankID Is Null, 1200, 120000 + p.BankID)), 110000 + p.CashBoxID) AS AccountCode, CAST(0 AS MONEY) AS Debit, p.Amount AS Credit, s.SupplierName AS LineText, 0 AS CostCenter
FROM [dbo].[SupplierPayments] AS p INNER JOIN [en].[qryLocSuppliers] AS s ON p.SupplierID = s.SupplierID
WHERE p.Amount <> 0;
GO
CREATE OR ALTER VIEW [en].[qryJournalExpense] AS
-- أسطر قيود المصروفات (عدا المسجلة بسند نقدية)
SELECT N'EXPENSE' AS SourceType, e.ExpenseID AS SourceID, e.ExpenseNumber AS SourceNumber, e.ExpenseDate AS SourceDate, t.ExpenseTypeName AS Party, 1 AS LineOrder, 530000 + e.ExpenseTypeID AS AccountCode, e.Amount AS Debit, CAST(0 AS MONEY) AS Credit, t.ExpenseTypeName AS LineText, IIF(e.CostCenterID Is Null, 0, e.CostCenterID) AS CostCenter
FROM ([dbo].[Expenses] AS e INNER JOIN [en].[qryLocExpenseTypes] AS t ON e.ExpenseTypeID = t.ExpenseTypeID) LEFT JOIN [dbo].[CashVouchers] AS v ON e.ExpenseID = v.ExpenseID
WHERE v.CashVoucherID Is Null AND e.Amount <> 0
UNION ALL
SELECT N'EXPENSE' AS SourceType, e.ExpenseID AS SourceID, e.ExpenseNumber AS SourceNumber, e.ExpenseDate AS SourceDate, t.ExpenseTypeName AS Party, 2 AS LineOrder, 1500 AS AccountCode, e.Tax AS Debit, CAST(0 AS MONEY) AS Credit, N'Input VAT' AS LineText, IIF(e.CostCenterID Is Null, 0, e.CostCenterID) AS CostCenter
FROM ([dbo].[Expenses] AS e INNER JOIN [en].[qryLocExpenseTypes] AS t ON e.ExpenseTypeID = t.ExpenseTypeID) LEFT JOIN [dbo].[CashVouchers] AS v ON e.ExpenseID = v.ExpenseID
WHERE v.CashVoucherID Is Null AND e.Tax <> 0
UNION ALL
SELECT N'EXPENSE' AS SourceType, e.ExpenseID AS SourceID, e.ExpenseNumber AS SourceNumber, e.ExpenseDate AS SourceDate, t.ExpenseTypeName AS Party, 3 AS LineOrder, IIF(e.CashBoxID Is Null, IIF(e.PaymentMethodID Is Null Or e.PaymentMethodID = 1, 1190, IIF(e.BankID Is Null, 1200, 120000 + e.BankID)), 110000 + e.CashBoxID) AS AccountCode, CAST(0 AS MONEY) AS Debit, e.TotalAmount AS Credit, e.Description AS LineText, IIF(e.CostCenterID Is Null, 0, e.CostCenterID) AS CostCenter
FROM ([dbo].[Expenses] AS e INNER JOIN [en].[qryLocExpenseTypes] AS t ON e.ExpenseTypeID = t.ExpenseTypeID) LEFT JOIN [dbo].[CashVouchers] AS v ON e.ExpenseID = v.ExpenseID
WHERE v.CashVoucherID Is Null AND e.TotalAmount <> 0;
GO
CREATE OR ALTER VIEW [en].[qryJournalCashVoucher] AS
-- أسطر قيود سندات النقدية (قبض وصرف وتحويل)
SELECT N'CASH_VOUCHER' AS SourceType, v.CashVoucherID AS SourceID, v.VoucherNumber AS SourceNumber, v.VoucherDate AS SourceDate, IIF(v.PartyName Is Null, v.Description, v.PartyName) AS Party, 1 AS LineOrder, 110000 + v.CashBoxID AS AccountCode, v.Amount AS Debit, CAST(0 AS MONEY) AS Credit, v.PartyName AS LineText, IIF(v.CostCenterID Is Null, 0, v.CostCenterID) AS CostCenter
FROM [dbo].[CashVouchers] AS v
WHERE v.VoucherType = N'IN'
UNION ALL
SELECT N'CASH_VOUCHER' AS SourceType, v.CashVoucherID AS SourceID, v.VoucherNumber AS SourceNumber, v.VoucherDate AS SourceDate, IIF(v.PartyName Is Null, v.Description, v.PartyName) AS Party, 2 AS LineOrder, IIF(v.Category = N'OWNER', 3100, IIF(v.Category = N'OVERAGE', 4300, IIF(v.Category = N'ADVANCE', 1600, 4200))) AS AccountCode, CAST(0 AS MONEY) AS Debit, v.Amount AS Credit, v.Description AS LineText, IIF(v.CostCenterID Is Null, 0, v.CostCenterID) AS CostCenter
FROM [dbo].[CashVouchers] AS v
WHERE v.VoucherType = N'IN'
UNION ALL
SELECT N'CASH_VOUCHER' AS SourceType, v.CashVoucherID AS SourceID, v.VoucherNumber AS SourceNumber, v.VoucherDate AS SourceDate, IIF(v.PartyName Is Null, v.Description, v.PartyName) AS Party, 1 AS LineOrder, IIF(v.Category = N'OWNER', 3100, IIF(v.Category = N'ADVANCE', 1600, IIF(v.Category = N'SHORTAGE', 5400, IIF(v.Category = N'COMMISSION', 2330, IIF(v.Category = N'EXPENSE' AND x.ExpenseTypeID Is Not Null, 530000 + x.ExpenseTypeID, 5900))))) AS AccountCode, v.Amount - CAST(COALESCE(x.Tax, 0) AS MONEY) AS Debit, CAST(0 AS MONEY) AS Credit, v.Description AS LineText, IIF(v.CostCenterID Is Null, 0, v.CostCenterID) AS CostCenter
FROM [dbo].[CashVouchers] AS v LEFT JOIN [dbo].[Expenses] AS x ON v.ExpenseID = x.ExpenseID
WHERE v.VoucherType = N'OUT'
UNION ALL
SELECT N'CASH_VOUCHER' AS SourceType, v.CashVoucherID AS SourceID, v.VoucherNumber AS SourceNumber, v.VoucherDate AS SourceDate, IIF(v.PartyName Is Null, v.Description, v.PartyName) AS Party, 2 AS LineOrder, 110000 + v.CashBoxID AS AccountCode, CAST(0 AS MONEY) AS Debit, v.Amount AS Credit, v.PartyName AS LineText, IIF(v.CostCenterID Is Null, 0, v.CostCenterID) AS CostCenter
FROM [dbo].[CashVouchers] AS v LEFT JOIN [dbo].[Expenses] AS x ON v.ExpenseID = x.ExpenseID
WHERE v.VoucherType = N'OUT'
UNION ALL
SELECT N'CASH_VOUCHER' AS SourceType, v.CashVoucherID AS SourceID, v.VoucherNumber AS SourceNumber, v.VoucherDate AS SourceDate, IIF(v.PartyName Is Null, v.Description, v.PartyName) AS Party, 3 AS LineOrder, 1500 AS AccountCode, x.Tax AS Debit, CAST(0 AS MONEY) AS Credit, N'Input VAT' AS LineText, IIF(v.CostCenterID Is Null, 0, v.CostCenterID) AS CostCenter
FROM [dbo].[CashVouchers] AS v LEFT JOIN [dbo].[Expenses] AS x ON v.ExpenseID = x.ExpenseID
WHERE v.VoucherType = N'OUT' AND x.Tax <> 0
UNION ALL
SELECT N'CASH_VOUCHER' AS SourceType, v.CashVoucherID AS SourceID, v.VoucherNumber AS SourceNumber, v.VoucherDate AS SourceDate, IIF(v.PartyName Is Null, v.Description, v.PartyName) AS Party, 1 AS LineOrder, IIF(v.InTransit <> 0, 1195, 110000 + v.ToCashBoxID) AS AccountCode, v.Amount AS Debit, CAST(0 AS MONEY) AS Credit, v.Description AS LineText, IIF(v.CostCenterID Is Null, 0, v.CostCenterID) AS CostCenter
FROM [dbo].[CashVouchers] AS v
WHERE v.VoucherType = N'TRANSFER'
UNION ALL
SELECT N'CASH_VOUCHER' AS SourceType, v.CashVoucherID AS SourceID, v.VoucherNumber AS SourceNumber, v.VoucherDate AS SourceDate, IIF(v.PartyName Is Null, v.Description, v.PartyName) AS Party, 2 AS LineOrder, 110000 + v.CashBoxID AS AccountCode, CAST(0 AS MONEY) AS Debit, v.Amount AS Credit, v.Description AS LineText, IIF(v.CostCenterID Is Null, 0, v.CostCenterID) AS CostCenter
FROM [dbo].[CashVouchers] AS v
WHERE v.VoucherType = N'TRANSFER'
UNION ALL
SELECT N'CASH_RECEIVE' AS SourceType, v.CashVoucherID AS SourceID, v.VoucherNumber AS SourceNumber, v.ReceivedAt AS SourceDate, v.Description AS Party, 1 AS LineOrder, 110000 + v.ToCashBoxID AS AccountCode, v.Amount AS Debit, CAST(0 AS MONEY) AS Credit, v.Description AS LineText, IIF(v.CostCenterID Is Null, 0, v.CostCenterID) AS CostCenter
FROM [dbo].[CashVouchers] AS v
WHERE v.VoucherType = N'TRANSFER' AND v.InTransit <> 0 AND v.ReceivedAt Is Not Null
UNION ALL
SELECT N'CASH_RECEIVE' AS SourceType, v.CashVoucherID AS SourceID, v.VoucherNumber AS SourceNumber, v.ReceivedAt AS SourceDate, v.Description AS Party, 2 AS LineOrder, 1195 AS AccountCode, CAST(0 AS MONEY) AS Debit, v.Amount AS Credit, N'Cash in transit' AS LineText, IIF(v.CostCenterID Is Null, 0, v.CostCenterID) AS CostCenter
FROM [dbo].[CashVouchers] AS v
WHERE v.VoucherType = N'TRANSFER' AND v.InTransit <> 0 AND v.ReceivedAt Is Not Null;
GO
CREATE OR ALTER VIEW [en].[qryJournalStock] AS
-- أسطر قيود حركات المخزون اليدوية وتسويات الجرد
SELECT N'STOCK_MOVE' AS SourceType, i.TransactionID AS SourceID, i.ReferenceNumber AS SourceNumber, i.TransactionDate AS SourceDate, p.ProductName AS Party, 1 AS LineOrder, IIF(i.WarehouseID = 1, 1400, 140000 + i.WarehouseID) AS AccountCode, IIF(i.Quantity * i.UnitCost > 0, i.Quantity * i.UnitCost, 0) AS Debit, IIF(i.Quantity * i.UnitCost < 0, -i.Quantity * i.UnitCost, 0) AS Credit, i.Notes AS LineText, 0 AS CostCenter
FROM [dbo].[InventoryTransactions] AS i INNER JOIN [dbo].[Products] AS p ON i.ProductID = p.ProductID
WHERE i.ReferenceType = N'MANUAL' AND i.Quantity * i.UnitCost <> 0
UNION ALL
SELECT N'STOCK_MOVE' AS SourceType, i.TransactionID AS SourceID, i.ReferenceNumber AS SourceNumber, i.TransactionDate AS SourceDate, p.ProductName AS Party, 2 AS LineOrder, IIF(i.TransactionTypeID = 8, 3900, 5200) AS AccountCode, IIF(i.Quantity * i.UnitCost < 0, -i.Quantity * i.UnitCost, 0) AS Debit, IIF(i.Quantity * i.UnitCost > 0, i.Quantity * i.UnitCost, 0) AS Credit, i.Notes AS LineText, 0 AS CostCenter
FROM [dbo].[InventoryTransactions] AS i INNER JOIN [dbo].[Products] AS p ON i.ProductID = p.ProductID
WHERE i.ReferenceType = N'MANUAL' AND i.Quantity * i.UnitCost <> 0
UNION ALL
SELECT N'STOCK_COUNT' AS SourceType, k.StockCountID AS SourceID, k.CountNumber AS SourceNumber, k.CountDate AS SourceDate, N'Stock count adjustment' AS Party, 1 AS LineOrder, IIF(k.CountWarehouse = 1, 1400, 140000 + k.CountWarehouse) AS AccountCode, IIF(k.CountValue > 0, k.CountValue, 0) AS Debit, IIF(k.CountValue < 0, -k.CountValue, 0) AS Credit, N'Stock' AS LineText, 0 AS CostCenter
FROM [en].[qryStockCountValue] AS k
WHERE k.CountValue <> 0
UNION ALL
SELECT N'STOCK_COUNT' AS SourceType, k.StockCountID AS SourceID, k.CountNumber AS SourceNumber, k.CountDate AS SourceDate, N'Stock count adjustment' AS Party, 2 AS LineOrder, 5200 AS AccountCode, IIF(k.CountValue < 0, -k.CountValue, 0) AS Debit, IIF(k.CountValue > 0, k.CountValue, 0) AS Credit, N'Count differences' AS LineText, 0 AS CostCenter
FROM [en].[qryStockCountValue] AS k
WHERE k.CountValue <> 0;
GO
CREATE OR ALTER VIEW [en].[qryJournalOpening] AS
-- أسطر قيود الأرصدة الافتتاحية للصناديق والعملاء والموردين والبنوك والحسابات
SELECT N'BOX_OPENING' AS SourceType, b.CashBoxID AS SourceID, b.BoxName AS SourceNumber, b.OpeningDate AS SourceDate, b.BoxName AS Party, 1 AS LineOrder, 110000 + b.CashBoxID AS AccountCode, b.OpeningBalance AS Debit, CAST(0 AS MONEY) AS Credit, b.BoxName AS LineText, 0 AS CostCenter
FROM [en].[qryLocCashBoxes] AS b
WHERE b.OpeningBalance <> 0
UNION ALL
SELECT N'BOX_OPENING' AS SourceType, b.CashBoxID AS SourceID, b.BoxName AS SourceNumber, b.OpeningDate AS SourceDate, b.BoxName AS Party, 2 AS LineOrder, 3900 AS AccountCode, CAST(0 AS MONEY) AS Debit, b.OpeningBalance AS Credit, N'Opening balance' AS LineText, 0 AS CostCenter
FROM [en].[qryLocCashBoxes] AS b
WHERE b.OpeningBalance <> 0
UNION ALL
SELECT N'CUSTOMER_OPENING' AS SourceType, c.CustomerID AS SourceID, c.CustomerName AS SourceNumber, c.OpeningOn AS SourceDate, c.CustomerName AS Party, 1 AS LineOrder, 1300 AS AccountCode, IIF(c.OpeningBalance > 0, c.OpeningBalance, 0) AS Debit, IIF(c.OpeningBalance < 0, -c.OpeningBalance, 0) AS Credit, c.CustomerName AS LineText, 0 AS CostCenter
FROM [en].[qryCustomerOpening] AS c
WHERE c.OpeningBalance <> 0
UNION ALL
SELECT N'CUSTOMER_OPENING' AS SourceType, c.CustomerID AS SourceID, c.CustomerName AS SourceNumber, c.OpeningOn AS SourceDate, c.CustomerName AS Party, 2 AS LineOrder, 3900 AS AccountCode, IIF(c.OpeningBalance < 0, -c.OpeningBalance, 0) AS Debit, IIF(c.OpeningBalance > 0, c.OpeningBalance, 0) AS Credit, N'Opening balance' AS LineText, 0 AS CostCenter
FROM [en].[qryCustomerOpening] AS c
WHERE c.OpeningBalance <> 0
UNION ALL
SELECT N'SUPPLIER_OPENING' AS SourceType, s.SupplierID AS SourceID, s.SupplierName AS SourceNumber, s.OpeningOn AS SourceDate, s.SupplierName AS Party, 1 AS LineOrder, 2100 AS AccountCode, IIF(s.OpeningBalance < 0, -s.OpeningBalance, 0) AS Debit, IIF(s.OpeningBalance > 0, s.OpeningBalance, 0) AS Credit, s.SupplierName AS LineText, 0 AS CostCenter
FROM [en].[qrySupplierOpening] AS s
WHERE s.OpeningBalance <> 0
UNION ALL
SELECT N'SUPPLIER_OPENING' AS SourceType, s.SupplierID AS SourceID, s.SupplierName AS SourceNumber, s.OpeningOn AS SourceDate, s.SupplierName AS Party, 2 AS LineOrder, 3900 AS AccountCode, IIF(s.OpeningBalance > 0, s.OpeningBalance, 0) AS Debit, IIF(s.OpeningBalance < 0, -s.OpeningBalance, 0) AS Credit, N'Opening balance' AS LineText, 0 AS CostCenter
FROM [en].[qrySupplierOpening] AS s
WHERE s.OpeningBalance <> 0
UNION ALL
SELECT N'ACCOUNT_OPENING' AS SourceType, o.OpeningLineID AS SourceID, o.AccountName AS SourceNumber, o.OpeningOn AS SourceDate, o.AccountName AS Party, 1 AS LineOrder, o.LineAccount AS AccountCode, o.LineDebit AS Debit, o.LineCredit AS Credit, o.AccountName AS LineText, 0 AS CostCenter
FROM [en].[qryOpeningAccountLines] AS o
WHERE o.LineDebit + o.LineCredit <> 0
UNION ALL
SELECT N'ACCOUNT_OPENING' AS SourceType, o.OpeningLineID AS SourceID, o.AccountName AS SourceNumber, o.OpeningOn AS SourceDate, o.AccountName AS Party, 2 AS LineOrder, 3900 AS AccountCode, o.LineCredit AS Debit, o.LineDebit AS Credit, N'Opening balance' AS LineText, 0 AS CostCenter
FROM [en].[qryOpeningAccountLines] AS o
WHERE o.LineDebit + o.LineCredit <> 0
UNION ALL
SELECT N'BANK_OPENING' AS SourceType, k.BankID AS SourceID, k.BankName AS SourceNumber, k.OpeningDate AS SourceDate, k.BankName AS Party, 1 AS LineOrder, 120000 + k.BankID AS AccountCode, IIF(k.OpeningBalance > 0, k.OpeningBalance, 0) AS Debit, IIF(k.OpeningBalance < 0, -k.OpeningBalance, 0) AS Credit, k.BankName AS LineText, 0 AS CostCenter
FROM [en].[qryLocBanks] AS k
WHERE k.OpeningBalance <> 0
UNION ALL
SELECT N'BANK_OPENING' AS SourceType, k.BankID AS SourceID, k.BankName AS SourceNumber, k.OpeningDate AS SourceDate, k.BankName AS Party, 2 AS LineOrder, 3900 AS AccountCode, IIF(k.OpeningBalance < 0, -k.OpeningBalance, 0) AS Debit, IIF(k.OpeningBalance > 0, k.OpeningBalance, 0) AS Credit, N'Opening balance' AS LineText, 0 AS CostCenter
FROM [en].[qryLocBanks] AS k
WHERE k.OpeningBalance <> 0;
GO
CREATE OR ALTER VIEW [en].[qryManualEntryLines] AS
-- أسطر القيود اليدوية مع رأس كل قيد
SELECT h.ManualEntryID, h.EntryNumber, h.EntryDate, h.Description, l.LineNumber AS [LineNo],
       l.AccountCode AS LineAccount, l.Debit AS LineDebit, l.Credit AS LineCredit, l.LineText AS LineNote,
       IIF(l.CostCenterID Is Null, 0, l.CostCenterID) AS LineCenter
FROM [dbo].[ManualEntries] AS h INNER JOIN [dbo].[ManualEntryLines] AS l ON h.ManualEntryID = l.ManualEntryID;
GO
CREATE OR ALTER VIEW [en].[qryJournalManual] AS
-- أسطر القيود اليدوية
SELECT N'MANUAL' AS SourceType, m.ManualEntryID AS SourceID, m.EntryNumber AS SourceNumber, m.EntryDate AS SourceDate, m.Description AS Party, m.[LineNo] AS LineOrder, m.LineAccount AS AccountCode, m.LineDebit AS Debit, m.LineCredit AS Credit, m.LineNote AS LineText, m.LineCenter AS CostCenter
FROM [en].[qryManualEntryLines] AS m
WHERE m.LineDebit + m.LineCredit <> 0;
GO
CREATE OR ALTER VIEW [en].[qryYearCloseLines] AS
-- أسطر قيود إقفال السنوات مع رأس كل إقفال
SELECT h.YearClosingID, h.ClosingNumber, h.ClosingDate, h.Notes, l.LineNumber AS [LineNo],
       l.AccountCode AS LineAccount, l.Debit AS LineDebit, l.Credit AS LineCredit, l.LineText AS LineNote
FROM [dbo].[FiscalYearClosings] AS h INNER JOIN [dbo].[FiscalYearClosingLines] AS l ON h.YearClosingID = l.YearClosingID;
GO
CREATE OR ALTER VIEW [en].[qryJournalYearClose] AS
-- أسطر قيود إقفال السنوات: الإيرادات والمصروفات إلى الأرباح المحتجزة
SELECT N'YEAR_CLOSE' AS SourceType, y.YearClosingID AS SourceID, y.ClosingNumber AS SourceNumber, y.ClosingDate AS SourceDate, y.Notes AS Party, y.[LineNo] AS LineOrder, y.LineAccount AS AccountCode, y.LineDebit AS Debit, y.LineCredit AS Credit, y.LineNote AS LineText, 0 AS CostCenter
FROM [en].[qryYearCloseLines] AS y
WHERE y.LineDebit + y.LineCredit <> 0;
GO
CREATE OR ALTER VIEW [en].[qryJournalVatReturn] AS
-- أسطر قيود الإقرار الضريبي المعتمد (التسوية) وسداده
SELECT N'VAT_RETURN' AS SourceType, v.VatReturnID AS SourceID, v.ReturnNumber AS SourceNumber, v.FiledDate AS SourceDate, v.ReturnNumber AS Party, 1 AS LineOrder, 2200 AS AccountCode, IIF(v.SalesStdVAT > 0, v.SalesStdVAT, 0) AS Debit, IIF(v.SalesStdVAT < 0, -v.SalesStdVAT, 0) AS Credit, N'Output VAT of the period' AS LineText, 0 AS CostCenter
FROM [dbo].[VatReturns] AS v
WHERE v.Status = N'FILED' AND v.SalesStdVAT <> 0
UNION ALL
SELECT N'VAT_RETURN' AS SourceType, v.VatReturnID AS SourceID, v.ReturnNumber AS SourceNumber, v.FiledDate AS SourceDate, v.ReturnNumber AS Party, 2 AS LineOrder, 1500 AS AccountCode, IIF(v.PurchStdVAT < 0, -v.PurchStdVAT, 0) AS Debit, IIF(v.PurchStdVAT > 0, v.PurchStdVAT, 0) AS Credit, N'Input VAT of the period' AS LineText, 0 AS CostCenter
FROM [dbo].[VatReturns] AS v
WHERE v.Status = N'FILED' AND v.PurchStdVAT <> 0
UNION ALL
SELECT N'VAT_RETURN' AS SourceType, v.VatReturnID AS SourceID, v.ReturnNumber AS SourceNumber, v.FiledDate AS SourceDate, v.ReturnNumber AS Party, 3 AS LineOrder, 2200 AS AccountCode, IIF(v.Corrections > 0, v.Corrections, 0) AS Debit, IIF(v.Corrections < 0, -v.Corrections, 0) AS Credit, N'Corrections from previous periods' AS LineText, 0 AS CostCenter
FROM [dbo].[VatReturns] AS v
WHERE v.Status = N'FILED' AND v.Corrections <> 0
UNION ALL
SELECT N'VAT_RETURN' AS SourceType, v.VatReturnID AS SourceID, v.ReturnNumber AS SourceNumber, v.FiledDate AS SourceDate, v.ReturnNumber AS Party, 4 AS LineOrder, 2250 AS AccountCode, IIF((v.SalesStdVAT - v.PurchStdVAT + v.Corrections) < 0, -(v.SalesStdVAT - v.PurchStdVAT + v.Corrections), 0) AS Debit, IIF((v.SalesStdVAT - v.PurchStdVAT + v.Corrections) > 0, (v.SalesStdVAT - v.PurchStdVAT + v.Corrections), 0) AS Credit, N'Net VAT of the period' AS LineText, 0 AS CostCenter
FROM [dbo].[VatReturns] AS v
WHERE v.Status = N'FILED' AND (v.SalesStdVAT - v.PurchStdVAT + v.Corrections) <> 0
UNION ALL
SELECT N'VAT_PAYMENT' AS SourceType, v.VatReturnID AS SourceID, v.ReturnNumber AS SourceNumber, v.PaidDate AS SourceDate, v.ReturnNumber AS Party, 1 AS LineOrder, 2250 AS AccountCode, v.PaidAmount AS Debit, CAST(0 AS MONEY) AS Credit, N'VAT payment' AS LineText, 0 AS CostCenter
FROM [dbo].[VatReturns] AS v
WHERE v.Status = N'FILED' AND v.PaidAmount <> 0
UNION ALL
SELECT N'VAT_PAYMENT' AS SourceType, v.VatReturnID AS SourceID, v.ReturnNumber AS SourceNumber, v.PaidDate AS SourceDate, v.ReturnNumber AS Party, 2 AS LineOrder, v.PaidAccount AS AccountCode, CAST(0 AS MONEY) AS Debit, v.PaidAmount AS Credit, v.FilingRef AS LineText, 0 AS CostCenter
FROM [dbo].[VatReturns] AS v
WHERE v.Status = N'FILED' AND v.PaidAmount <> 0;
GO
CREATE OR ALTER VIEW [en].[qryJournalCheque] AS
-- أسطر قيود الشيكات: الاستلام أو الإصدار، ثم التحصيل أو الارتداد
SELECT N'CHEQUE' AS SourceType, q.ChequeID AS SourceID, q.ChequeRef AS SourceNumber, q.IssueDate AS SourceDate, q.ChequeNo AS Party, 1 AS LineOrder, 1250 AS AccountCode, q.Amount AS Debit, CAST(0 AS MONEY) AS Credit, N'Received cheque under collection' AS LineText, 0 AS CostCenter
FROM [dbo].[Cheques] AS q
WHERE q.Direction = N'IN'
UNION ALL
SELECT N'CHEQUE' AS SourceType, q.ChequeID AS SourceID, q.ChequeRef AS SourceNumber, q.IssueDate AS SourceDate, q.ChequeNo AS Party, 2 AS LineOrder, 1300 AS AccountCode, CAST(0 AS MONEY) AS Debit, q.Amount AS Credit, q.ChequeNo AS LineText, 0 AS CostCenter
FROM [dbo].[Cheques] AS q
WHERE q.Direction = N'IN'
UNION ALL
SELECT N'CHEQUE' AS SourceType, q.ChequeID AS SourceID, q.ChequeRef AS SourceNumber, q.IssueDate AS SourceDate, q.ChequeNo AS Party, 1 AS LineOrder, 2100 AS AccountCode, q.Amount AS Debit, CAST(0 AS MONEY) AS Credit, q.ChequeNo AS LineText, 0 AS CostCenter
FROM [dbo].[Cheques] AS q
WHERE q.Direction = N'OUT'
UNION ALL
SELECT N'CHEQUE' AS SourceType, q.ChequeID AS SourceID, q.ChequeRef AS SourceNumber, q.IssueDate AS SourceDate, q.ChequeNo AS Party, 2 AS LineOrder, 2110 AS AccountCode, CAST(0 AS MONEY) AS Debit, q.Amount AS Credit, N'Issued cheque' AS LineText, 0 AS CostCenter
FROM [dbo].[Cheques] AS q
WHERE q.Direction = N'OUT'
UNION ALL
SELECT N'CHEQUE_STATUS' AS SourceType, q.ChequeID AS SourceID, q.ChequeRef AS SourceNumber, q.StatusDate AS SourceDate, q.ChequeNo AS Party, 1 AS LineOrder, 120000 + q.BankID AS AccountCode, q.Amount AS Debit, CAST(0 AS MONEY) AS Credit, N'Cheque collection' AS LineText, 0 AS CostCenter
FROM [dbo].[Cheques] AS q
WHERE q.Direction = N'IN' AND q.Status = N'COLLECTED'
UNION ALL
SELECT N'CHEQUE_STATUS' AS SourceType, q.ChequeID AS SourceID, q.ChequeRef AS SourceNumber, q.StatusDate AS SourceDate, q.ChequeNo AS Party, 2 AS LineOrder, 1250 AS AccountCode, CAST(0 AS MONEY) AS Debit, q.Amount AS Credit, q.ChequeNo AS LineText, 0 AS CostCenter
FROM [dbo].[Cheques] AS q
WHERE q.Direction = N'IN' AND q.Status = N'COLLECTED'
UNION ALL
SELECT N'CHEQUE_STATUS' AS SourceType, q.ChequeID AS SourceID, q.ChequeRef AS SourceNumber, q.StatusDate AS SourceDate, q.ChequeNo AS Party, 1 AS LineOrder, 1300 AS AccountCode, q.Amount AS Debit, CAST(0 AS MONEY) AS Credit, N'Bounced cheque' AS LineText, 0 AS CostCenter
FROM [dbo].[Cheques] AS q
WHERE q.Direction = N'IN' AND q.Status = N'BOUNCED'
UNION ALL
SELECT N'CHEQUE_STATUS' AS SourceType, q.ChequeID AS SourceID, q.ChequeRef AS SourceNumber, q.StatusDate AS SourceDate, q.ChequeNo AS Party, 2 AS LineOrder, 1250 AS AccountCode, CAST(0 AS MONEY) AS Debit, q.Amount AS Credit, q.ChequeNo AS LineText, 0 AS CostCenter
FROM [dbo].[Cheques] AS q
WHERE q.Direction = N'IN' AND q.Status = N'BOUNCED'
UNION ALL
SELECT N'CHEQUE_STATUS' AS SourceType, q.ChequeID AS SourceID, q.ChequeRef AS SourceNumber, q.StatusDate AS SourceDate, q.ChequeNo AS Party, 1 AS LineOrder, 2110 AS AccountCode, q.Amount AS Debit, CAST(0 AS MONEY) AS Credit, q.ChequeNo AS LineText, 0 AS CostCenter
FROM [dbo].[Cheques] AS q
WHERE q.Direction = N'OUT' AND q.Status = N'COLLECTED'
UNION ALL
SELECT N'CHEQUE_STATUS' AS SourceType, q.ChequeID AS SourceID, q.ChequeRef AS SourceNumber, q.StatusDate AS SourceDate, q.ChequeNo AS Party, 2 AS LineOrder, 120000 + q.BankID AS AccountCode, CAST(0 AS MONEY) AS Debit, q.Amount AS Credit, N'Cheque payment' AS LineText, 0 AS CostCenter
FROM [dbo].[Cheques] AS q
WHERE q.Direction = N'OUT' AND q.Status = N'COLLECTED'
UNION ALL
SELECT N'CHEQUE_STATUS' AS SourceType, q.ChequeID AS SourceID, q.ChequeRef AS SourceNumber, q.StatusDate AS SourceDate, q.ChequeNo AS Party, 1 AS LineOrder, 2110 AS AccountCode, q.Amount AS Debit, CAST(0 AS MONEY) AS Credit, q.ChequeNo AS LineText, 0 AS CostCenter
FROM [dbo].[Cheques] AS q
WHERE q.Direction = N'OUT' AND q.Status = N'BOUNCED'
UNION ALL
SELECT N'CHEQUE_STATUS' AS SourceType, q.ChequeID AS SourceID, q.ChequeRef AS SourceNumber, q.StatusDate AS SourceDate, q.ChequeNo AS Party, 2 AS LineOrder, 2100 AS AccountCode, CAST(0 AS MONEY) AS Debit, q.Amount AS Credit, N'Bounced cheque' AS LineText, 0 AS CostCenter
FROM [dbo].[Cheques] AS q
WHERE q.Direction = N'OUT' AND q.Status = N'BOUNCED';
GO
CREATE OR ALTER VIEW [en].[qryAssetRevalTotals] AS
-- مجموع إعادة تقييم كل أصل: الفرق، والفائض، وخسائر الانخفاض
SELECT AssetID, Sum(ValueChange) AS SumReval, Sum(SurplusPart) AS SumSurplus, Sum(LossPart) AS SumLoss, Count(*) AS RevalCount
FROM [dbo].[AssetRevaluations]
GROUP BY AssetID;
GO
CREATE OR ALTER VIEW [en].[qryAssetLastReval] AS
-- آخر إعادة تقييم لكل أصل: القيمة الجديدة والعمر الباقي
SELECT r.AssetID, r.RevalDate, r.NewValue, r.MonthsLeft
FROM [dbo].[AssetRevaluations] AS r
WHERE r.RevaluationID IN (SELECT Max(x.RevaluationID) FROM [dbo].[AssetRevaluations] AS x GROUP BY x.AssetID);
GO
CREATE OR ALTER VIEW [en].[qryAssetFirstCenter] AS
-- مركز تكلفة الأصل وقت شرائه: مصدر أول نقل له
SELECT t.AssetID, t.FromCenterID
FROM [dbo].[AssetTransfers] AS t
WHERE t.TransferID IN (SELECT Min(x.TransferID) FROM [dbo].[AssetTransfers] AS x GROUP BY x.AssetID);
GO
CREATE OR ALTER VIEW [en].[qryJournalAsset] AS
-- أسطر قيود اقتناء الأصول الثابتة وبيعها أو استبعادها
SELECT N'ASSET' AS SourceType, a.AssetID AS SourceID, a.AssetCode AS SourceNumber, a.PurchaseDate AS SourceDate, a.AssetName AS Party, 1 AS LineOrder, a.AssetAccount AS AccountCode, a.Cost AS Debit, CAST(0 AS MONEY) AS Credit, a.AssetName AS LineText, IIF(pc.AssetID Is Null, IIF(a.CostCenterID Is Null, 0, a.CostCenterID), IIF(pc.FromCenterID Is Null, 0, pc.FromCenterID)) AS CostCenter
FROM [dbo].[FixedAssets] AS a LEFT JOIN [en].[qryAssetFirstCenter] AS pc ON a.AssetID = pc.AssetID
WHERE a.Cost <> 0
UNION ALL
SELECT N'ASSET' AS SourceType, a.AssetID AS SourceID, a.AssetCode AS SourceNumber, a.PurchaseDate AS SourceDate, a.AssetName AS Party, 2 AS LineOrder, 1500 AS AccountCode, a.InputVAT AS Debit, CAST(0 AS MONEY) AS Credit, N'Input VAT' AS LineText, IIF(pc.AssetID Is Null, IIF(a.CostCenterID Is Null, 0, a.CostCenterID), IIF(pc.FromCenterID Is Null, 0, pc.FromCenterID)) AS CostCenter
FROM [dbo].[FixedAssets] AS a LEFT JOIN [en].[qryAssetFirstCenter] AS pc ON a.AssetID = pc.AssetID
WHERE a.InputVAT <> 0 AND a.SourceType <> N'OPENING'
UNION ALL
SELECT N'ASSET' AS SourceType, a.AssetID AS SourceID, a.AssetCode AS SourceNumber, a.PurchaseDate AS SourceDate, a.AssetName AS Party, 3 AS LineOrder, IIF(a.SourceType = N'BANK', 120000 + a.BankID, IIF(a.SourceType = N'CASHBOX', 110000 + a.CashBoxID, IIF(a.SourceType = N'ACCOUNT', a.CounterAccount, 3900))) AS AccountCode, CAST(0 AS MONEY) AS Debit, IIF(a.SourceType = N'OPENING', a.Cost - a.OpeningAccumDep, a.Cost + a.InputVAT) AS Credit, a.Notes AS LineText, IIF(pc.AssetID Is Null, IIF(a.CostCenterID Is Null, 0, a.CostCenterID), IIF(pc.FromCenterID Is Null, 0, pc.FromCenterID)) AS CostCenter
FROM [dbo].[FixedAssets] AS a LEFT JOIN [en].[qryAssetFirstCenter] AS pc ON a.AssetID = pc.AssetID
WHERE IIF(a.SourceType = N'OPENING', a.Cost - a.OpeningAccumDep, a.Cost + a.InputVAT) <> 0
UNION ALL
SELECT N'ASSET' AS SourceType, a.AssetID AS SourceID, a.AssetCode AS SourceNumber, a.PurchaseDate AS SourceDate, a.AssetName AS Party, 4 AS LineOrder, 1790 AS AccountCode, CAST(0 AS MONEY) AS Debit, a.OpeningAccumDep AS Credit, N'Previous depreciation' AS LineText, IIF(pc.AssetID Is Null, IIF(a.CostCenterID Is Null, 0, a.CostCenterID), IIF(pc.FromCenterID Is Null, 0, pc.FromCenterID)) AS CostCenter
FROM [dbo].[FixedAssets] AS a LEFT JOIN [en].[qryAssetFirstCenter] AS pc ON a.AssetID = pc.AssetID
WHERE a.SourceType = N'OPENING' AND a.OpeningAccumDep <> 0
UNION ALL
SELECT N'ASSET_DISPOSAL' AS SourceType, a.AssetID AS SourceID, a.AssetCode AS SourceNumber, a.DisposalDate AS SourceDate, a.AssetName AS Party, 1 AS LineOrder, 1790 AS AccountCode, a.DisposalAccumDep AS Debit, CAST(0 AS MONEY) AS Credit, N'Accumulated depreciation of the asset' AS LineText, IIF(a.CostCenterID Is Null, 0, a.CostCenterID) AS CostCenter
FROM [dbo].[FixedAssets] AS a LEFT JOIN [en].[qryAssetRevalTotals] AS rv ON a.AssetID = rv.AssetID
WHERE a.Status = N'DISPOSED' AND a.DisposalAccumDep <> 0
UNION ALL
SELECT N'ASSET_DISPOSAL' AS SourceType, a.AssetID AS SourceID, a.AssetCode AS SourceNumber, a.DisposalDate AS SourceDate, a.AssetName AS Party, 2 AS LineOrder, IIF(a.DisposalTo = N'BANK', 120000 + a.DisposalBankID, 110000 + a.DisposalCashBoxID) AS AccountCode, a.DisposalProceeds + a.DisposalVAT AS Debit, CAST(0 AS MONEY) AS Credit, N'Sale price of the asset' AS LineText, IIF(a.CostCenterID Is Null, 0, a.CostCenterID) AS CostCenter
FROM [dbo].[FixedAssets] AS a LEFT JOIN [en].[qryAssetRevalTotals] AS rv ON a.AssetID = rv.AssetID
WHERE a.Status = N'DISPOSED' AND a.DisposalProceeds <> 0
UNION ALL
SELECT N'ASSET_DISPOSAL' AS SourceType, a.AssetID AS SourceID, a.AssetCode AS SourceNumber, a.DisposalDate AS SourceDate, a.AssetName AS Party, 3 AS LineOrder, a.AssetAccount AS AccountCode, CAST(0 AS MONEY) AS Debit, (a.Cost + CAST(COALESCE(rv.SumReval, 0) AS MONEY)) AS Credit, a.AssetName AS LineText, IIF(a.CostCenterID Is Null, 0, a.CostCenterID) AS CostCenter
FROM [dbo].[FixedAssets] AS a LEFT JOIN [en].[qryAssetRevalTotals] AS rv ON a.AssetID = rv.AssetID
WHERE a.Status = N'DISPOSED'
UNION ALL
SELECT N'ASSET_DISPOSAL' AS SourceType, a.AssetID AS SourceID, a.AssetCode AS SourceNumber, a.DisposalDate AS SourceDate, a.AssetName AS Party, 4 AS LineOrder, 4500 AS AccountCode, CAST(0 AS MONEY) AS Debit, (a.DisposalProceeds + a.DisposalAccumDep - (a.Cost + CAST(COALESCE(rv.SumReval, 0) AS MONEY))) AS Credit, N'Gain on sale of the asset' AS LineText, IIF(a.CostCenterID Is Null, 0, a.CostCenterID) AS CostCenter
FROM [dbo].[FixedAssets] AS a LEFT JOIN [en].[qryAssetRevalTotals] AS rv ON a.AssetID = rv.AssetID
WHERE a.Status = N'DISPOSED' AND (a.DisposalProceeds + a.DisposalAccumDep - (a.Cost + CAST(COALESCE(rv.SumReval, 0) AS MONEY))) > 0
UNION ALL
SELECT N'ASSET_DISPOSAL' AS SourceType, a.AssetID AS SourceID, a.AssetCode AS SourceNumber, a.DisposalDate AS SourceDate, a.AssetName AS Party, 5 AS LineOrder, 5650 AS AccountCode, -(a.DisposalProceeds + a.DisposalAccumDep - (a.Cost + CAST(COALESCE(rv.SumReval, 0) AS MONEY))) AS Debit, CAST(0 AS MONEY) AS Credit, N'Loss on sale / disposal of the asset' AS LineText, IIF(a.CostCenterID Is Null, 0, a.CostCenterID) AS CostCenter
FROM [dbo].[FixedAssets] AS a LEFT JOIN [en].[qryAssetRevalTotals] AS rv ON a.AssetID = rv.AssetID
WHERE a.Status = N'DISPOSED' AND (a.DisposalProceeds + a.DisposalAccumDep - (a.Cost + CAST(COALESCE(rv.SumReval, 0) AS MONEY))) < 0
UNION ALL
SELECT N'ASSET_DISPOSAL' AS SourceType, a.AssetID AS SourceID, a.AssetCode AS SourceNumber, a.DisposalDate AS SourceDate, a.AssetName AS Party, 6 AS LineOrder, 2200 AS AccountCode, CAST(0 AS MONEY) AS Debit, a.DisposalVAT AS Credit, N'Output VAT on the asset sale' AS LineText, IIF(a.CostCenterID Is Null, 0, a.CostCenterID) AS CostCenter
FROM [dbo].[FixedAssets] AS a LEFT JOIN [en].[qryAssetRevalTotals] AS rv ON a.AssetID = rv.AssetID
WHERE a.Status = N'DISPOSED' AND a.DisposalVAT <> 0
UNION ALL
SELECT N'ASSET_DISPOSAL' AS SourceType, a.AssetID AS SourceID, a.AssetCode AS SourceNumber, a.DisposalDate AS SourceDate, a.AssetName AS Party, 7 AS LineOrder, 3500 AS AccountCode, CAST(COALESCE(rv.SumSurplus, 0) AS MONEY) AS Debit, CAST(0 AS MONEY) AS Credit, N'Revaluation surplus of the disposed asset' AS LineText, IIF(a.CostCenterID Is Null, 0, a.CostCenterID) AS CostCenter
FROM [dbo].[FixedAssets] AS a LEFT JOIN [en].[qryAssetRevalTotals] AS rv ON a.AssetID = rv.AssetID
WHERE a.Status = N'DISPOSED' AND CAST(COALESCE(rv.SumSurplus, 0) AS MONEY) > 0
UNION ALL
SELECT N'ASSET_DISPOSAL' AS SourceType, a.AssetID AS SourceID, a.AssetCode AS SourceNumber, a.DisposalDate AS SourceDate, a.AssetName AS Party, 8 AS LineOrder, 3300 AS AccountCode, CAST(0 AS MONEY) AS Debit, CAST(COALESCE(rv.SumSurplus, 0) AS MONEY) AS Credit, N'Revaluation surplus of the disposed asset' AS LineText, IIF(a.CostCenterID Is Null, 0, a.CostCenterID) AS CostCenter
FROM [dbo].[FixedAssets] AS a LEFT JOIN [en].[qryAssetRevalTotals] AS rv ON a.AssetID = rv.AssetID
WHERE a.Status = N'DISPOSED' AND CAST(COALESCE(rv.SumSurplus, 0) AS MONEY) > 0;
GO
CREATE OR ALTER VIEW [en].[qryJournalAssetReval] AS
-- أسطر قيود إعادة تقييم الأصول الثابتة
SELECT N'ASSET_REVAL' AS SourceType, r.RevaluationID AS SourceID, r.RevalNumber AS SourceNumber, r.RevalDate AS SourceDate, a.AssetName AS Party, 1 AS LineOrder, a.AssetAccount AS AccountCode, IIF(r.ValueChange > 0, r.ValueChange, 0) AS Debit, IIF(r.ValueChange < 0, -r.ValueChange, 0) AS Credit, a.AssetName AS LineText, IIF(r.RevalCenter Is Null, 0, r.RevalCenter) AS CostCenter
FROM [dbo].[AssetRevaluations] AS r INNER JOIN [dbo].[FixedAssets] AS a ON r.AssetID = a.AssetID
WHERE r.ValueChange <> 0
UNION ALL
SELECT N'ASSET_REVAL' AS SourceType, r.RevaluationID AS SourceID, r.RevalNumber AS SourceNumber, r.RevalDate AS SourceDate, a.AssetName AS Party, 2 AS LineOrder, 3500 AS AccountCode, IIF(r.SurplusPart < 0, -r.SurplusPart, 0) AS Debit, IIF(r.SurplusPart > 0, r.SurplusPart, 0) AS Credit, N'Fixed asset revaluation surplus' AS LineText, IIF(r.RevalCenter Is Null, 0, r.RevalCenter) AS CostCenter
FROM [dbo].[AssetRevaluations] AS r INNER JOIN [dbo].[FixedAssets] AS a ON r.AssetID = a.AssetID
WHERE r.SurplusPart <> 0
UNION ALL
SELECT N'ASSET_REVAL' AS SourceType, r.RevaluationID AS SourceID, r.RevalNumber AS SourceNumber, r.RevalDate AS SourceDate, a.AssetName AS Party, 3 AS LineOrder, 5660 AS AccountCode, IIF(r.LossPart > 0, r.LossPart, 0) AS Debit, IIF(r.LossPart < 0, -r.LossPart, 0) AS Credit, N'Fixed asset impairment' AS LineText, IIF(r.RevalCenter Is Null, 0, r.RevalCenter) AS CostCenter
FROM [dbo].[AssetRevaluations] AS r INNER JOIN [dbo].[FixedAssets] AS a ON r.AssetID = a.AssetID
WHERE r.LossPart <> 0;
GO
CREATE OR ALTER VIEW [en].[qryJournalAssetTransfer] AS
-- أسطر قيود نقل الأصول الثابتة بين مراكز التكلفة
SELECT N'ASSET_TRANSFER' AS SourceType, t.TransferID AS SourceID, t.TransferNumber AS SourceNumber, t.TransferDate AS SourceDate, a.AssetName AS Party, 1 AS LineOrder, a.AssetAccount AS AccountCode, t.AssetValue AS Debit, CAST(0 AS MONEY) AS Credit, a.AssetName AS LineText, IIF(t.ToCenterID Is Null, 0, t.ToCenterID) AS CostCenter
FROM [dbo].[AssetTransfers] AS t INNER JOIN [dbo].[FixedAssets] AS a ON t.AssetID = a.AssetID
WHERE t.AssetValue <> 0
UNION ALL
SELECT N'ASSET_TRANSFER' AS SourceType, t.TransferID AS SourceID, t.TransferNumber AS SourceNumber, t.TransferDate AS SourceDate, a.AssetName AS Party, 2 AS LineOrder, a.AssetAccount AS AccountCode, CAST(0 AS MONEY) AS Debit, t.AssetValue AS Credit, a.AssetName AS LineText, IIF(t.FromCenterID Is Null, 0, t.FromCenterID) AS CostCenter
FROM [dbo].[AssetTransfers] AS t INNER JOIN [dbo].[FixedAssets] AS a ON t.AssetID = a.AssetID
WHERE t.AssetValue <> 0
UNION ALL
SELECT N'ASSET_TRANSFER' AS SourceType, t.TransferID AS SourceID, t.TransferNumber AS SourceNumber, t.TransferDate AS SourceDate, a.AssetName AS Party, 3 AS LineOrder, 1790 AS AccountCode, t.AccumDep AS Debit, CAST(0 AS MONEY) AS Credit, N'Accumulated depreciation of the asset' AS LineText, IIF(t.FromCenterID Is Null, 0, t.FromCenterID) AS CostCenter
FROM [dbo].[AssetTransfers] AS t INNER JOIN [dbo].[FixedAssets] AS a ON t.AssetID = a.AssetID
WHERE t.AccumDep <> 0
UNION ALL
SELECT N'ASSET_TRANSFER' AS SourceType, t.TransferID AS SourceID, t.TransferNumber AS SourceNumber, t.TransferDate AS SourceDate, a.AssetName AS Party, 4 AS LineOrder, 1790 AS AccountCode, CAST(0 AS MONEY) AS Debit, t.AccumDep AS Credit, N'Accumulated depreciation of the asset' AS LineText, IIF(t.ToCenterID Is Null, 0, t.ToCenterID) AS CostCenter
FROM [dbo].[AssetTransfers] AS t INNER JOIN [dbo].[FixedAssets] AS a ON t.AssetID = a.AssetID
WHERE t.AccumDep <> 0;
GO
CREATE OR ALTER VIEW [en].[qryJournalRepShortage] AS
-- أسطر قيود عجز بضاعة المندوب المحمَّل عليه سلفة
SELECT N'REP_SHORTAGE' AS SourceType, d.RepDayID AS SourceID, d.DayNumber AS SourceNumber, d.SettledAt AS SourceDate, r.RepName AS Party, 1 AS LineOrder, 1600 AS AccountCode, d.GoodsShortage AS Debit, CAST(0 AS MONEY) AS Credit, N'Van goods shortage as an advance on the rep' AS LineText, 0 AS CostCenter
FROM [dbo].[RepDays] AS d INNER JOIN [en].[qryLocSalesReps] AS r ON d.SalesRepID = r.SalesRepID
WHERE d.Status = N'SETTLED' AND d.GoodsShortage <> 0 AND d.AdvanceEmployeeID Is Not Null
UNION ALL
SELECT N'REP_SHORTAGE' AS SourceType, d.RepDayID AS SourceID, d.DayNumber AS SourceNumber, d.SettledAt AS SourceDate, r.RepName AS Party, 2 AS LineOrder, 5200 AS AccountCode, CAST(0 AS MONEY) AS Debit, d.GoodsShortage AS Credit, N'Van goods shortage as an advance on the rep' AS LineText, 0 AS CostCenter
FROM [dbo].[RepDays] AS d INNER JOIN [en].[qryLocSalesReps] AS r ON d.SalesRepID = r.SalesRepID
WHERE d.Status = N'SETTLED' AND d.GoodsShortage <> 0 AND d.AdvanceEmployeeID Is Not Null;
GO
CREATE OR ALTER VIEW [en].[qryDepreciationLines] AS
-- أسطر قيود الإهلاك الشهرية مع اسم الأصل
SELECT r.RunID, r.RunNumber, r.RunMonth, d.[LineNo], d.AssetID, d.Amount, a.AssetName,
       IIF(d.DepCenter Is Null, IIF(a.CostCenterID Is Null, 0, a.CostCenterID), d.DepCenter) AS LineCenter
FROM ([dbo].[DepreciationRuns] AS r INNER JOIN [dbo].[AssetDepreciations] AS d ON r.RunID = d.RunID)
     INNER JOIN [dbo].[FixedAssets] AS a ON d.AssetID = a.AssetID;
GO
CREATE OR ALTER VIEW [en].[qryJournalDepreciation] AS
-- أسطر قيود الإهلاك الشهرية: مصروف الإهلاك ومجمع الإهلاك لكل أصل
SELECT N'DEPRECIATION' AS SourceType, d.RunID AS SourceID, d.RunNumber AS SourceNumber, d.RunMonth AS SourceDate, N'Monthly depreciation' AS Party, 2 * d.[LineNo] - 1 AS LineOrder, 5600 AS AccountCode, d.Amount AS Debit, CAST(0 AS MONEY) AS Credit, d.AssetName AS LineText, d.LineCenter AS CostCenter
FROM [en].[qryDepreciationLines] AS d
WHERE d.Amount <> 0
UNION ALL
SELECT N'DEPRECIATION' AS SourceType, d.RunID AS SourceID, d.RunNumber AS SourceNumber, d.RunMonth AS SourceDate, N'Monthly depreciation' AS Party, 2 * d.[LineNo] AS LineOrder, 1790 AS AccountCode, CAST(0 AS MONEY) AS Debit, d.Amount AS Credit, d.AssetName AS LineText, d.LineCenter AS CostCenter
FROM [en].[qryDepreciationLines] AS d
WHERE d.Amount <> 0;
GO
CREATE OR ALTER VIEW [en].[qryPayrollTotals] AS
-- مجاميع كل مسير رواتب لقيده
SELECT PayrollRunID, Sum(Basic + Housing - AbsenceDeduction) AS SumSalaries,
       Sum(OtherAllow + Overtime + Additions) AS SumAllowances, Sum(GosiEmployer) AS SumGosiER,
       Sum(GosiEmployee + GosiEmployer) AS SumGosi, Sum(AdvanceDeduction) AS SumAdvance,
       Sum(OtherDeduction) AS SumOtherDed, Sum(NetPay) AS SumNet, Count(*) AS LineCount
FROM [dbo].[PayrollLines]
GROUP BY PayrollRunID;
GO
CREATE OR ALTER VIEW [en].[qryPayrollCenterTotals] AS
-- مجاميع كل مسير رواتب لكل مركز تكلفة لقيده
SELECT PayrollRunID, IIF(CostCenterID Is Null, 0, CostCenterID) AS CenterKey,
       Sum(Basic + Housing - AbsenceDeduction) AS SumSalaries, Sum(OtherAllow + Overtime + Additions) AS SumAllowances,
       Sum(GosiEmployer) AS SumGosiER, Sum(GosiEmployee + GosiEmployer) AS SumGosi, Sum(AdvanceDeduction) AS SumAdvance,
       Sum(OtherDeduction) AS SumOtherDed, Sum(NetPay) AS SumNet
FROM [dbo].[PayrollLines]
GROUP BY PayrollRunID, IIF(CostCenterID Is Null, 0, CostCenterID);
GO
CREATE OR ALTER VIEW [en].[qryJournalPayroll] AS
-- أسطر قيود مسيرات الرواتب المرحَّلة وصرفها
SELECT N'PAYROLL' AS SourceType, r.PayrollRunID AS SourceID, r.RunNumber AS SourceNumber, r.PayMonth AS SourceDate, N'Payroll' AS Party, 1 + 10 * t.CenterKey AS LineOrder, 5500 AS AccountCode, t.SumSalaries AS Debit, CAST(0 AS MONEY) AS Credit, N'Payroll' AS LineText, t.CenterKey AS CostCenter
FROM [dbo].[PayrollRuns] AS r INNER JOIN [en].[qryPayrollCenterTotals] AS t ON r.PayrollRunID = t.PayrollRunID
WHERE r.Status = N'POSTED' AND t.SumSalaries <> 0
UNION ALL
SELECT N'PAYROLL' AS SourceType, r.PayrollRunID AS SourceID, r.RunNumber AS SourceNumber, r.PayMonth AS SourceDate, N'Payroll' AS Party, 2 + 10 * t.CenterKey AS LineOrder, 5510 AS AccountCode, t.SumAllowances AS Debit, CAST(0 AS MONEY) AS Credit, N'Allowances and overtime' AS LineText, t.CenterKey AS CostCenter
FROM [dbo].[PayrollRuns] AS r INNER JOIN [en].[qryPayrollCenterTotals] AS t ON r.PayrollRunID = t.PayrollRunID
WHERE r.Status = N'POSTED' AND t.SumAllowances <> 0
UNION ALL
SELECT N'PAYROLL' AS SourceType, r.PayrollRunID AS SourceID, r.RunNumber AS SourceNumber, r.PayMonth AS SourceDate, N'Payroll' AS Party, 3 + 10 * t.CenterKey AS LineOrder, 5520 AS AccountCode, t.SumGosiER AS Debit, CAST(0 AS MONEY) AS Credit, N'Social insurance - employer share' AS LineText, t.CenterKey AS CostCenter
FROM [dbo].[PayrollRuns] AS r INNER JOIN [en].[qryPayrollCenterTotals] AS t ON r.PayrollRunID = t.PayrollRunID
WHERE r.Status = N'POSTED' AND t.SumGosiER <> 0
UNION ALL
SELECT N'PAYROLL' AS SourceType, r.PayrollRunID AS SourceID, r.RunNumber AS SourceNumber, r.PayMonth AS SourceDate, N'Payroll' AS Party, 4 + 10 * t.CenterKey AS LineOrder, 2320 AS AccountCode, CAST(0 AS MONEY) AS Debit, t.SumGosi AS Credit, N'Social insurance payable' AS LineText, t.CenterKey AS CostCenter
FROM [dbo].[PayrollRuns] AS r INNER JOIN [en].[qryPayrollCenterTotals] AS t ON r.PayrollRunID = t.PayrollRunID
WHERE r.Status = N'POSTED' AND t.SumGosi <> 0
UNION ALL
SELECT N'PAYROLL' AS SourceType, r.PayrollRunID AS SourceID, r.RunNumber AS SourceNumber, r.PayMonth AS SourceDate, N'Payroll' AS Party, 5 + 10 * t.CenterKey AS LineOrder, 1600 AS AccountCode, CAST(0 AS MONEY) AS Debit, t.SumAdvance AS Credit, N'Advance deductions' AS LineText, t.CenterKey AS CostCenter
FROM [dbo].[PayrollRuns] AS r INNER JOIN [en].[qryPayrollCenterTotals] AS t ON r.PayrollRunID = t.PayrollRunID
WHERE r.Status = N'POSTED' AND t.SumAdvance <> 0
UNION ALL
SELECT N'PAYROLL' AS SourceType, r.PayrollRunID AS SourceID, r.RunNumber AS SourceNumber, r.PayMonth AS SourceDate, N'Payroll' AS Party, 6 + 10 * t.CenterKey AS LineOrder, 4200 AS AccountCode, CAST(0 AS MONEY) AS Debit, t.SumOtherDed AS Credit, N'Penalties and deductions' AS LineText, t.CenterKey AS CostCenter
FROM [dbo].[PayrollRuns] AS r INNER JOIN [en].[qryPayrollCenterTotals] AS t ON r.PayrollRunID = t.PayrollRunID
WHERE r.Status = N'POSTED' AND t.SumOtherDed <> 0
UNION ALL
SELECT N'PAYROLL' AS SourceType, r.PayrollRunID AS SourceID, r.RunNumber AS SourceNumber, r.PayMonth AS SourceDate, N'Payroll' AS Party, 7 + 10 * t.CenterKey AS LineOrder, 2310 AS AccountCode, CAST(0 AS MONEY) AS Debit, t.SumNet AS Credit, N'Net salaries' AS LineText, t.CenterKey AS CostCenter
FROM [dbo].[PayrollRuns] AS r INNER JOIN [en].[qryPayrollCenterTotals] AS t ON r.PayrollRunID = t.PayrollRunID
WHERE r.Status = N'POSTED' AND t.SumNet <> 0
UNION ALL
SELECT N'PAYROLL_PAYMENT' AS SourceType, r.PayrollRunID AS SourceID, r.RunNumber AS SourceNumber, r.PaidDate AS SourceDate, N'Salary payment' AS Party, 1 AS LineOrder, 2310 AS AccountCode, r.PaidAmount AS Debit, CAST(0 AS MONEY) AS Credit, N'Net salaries' AS LineText, 0 AS CostCenter
FROM [dbo].[PayrollRuns] AS r
WHERE r.Status = N'POSTED' AND r.PaidAmount <> 0
UNION ALL
SELECT N'PAYROLL_PAYMENT' AS SourceType, r.PayrollRunID AS SourceID, r.RunNumber AS SourceNumber, r.PaidDate AS SourceDate, N'Salary payment' AS Party, 2 AS LineOrder, IIF(r.PaidFrom = N'BANK', 120000 + r.BankID, 110000 + r.CashBoxID) AS AccountCode, CAST(0 AS MONEY) AS Debit, r.PaidAmount AS Credit, N'Salary payment' AS LineText, 0 AS CostCenter
FROM [dbo].[PayrollRuns] AS r
WHERE r.Status = N'POSTED' AND r.PaidAmount <> 0;
GO
CREATE OR ALTER VIEW [en].[qryCommissionCenterTotals] AS
-- عمولات كل مسير لكل مركز تكلفة لقيده
SELECT CommissionRunID, IIF(CostCenterID Is Null, 0, CostCenterID) AS CenterKey, Sum(Commission) AS SumCommission
FROM [dbo].[CommissionLines]
GROUP BY CommissionRunID, IIF(CostCenterID Is Null, 0, CostCenterID);
GO
CREATE OR ALTER VIEW [en].[qryJournalCommission] AS
-- أسطر قيود مسيرات العمولات المرحَّلة
SELECT N'COMMISSION' AS SourceType, r.CommissionRunID AS SourceID, r.RunNumber AS SourceNumber, r.RunMonth AS SourceDate, N'Sales rep commissions' AS Party, 1 + 10 * t.CenterKey AS LineOrder, 5530 AS AccountCode, t.SumCommission AS Debit, CAST(0 AS MONEY) AS Credit, N'Sales rep commissions' AS LineText, t.CenterKey AS CostCenter
FROM [dbo].[CommissionRuns] AS r INNER JOIN [en].[qryCommissionCenterTotals] AS t ON r.CommissionRunID = t.CommissionRunID
WHERE r.Status = N'POSTED' AND t.SumCommission <> 0
UNION ALL
SELECT N'COMMISSION' AS SourceType, r.CommissionRunID AS SourceID, r.RunNumber AS SourceNumber, r.RunMonth AS SourceDate, N'Sales rep commissions' AS Party, 2 + 10 * t.CenterKey AS LineOrder, 2330 AS AccountCode, CAST(0 AS MONEY) AS Debit, t.SumCommission AS Credit, N'Commissions payable' AS LineText, t.CenterKey AS CostCenter
FROM [dbo].[CommissionRuns] AS r INNER JOIN [en].[qryCommissionCenterTotals] AS t ON r.CommissionRunID = t.CommissionRunID
WHERE r.Status = N'POSTED' AND t.SumCommission <> 0;
GO
CREATE OR ALTER VIEW [en].[qryJournalBankTx] AS
-- أسطر قيود الحركات البنكية: الإيداع والسحب وتسوية مدى والتحويل والحركات الأخرى
SELECT N'BANK_TX' AS SourceType, t.BankTxID AS SourceID, t.TxNumber AS SourceNumber, t.TxDate AS SourceDate, t.Description AS Party, 1 AS LineOrder, 120000 + t.BankID AS AccountCode, t.Amount AS Debit, CAST(0 AS MONEY) AS Credit, N'Cash deposit' AS LineText, 0 AS CostCenter
FROM [dbo].[BankTransactions] AS t
WHERE t.TxType = N'DEPOSIT'
UNION ALL
SELECT N'BANK_TX' AS SourceType, t.BankTxID AS SourceID, t.TxNumber AS SourceNumber, t.TxDate AS SourceDate, t.Description AS Party, 2 AS LineOrder, 110000 + t.CashBoxID AS AccountCode, CAST(0 AS MONEY) AS Debit, t.Amount AS Credit, N'Deposit in the bank' AS LineText, 0 AS CostCenter
FROM [dbo].[BankTransactions] AS t
WHERE t.TxType = N'DEPOSIT'
UNION ALL
SELECT N'BANK_TX' AS SourceType, t.BankTxID AS SourceID, t.TxNumber AS SourceNumber, t.TxDate AS SourceDate, t.Description AS Party, 1 AS LineOrder, 110000 + t.CashBoxID AS AccountCode, t.Amount AS Debit, CAST(0 AS MONEY) AS Credit, N'Withdrawal from the bank' AS LineText, 0 AS CostCenter
FROM [dbo].[BankTransactions] AS t
WHERE t.TxType = N'WITHDRAW'
UNION ALL
SELECT N'BANK_TX' AS SourceType, t.BankTxID AS SourceID, t.TxNumber AS SourceNumber, t.TxDate AS SourceDate, t.Description AS Party, 2 AS LineOrder, 120000 + t.BankID AS AccountCode, CAST(0 AS MONEY) AS Debit, t.Amount AS Credit, N'Cash withdrawal' AS LineText, 0 AS CostCenter
FROM [dbo].[BankTransactions] AS t
WHERE t.TxType = N'WITHDRAW'
UNION ALL
SELECT N'BANK_TX' AS SourceType, t.BankTxID AS SourceID, t.TxNumber AS SourceNumber, t.TxDate AS SourceDate, t.Description AS Party, 1 AS LineOrder, 120000 + t.BankID AS AccountCode, t.Amount - t.FeeAmount - t.FeeVAT AS Debit, CAST(0 AS MONEY) AS Credit, N'Net Mada settlement' AS LineText, 0 AS CostCenter
FROM [dbo].[BankTransactions] AS t
WHERE t.TxType = N'SETTLEMENT' AND t.Amount - t.FeeAmount - t.FeeVAT <> 0
UNION ALL
SELECT N'BANK_TX' AS SourceType, t.BankTxID AS SourceID, t.TxNumber AS SourceNumber, t.TxDate AS SourceDate, t.Description AS Party, 2 AS LineOrder, 5610 AS AccountCode, t.FeeAmount AS Debit, CAST(0 AS MONEY) AS Credit, N'Mada fee' AS LineText, 0 AS CostCenter
FROM [dbo].[BankTransactions] AS t
WHERE t.TxType = N'SETTLEMENT' AND t.FeeAmount <> 0
UNION ALL
SELECT N'BANK_TX' AS SourceType, t.BankTxID AS SourceID, t.TxNumber AS SourceNumber, t.TxDate AS SourceDate, t.Description AS Party, 3 AS LineOrder, 1500 AS AccountCode, t.FeeVAT AS Debit, CAST(0 AS MONEY) AS Credit, N'Fee VAT' AS LineText, 0 AS CostCenter
FROM [dbo].[BankTransactions] AS t
WHERE t.FeeVAT <> 0 AND (t.TxType = N'SETTLEMENT' OR t.TxType = N'OTHER_OUT')
UNION ALL
SELECT N'BANK_TX' AS SourceType, t.BankTxID AS SourceID, t.TxNumber AS SourceNumber, t.TxDate AS SourceDate, t.Description AS Party, 4 AS LineOrder, 1200 AS AccountCode, CAST(0 AS MONEY) AS Debit, t.Amount AS Credit, N'Mada collections' AS LineText, 0 AS CostCenter
FROM [dbo].[BankTransactions] AS t
WHERE t.TxType = N'SETTLEMENT'
UNION ALL
SELECT N'BANK_TX' AS SourceType, t.BankTxID AS SourceID, t.TxNumber AS SourceNumber, t.TxDate AS SourceDate, t.Description AS Party, 1 AS LineOrder, 120000 + t.ToBankID AS AccountCode, t.Amount AS Debit, CAST(0 AS MONEY) AS Credit, N'Incoming transfer' AS LineText, 0 AS CostCenter
FROM [dbo].[BankTransactions] AS t
WHERE t.TxType = N'TRANSFER'
UNION ALL
SELECT N'BANK_TX' AS SourceType, t.BankTxID AS SourceID, t.TxNumber AS SourceNumber, t.TxDate AS SourceDate, t.Description AS Party, 2 AS LineOrder, 120000 + t.BankID AS AccountCode, CAST(0 AS MONEY) AS Debit, t.Amount AS Credit, N'Outgoing transfer' AS LineText, 0 AS CostCenter
FROM [dbo].[BankTransactions] AS t
WHERE t.TxType = N'TRANSFER'
UNION ALL
SELECT N'BANK_TX' AS SourceType, t.BankTxID AS SourceID, t.TxNumber AS SourceNumber, t.TxDate AS SourceDate, t.Description AS Party, 1 AS LineOrder, 120000 + t.BankID AS AccountCode, t.Amount AS Debit, CAST(0 AS MONEY) AS Credit, t.Reference AS LineText, 0 AS CostCenter
FROM [dbo].[BankTransactions] AS t
WHERE t.TxType = N'OTHER_IN'
UNION ALL
SELECT N'BANK_TX' AS SourceType, t.BankTxID AS SourceID, t.TxNumber AS SourceNumber, t.TxDate AS SourceDate, t.Description AS Party, 2 AS LineOrder, t.CounterAccount AS AccountCode, CAST(0 AS MONEY) AS Debit, t.Amount AS Credit, t.Description AS LineText, 0 AS CostCenter
FROM [dbo].[BankTransactions] AS t
WHERE t.TxType = N'OTHER_IN'
UNION ALL
SELECT N'BANK_TX' AS SourceType, t.BankTxID AS SourceID, t.TxNumber AS SourceNumber, t.TxDate AS SourceDate, t.Description AS Party, 1 AS LineOrder, t.CounterAccount AS AccountCode, t.Amount - t.FeeVAT AS Debit, CAST(0 AS MONEY) AS Credit, t.Description AS LineText, 0 AS CostCenter
FROM [dbo].[BankTransactions] AS t
WHERE t.TxType = N'OTHER_OUT'
UNION ALL
SELECT N'BANK_TX' AS SourceType, t.BankTxID AS SourceID, t.TxNumber AS SourceNumber, t.TxDate AS SourceDate, t.Description AS Party, 2 AS LineOrder, 120000 + t.BankID AS AccountCode, CAST(0 AS MONEY) AS Debit, t.Amount AS Credit, t.Reference AS LineText, 0 AS CostCenter
FROM [dbo].[BankTransactions] AS t
WHERE t.TxType = N'OTHER_OUT';
GO
CREATE OR ALTER VIEW [en].[qryBankItemSums] AS
-- صافي كل عملية على حساب كل بنك في القيود
SELECT l.AccountCode - 120000 AS BankID, e.SourceType, e.SourceID, Max(e.EntryDate) AS ItemDate,
       Max(e.SourceNumber) AS ItemNumber, Max(e.Description) AS ItemText, Sum(l.Debit) - Sum(l.Credit) AS ItemAmount
FROM [dbo].[JournalEntries] AS e INNER JOIN [dbo].[JournalLines] AS l ON e.EntryID = l.EntryID
WHERE l.AccountCode > 120000 AND l.AccountCode < 130000
GROUP BY l.AccountCode, e.SourceType, e.SourceID;
GO
CREATE OR ALTER VIEW [en].[qryBankItems] AS
-- عمليات البنوك: المبلغ، وهل طابقت كشف البنك ومبلغها يوم المطابقة
SELECT i.BankID, i.SourceType, i.SourceID, i.ItemDate, i.ItemNumber, i.ItemText, i.ItemAmount,
       t.TypeName, c.ReconciliationID, c.ClearedAmount, IIF(c.ClearingID Is Null, 0, 1) AS IsCleared
FROM ([en].[qryBankItemSums] AS i INNER JOIN [en].[qryLocJournalSourceTypes] AS t ON i.SourceType = t.SourceType)
     LEFT JOIN [dbo].[BankClearings] AS c ON (i.BankID = c.BankID AND i.SourceType = c.SourceType AND i.SourceID = c.SourceID)
WHERE i.ItemAmount <> 0;
GO
CREATE OR ALTER VIEW [en].[qryBankTotals] AS
-- رصيد كل بنك في الدفاتر
SELECT BankID, Sum(ItemAmount) AS BookBalance, Max(ItemDate) AS LastItemDate
FROM [en].[qryBankItemSums]
GROUP BY BankID;
GO
CREATE OR ALTER VIEW [en].[BankBalanceQuery] AS
-- أرصدة البنوك في الدفاتر
SELECT k.BankID, k.BankName, k.AccountNo, k.IBAN, k.IsActive, CAST(COALESCE(t.BookBalance, 0) AS MONEY) AS Balance, t.LastItemDate
FROM [en].[qryLocBanks] AS k LEFT JOIN [en].[qryBankTotals] AS t ON k.BankID = t.BankID;
GO
CREATE OR ALTER VIEW [en].[qryAssetDepTotals] AS
-- مجموع إهلاك كل أصل في القيود الشهرية
SELECT AssetID, Sum(Amount) AS SumDep, Count(*) AS DepCount
FROM [dbo].[AssetDepreciations]
GROUP BY AssetID;
GO
CREATE OR ALTER VIEW [en].[FixedAssetsQuery] AS
-- سجل الأصول الثابتة: التكلفة ومجمع الإهلاك والقيمة الدفترية والقسط الشهري
SELECT a.AssetID, a.AssetCode, a.AssetName, a.AssetAccount, c.AccountName AS AssetGroup, a.PurchaseDate, a.Cost,
       a.SalvageValue, a.UsefulLifeMonths, a.DepStartDate, a.Status, IIF(a.Status = N'ACTIVE', N'Open', N'Disposed') AS StatusName,
       a.DepMethod, IIF(a.DepMethod = N'DB', N'Declining', N'Straight line') AS MethodName, CAST(COALESCE(rv.SumReval, 0) AS MONEY) AS RevalTotal,
       a.OpeningAccumDep + CAST(COALESCE(t.SumDep, 0) AS MONEY) AS AccumDep, a.Cost + CAST(COALESCE(rv.SumReval, 0) AS MONEY) - a.OpeningAccumDep - CAST(COALESCE(t.SumDep, 0) AS MONEY) AS BookValue,
       IIF(a.DepMethod = N'DB', ROUND((a.Cost + CAST(COALESCE(rv.SumReval, 0) AS MONEY) - a.OpeningAccumDep - CAST(COALESCE(t.SumDep, 0) AS MONEY)) * IIF(a.DepRate > 0, a.DepRate, 24 * 1e0 / a.UsefulLifeMonths) * 1e0 / 12, 2), IIF(lr.AssetID Is Null, ROUND((a.Cost - a.SalvageValue) * 1e0 / a.UsefulLifeMonths, 2), ROUND((lr.NewValue - a.SalvageValue) * 1e0 / lr.MonthsLeft, 2))) AS MonthlyDep,
       CAST(COALESCE(t.DepCount, 0) AS MONEY) AS DepMonths, a.DisposalDate, a.DisposalProceeds
FROM ((([dbo].[FixedAssets] AS a INNER JOIN [en].[qryLocAccounts] AS c ON a.AssetAccount = c.AccountCode)
     LEFT JOIN [en].[qryAssetDepTotals] AS t ON a.AssetID = t.AssetID)
     LEFT JOIN [en].[qryAssetRevalTotals] AS rv ON a.AssetID = rv.AssetID)
     LEFT JOIN [en].[qryAssetLastReval] AS lr ON a.AssetID = lr.AssetID;
GO
CREATE OR ALTER VIEW [en].[AuditTrailQuery] AS
-- سجل التدقيق: كل عملية بمن قام بها ووقتها، وحقولها بالقيمة قبل وبعد
SELECT a.LogID, a.LogDate, a.EmployeeID, IIF(e.EmployeeName Is Null, N'-', e.EmployeeName) AS UserName, a.ActionType,
       IIF(a.ActionType = N'ADD', N'Add', IIF(a.ActionType = N'EDIT', N'Edit', IIF(a.ActionType = N'DELETE', N'Delete', IIF(a.ActionType = N'LOGIN', N'Login', IIF(a.ActionType = N'LOGOUT', N'Exit', a.ActionType))))) AS ActionLabel,
       a.ObjectName, a.RecordID, a.RecordLabel, a.ComputerName, a.Details,
       c.[LineNo], c.FieldCaption, c.OldValue, c.NewValue
FROM ([dbo].[AuditLog] AS a LEFT JOIN [dbo].[Employees] AS e ON a.EmployeeID = e.EmployeeID)
     LEFT JOIN [dbo].[AuditChanges] AS c ON a.LogID = c.LogID;
GO
CREATE OR ALTER VIEW [en].[qryAdvanceMoves] AS
-- حركات سلف الموظفين: الصرف والسداد النقدي والخصم من الرواتب
SELECT v.AdvanceEmployeeID AS EmployeeID, v.VoucherDate AS MoveDate, IIF(v.VoucherType = N'OUT', v.Amount, -v.Amount) AS MoveAmount
FROM [dbo].[CashVouchers] AS v
WHERE v.Category = N'ADVANCE' AND v.AdvanceEmployeeID Is Not Null
UNION ALL
SELECT l.EmployeeID, r.PayMonth, -l.AdvanceDeduction
FROM [dbo].[PayrollLines] AS l INNER JOIN [dbo].[PayrollRuns] AS r ON l.PayrollRunID = r.PayrollRunID
WHERE r.Status = N'POSTED' AND l.AdvanceDeduction <> 0
UNION ALL
SELECT d.AdvanceEmployeeID, d.SettledAt, d.GoodsShortage
FROM [dbo].[RepDays] AS d
WHERE d.Status = N'SETTLED' AND d.GoodsShortage <> 0 AND d.AdvanceEmployeeID Is Not Null;
GO
CREATE OR ALTER VIEW [en].[qryAdvanceTotals] AS
-- رصيد سلف كل موظف
SELECT EmployeeID, Sum(MoveAmount) AS AdvanceBalance
FROM [en].[qryAdvanceMoves]
GROUP BY EmployeeID;
GO
CREATE OR ALTER VIEW [en].[AdvanceBalanceQuery] AS
-- أرصدة سلف الموظفين
SELECT e.EmployeeID, e.EmployeeName, e.AdvanceInstallment, CAST(COALESCE(t.AdvanceBalance, 0) AS MONEY) AS Balance
FROM [dbo].[Employees] AS e LEFT JOIN [en].[qryAdvanceTotals] AS t ON e.EmployeeID = t.EmployeeID
WHERE t.AdvanceBalance <> 0;
GO
CREATE OR ALTER VIEW [en].[PayrollSheetQuery] AS
-- مسير الرواتب المختار بأسطر الموظفين
SELECT r.PayrollRunID, r.RunNumber, r.PayMonth, r.Status, l.EmployeeName, l.Basic, l.Housing, l.OtherAllow, l.Overtime,
       l.Additions, l.Basic + l.Housing + l.OtherAllow + l.Overtime + l.Additions AS Gross, l.AbsenceDeduction,
       l.AdvanceDeduction, l.OtherDeduction, l.GosiEmployee, l.GosiEmployer, l.NetPay
FROM [dbo].[PayrollRuns] AS r INNER JOIN [dbo].[PayrollLines] AS l ON r.PayrollRunID = l.PayrollRunID CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE r.PayrollRunID = qp.[qp_PayrollRunID];
GO
CREATE OR ALTER VIEW [en].[ChequesQuery] AS
-- الشيكات الواردة والصادرة مع العميل أو المورد وحالتها
SELECT q.ChequeID, q.ChequeRef, q.Direction, IIF(q.Direction = N'IN', N'Received', N'Issued') AS DirectionName,
       IIF(q.Direction = N'IN', c.CustomerName, s.SupplierName) AS PartyName, q.ChequeNo, q.DrawerBank,
       k.BankName, q.IssueDate, q.DueDate, q.Amount, q.Status,
       IIF(q.Status = N'PENDING', N'Under collection', IIF(q.Status = N'COLLECTED', IIF(q.Direction = N'IN', N'Collected', N'Expense'), N'Bounced')) AS StatusName, q.StatusDate, q.Notes
FROM (([dbo].[Cheques] AS q LEFT JOIN [en].[qryLocCustomers] AS c ON q.CustomerID = c.CustomerID)
      LEFT JOIN [en].[qryLocSuppliers] AS s ON q.SupplierID = s.SupplierID)
     LEFT JOIN [en].[qryLocBanks] AS k ON q.BankID = k.BankID;
GO
CREATE OR ALTER VIEW [en].[JournalLinesQuery] AS
-- قيود اليومية خلال فترة بأسطرها
SELECT e.EntryID, e.EntryNumber, e.EntryDate, e.SourceType, t.TypeName, e.SourceID, e.SourceNumber,
       e.Description, l.LineNumber, l.AccountCode, a.AccountName, l.LineText, l.Debit, l.Credit
FROM (([dbo].[JournalEntries] AS e INNER JOIN [en].[qryLocJournalSourceTypes] AS t ON e.SourceType = t.SourceType)
      INNER JOIN [dbo].[JournalLines] AS l ON e.EntryID = l.EntryID)
     INNER JOIN [en].[qryLocAccounts] AS a ON l.AccountCode = a.AccountCode CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE e.EntryDate >= qp.[qp_PeriodStart] AND e.EntryDate < qp.[qp_PeriodEnd];
GO
CREATE OR ALTER VIEW [en].[qryJournalEntryPrint] AS
-- بيانات طباعة قيد
SELECT e.EntryID, e.EntryNumber, e.EntryDate, t.TypeName, e.SourceNumber, e.Description, e.TotalDebit,
       l.LineNumber, l.AccountCode, a.AccountName, l.LineText, l.Debit, l.Credit
FROM (([dbo].[JournalEntries] AS e INNER JOIN [en].[qryLocJournalSourceTypes] AS t ON e.SourceType = t.SourceType)
      INNER JOIN [dbo].[JournalLines] AS l ON e.EntryID = l.EntryID)
     INNER JOIN [en].[qryLocAccounts] AS a ON l.AccountCode = a.AccountCode;
GO
CREATE OR ALTER VIEW [en].[qryTrialBefore] AS
-- مجموع الحسابات قبل الفترة
SELECT l.AccountCode, Sum(l.Debit) AS DebitBefore, Sum(l.Credit) AS CreditBefore
FROM [dbo].[JournalEntries] AS e INNER JOIN [dbo].[JournalLines] AS l ON e.EntryID = l.EntryID CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE e.EntryDate < qp.[qp_PeriodStart]
GROUP BY l.AccountCode;
GO
CREATE OR ALTER VIEW [en].[qryTrialPeriod] AS
-- حركة الحسابات خلال الفترة
SELECT l.AccountCode, Sum(l.Debit) AS SumDebit, Sum(l.Credit) AS SumCredit
FROM [dbo].[JournalEntries] AS e INNER JOIN [dbo].[JournalLines] AS l ON e.EntryID = l.EntryID CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE e.EntryDate >= qp.[qp_PeriodStart] AND e.EntryDate < qp.[qp_PeriodEnd]
GROUP BY l.AccountCode;
GO
CREATE OR ALTER VIEW [en].[TrialBalanceQuery] AS
-- ميزان المراجعة: رصيد أول المدة وحركة الفترة والرصيد الختامي (المدين موجب)
SELECT a.AccountCode, a.AccountName, a.AccountType,
       CAST(COALESCE(b.DebitBefore, 0) AS MONEY) - CAST(COALESCE(b.CreditBefore, 0) AS MONEY) AS OpeningBalance,
       CAST(COALESCE(p.SumDebit, 0) AS MONEY) AS PeriodDebit, CAST(COALESCE(p.SumCredit, 0) AS MONEY) AS PeriodCredit,
       CAST(COALESCE(b.DebitBefore, 0) AS MONEY) - CAST(COALESCE(b.CreditBefore, 0) AS MONEY) + CAST(COALESCE(p.SumDebit, 0) AS MONEY) - CAST(COALESCE(p.SumCredit, 0) AS MONEY) AS ClosingBalance
FROM ([en].[qryLocAccounts] AS a LEFT JOIN [en].[qryTrialBefore] AS b ON a.AccountCode = b.AccountCode)
     LEFT JOIN [en].[qryTrialPeriod] AS p ON a.AccountCode = p.AccountCode
WHERE b.AccountCode Is Not Null OR p.AccountCode Is Not Null;
GO
CREATE OR ALTER VIEW [en].[qryStatementBefore] AS
-- رصيد الحساب المختار (مع حساباته التابعة) قبل بداية الفترة
SELECT CAST(COALESCE(Sum(o.Debit), 0) AS MONEY) - CAST(COALESCE(Sum(o.Credit), 0) AS MONEY) AS SumBefore
FROM ([dbo].[JournalLines] AS o INNER JOIN [dbo].[JournalEntries] AS f ON o.EntryID = f.EntryID)
     INNER JOIN [dbo].[Accounts] AS b ON o.AccountCode = b.AccountCode CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE (b.Level1Code = qp.[qp_AccountCode] OR b.Level2Code = qp.[qp_AccountCode] OR b.Level3Code = qp.[qp_AccountCode] OR b.Level4Code = qp.[qp_AccountCode] OR b.Level5Code = qp.[qp_AccountCode]) AND f.EntryDate < qp.[qp_PeriodStart];
GO
CREATE OR ALTER VIEW [en].[AccountStatementQuery] AS
-- كشف حساب لفترة: رصيد أول المدة ثم كل سطر قيد (الحساب الرئيسي يشمل حساباته التابعة)
SELECT 1 AS SortKey, s.AccountCode AS StatementAccount, s.AccountName AS StatementName, e.EntryDate AS LineDate,
       e.EntryNumber AS EntryNo, e.EntryID AS EntryRef, k.TypeName AS KindName, e.SourceNumber AS DocNo,
       e.Description AS Details, a.AccountCode AS SubCode, a.AccountName AS SubName, l.Debit AS LineDebit,
       l.Credit AS LineCredit
FROM ((([dbo].[JournalLines] AS l INNER JOIN [dbo].[JournalEntries] AS e ON l.EntryID = e.EntryID)
      INNER JOIN [en].[qryLocAccounts] AS a ON l.AccountCode = a.AccountCode)
     INNER JOIN [en].[qryLocJournalSourceTypes] AS k ON e.SourceType = k.SourceType), [en].[qryLocAccounts] AS s CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE s.AccountCode = qp.[qp_AccountCode] AND (a.Level1Code = qp.[qp_AccountCode] OR a.Level2Code = qp.[qp_AccountCode] OR a.Level3Code = qp.[qp_AccountCode] OR a.Level4Code = qp.[qp_AccountCode] OR a.Level5Code = qp.[qp_AccountCode]) AND e.EntryDate >= qp.[qp_PeriodStart] AND e.EntryDate < qp.[qp_PeriodEnd]
UNION ALL
SELECT 0, s.AccountCode, s.AccountName, (SELECT p.[qp_PeriodStart] FROM [dbo].[QueryParamsNow] AS p), N'-', 0, N'Opening balance', Null, Null, Null, Null,
       IIF(x.SumBefore > 0, x.SumBefore, 0), IIF(x.SumBefore < 0, -x.SumBefore, 0)
FROM [en].[qryLocAccounts] AS s, [en].[qryStatementBefore] AS x CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE s.AccountCode = qp.[qp_AccountCode];
GO
CREATE OR ALTER VIEW [en].[GeneralLedgerQuery] AS
-- دفتر الأستاذ لفترة: لكل حساب فرعي رصيد أول المدة ثم أسطر قيوده (0 = كل الحسابات)
SELECT 1 AS SortKey, a.TreeKey AS AccountKey, a.AccountCode AS LedgerCode, a.AccountName AS LedgerName,
       e.EntryDate AS LineDate, e.EntryNumber AS EntryNo, e.EntryID AS EntryRef, k.TypeName AS KindName,
       e.SourceNumber AS DocNo, e.Description AS Details, l.Debit AS LineDebit, l.Credit AS LineCredit
FROM (([dbo].[JournalLines] AS l INNER JOIN [dbo].[JournalEntries] AS e ON l.EntryID = e.EntryID)
      INNER JOIN [en].[qryLocAccounts] AS a ON l.AccountCode = a.AccountCode)
     INNER JOIN [en].[qryLocJournalSourceTypes] AS k ON e.SourceType = k.SourceType CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE (qp.[qp_AccountCode] = 0 OR (a.Level1Code = qp.[qp_AccountCode] OR a.Level2Code = qp.[qp_AccountCode] OR a.Level3Code = qp.[qp_AccountCode] OR a.Level4Code = qp.[qp_AccountCode] OR a.Level5Code = qp.[qp_AccountCode])) AND e.EntryDate >= qp.[qp_PeriodStart] AND e.EntryDate < qp.[qp_PeriodEnd]
UNION ALL
SELECT 0, b.TreeKey, b.AccountCode, b.AccountName, (SELECT p.[qp_PeriodStart] FROM [dbo].[QueryParamsNow] AS p), N'-', 0, N'Opening balance', Null, Null,
       IIF(t.OpeningBalance > 0, t.OpeningBalance, 0), IIF(t.OpeningBalance < 0, -t.OpeningBalance, 0)
FROM [en].[TrialBalanceQuery] AS t INNER JOIN [en].[qryLocAccounts] AS b ON t.AccountCode = b.AccountCode CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE qp.[qp_AccountCode] = 0 OR (b.Level1Code = qp.[qp_AccountCode] OR b.Level2Code = qp.[qp_AccountCode] OR b.Level3Code = qp.[qp_AccountCode] OR b.Level4Code = qp.[qp_AccountCode] OR b.Level5Code = qp.[qp_AccountCode]);
GO
CREATE OR ALTER VIEW [en].[qryTreeRollup] AS
-- أرصدة ميزان المراجعة مجمّعة على كل مستوى من شجرة الحسابات
SELECT d.Level1Code AS TreeCode, Sum(t.OpeningBalance) AS SumOpening, Sum(t.PeriodDebit) AS SumDebit,
       Sum(t.PeriodCredit) AS SumCredit, Sum(t.ClosingBalance) AS SumClosing
FROM [en].[TrialBalanceQuery] AS t INNER JOIN [dbo].[Accounts] AS d ON t.AccountCode = d.AccountCode
WHERE d.Level1Code Is Not Null
GROUP BY d.Level1Code
UNION ALL
SELECT d.Level2Code AS TreeCode, Sum(t.OpeningBalance) AS SumOpening, Sum(t.PeriodDebit) AS SumDebit,
       Sum(t.PeriodCredit) AS SumCredit, Sum(t.ClosingBalance) AS SumClosing
FROM [en].[TrialBalanceQuery] AS t INNER JOIN [dbo].[Accounts] AS d ON t.AccountCode = d.AccountCode
WHERE d.Level2Code Is Not Null
GROUP BY d.Level2Code
UNION ALL
SELECT d.Level3Code AS TreeCode, Sum(t.OpeningBalance) AS SumOpening, Sum(t.PeriodDebit) AS SumDebit,
       Sum(t.PeriodCredit) AS SumCredit, Sum(t.ClosingBalance) AS SumClosing
FROM [en].[TrialBalanceQuery] AS t INNER JOIN [dbo].[Accounts] AS d ON t.AccountCode = d.AccountCode
WHERE d.Level3Code Is Not Null
GROUP BY d.Level3Code
UNION ALL
SELECT d.Level4Code AS TreeCode, Sum(t.OpeningBalance) AS SumOpening, Sum(t.PeriodDebit) AS SumDebit,
       Sum(t.PeriodCredit) AS SumCredit, Sum(t.ClosingBalance) AS SumClosing
FROM [en].[TrialBalanceQuery] AS t INNER JOIN [dbo].[Accounts] AS d ON t.AccountCode = d.AccountCode
WHERE d.Level4Code Is Not Null
GROUP BY d.Level4Code
UNION ALL
SELECT d.Level5Code AS TreeCode, Sum(t.OpeningBalance) AS SumOpening, Sum(t.PeriodDebit) AS SumDebit,
       Sum(t.PeriodCredit) AS SumCredit, Sum(t.ClosingBalance) AS SumClosing
FROM [en].[TrialBalanceQuery] AS t INNER JOIN [dbo].[Accounts] AS d ON t.AccountCode = d.AccountCode
WHERE d.Level5Code Is Not Null
GROUP BY d.Level5Code;
GO
CREATE OR ALTER VIEW [en].[TrialBalanceTreeQuery] AS
-- ميزان المراجعة بالمستويات: كل حساب رئيسي بمجموع حساباته التابعة
SELECT a.AccountCode, a.AccountName, IIF(a.AccountType = N'ASSET', N'Assets', IIF(a.AccountType = N'LIABILITY', N'Liabilities', IIF(a.AccountType = N'EQUITY', N'Equity', IIF(a.AccountType = N'REVENUE', N'Revenue', N'Expenses')))) AS TypeName, a.AccountLevel, a.TreeKey, a.IsPosting,
       r.SumOpening AS OpeningBalance, r.SumDebit AS PeriodDebit, r.SumCredit AS PeriodCredit,
       r.SumClosing AS ClosingBalance
FROM [en].[qryLocAccounts] AS a INNER JOIN [en].[qryTreeRollup] AS r ON a.AccountCode = r.TreeCode;
GO
CREATE OR ALTER VIEW [en].[qryIncomeMoves] AS
-- حركة الحسابات في الفترة بدون قيود إقفال السنة
SELECT l.AccountCode, Sum(l.Debit) AS SumDebit, Sum(l.Credit) AS SumCredit
FROM [dbo].[JournalEntries] AS e INNER JOIN [dbo].[JournalLines] AS l ON e.EntryID = l.EntryID CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE e.EntryDate >= qp.[qp_PeriodStart] AND e.EntryDate < qp.[qp_PeriodEnd] AND e.SourceType <> N'YEAR_CLOSE'
GROUP BY l.AccountCode;
GO
CREATE OR ALTER VIEW [en].[qryCompareMoves] AS
-- حركة الحسابات في فترة المقارنة بدون قيود إقفال السنة
SELECT l.AccountCode, Sum(l.Debit) AS SumDebit, Sum(l.Credit) AS SumCredit
FROM [dbo].[JournalEntries] AS e INNER JOIN [dbo].[JournalLines] AS l ON e.EntryID = l.EntryID CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE e.EntryDate >= qp.[qp_CompareStart] AND e.EntryDate < qp.[qp_CompareEnd] AND e.SourceType <> N'YEAR_CLOSE'
GROUP BY l.AccountCode;
GO
CREATE OR ALTER VIEW [en].[qryIncomeAccounts] AS
-- حسابات قائمة الدخل: صافي حركة كل حساب إيرادات أو مصروفات في الفترة وفترة المقارنة
SELECT a.AccountCode, a.AccountName, a.TreeKey,
       IIF(a.Level2Code = 41, 1, IIF(a.Level2Code = 51, 2, IIF(a.Level2Code = 52, 3, IIF(a.AccountType = N'REVENUE', 4, 5)))) AS SectionNo,
       IIF(a.AccountType = N'REVENUE', 1, -1) * (CAST(COALESCE(c.SumCredit, 0) AS MONEY) - CAST(COALESCE(c.SumDebit, 0) AS MONEY)) AS CurrentAmount,
       IIF(a.AccountType = N'REVENUE', 1, -1) * (CAST(COALESCE(p.SumCredit, 0) AS MONEY) - CAST(COALESCE(p.SumDebit, 0) AS MONEY)) AS PriorAmount
FROM ([en].[qryLocAccounts] AS a LEFT JOIN [en].[qryIncomeMoves] AS c ON a.AccountCode = c.AccountCode)
     LEFT JOIN [en].[qryCompareMoves] AS p ON a.AccountCode = p.AccountCode
WHERE a.AccountType IN (N'REVENUE', N'EXPENSE') AND (c.AccountCode Is Not Null OR p.AccountCode Is Not Null);
GO
CREATE OR ALTER VIEW [en].[IncomeStatementQuery] AS
-- قائمة الدخل: الإيرادات والتكاليف والمصروفات ومجمل وصافي الربح، مع فترة المقارنة
SELECT q.SectionNo * 10 + 1 AS Block, q.TreeKey AS AccountKey, N'A' AS RowKind, q.AccountName AS Caption,
       q.AccountCode AS LineAccount, q.CurrentAmount AS CurrentValue, q.PriorAmount AS PriorValue
FROM [en].[qryIncomeAccounts] AS q
UNION ALL
SELECT 10, N'', N'H', N'Operating revenue', Null, Null, Null
FROM [dbo].[Settings] AS z WHERE z.SettingID = 1
UNION ALL
SELECT 12, N'', N'T', N'Net operating revenue', Null, CAST(COALESCE(Sum(IIF(q.SectionNo = 1, 1 * q.CurrentAmount, 0)), 0) AS MONEY), CAST(COALESCE(Sum(IIF(q.SectionNo = 1, 1 * q.PriorAmount, 0)), 0) AS MONEY)
FROM [en].[qryIncomeAccounts] AS q
UNION ALL
SELECT 20, N'', N'H', N'Cost of sales', Null, Null, Null
FROM [dbo].[Settings] AS z WHERE z.SettingID = 1
UNION ALL
SELECT 22, N'', N'T', N'Total cost of sales', Null, CAST(COALESCE(Sum(IIF(q.SectionNo = 2, 1 * q.CurrentAmount, 0)), 0) AS MONEY), CAST(COALESCE(Sum(IIF(q.SectionNo = 2, 1 * q.PriorAmount, 0)), 0) AS MONEY)
FROM [en].[qryIncomeAccounts] AS q
UNION ALL
SELECT 30, N'', N'H', N'Operating and administrative expenses', Null, Null, Null
FROM [dbo].[Settings] AS z WHERE z.SettingID = 1
UNION ALL
SELECT 32, N'', N'T', N'Total operating and administrative expenses', Null, CAST(COALESCE(Sum(IIF(q.SectionNo = 3, 1 * q.CurrentAmount, 0)), 0) AS MONEY), CAST(COALESCE(Sum(IIF(q.SectionNo = 3, 1 * q.PriorAmount, 0)), 0) AS MONEY)
FROM [en].[qryIncomeAccounts] AS q
UNION ALL
SELECT 40, N'', N'H', N'Other revenue', Null, Null, Null
FROM [dbo].[Settings] AS z WHERE z.SettingID = 1
UNION ALL
SELECT 42, N'', N'T', N'Total other revenue', Null, CAST(COALESCE(Sum(IIF(q.SectionNo = 4, 1 * q.CurrentAmount, 0)), 0) AS MONEY), CAST(COALESCE(Sum(IIF(q.SectionNo = 4, 1 * q.PriorAmount, 0)), 0) AS MONEY)
FROM [en].[qryIncomeAccounts] AS q
UNION ALL
SELECT 50, N'', N'H', N'Other expenses', Null, Null, Null
FROM [dbo].[Settings] AS z WHERE z.SettingID = 1
UNION ALL
SELECT 52, N'', N'T', N'Total other expenses', Null, CAST(COALESCE(Sum(IIF(q.SectionNo = 5, 1 * q.CurrentAmount, 0)), 0) AS MONEY), CAST(COALESCE(Sum(IIF(q.SectionNo = 5, 1 * q.PriorAmount, 0)), 0) AS MONEY)
FROM [en].[qryIncomeAccounts] AS q
UNION ALL
SELECT 25, N'', N'R', N'Gross profit', Null, CAST(COALESCE(Sum(IIF(q.SectionNo = 1, 1 * q.CurrentAmount, 0) + IIF(q.SectionNo = 2, -1 * q.CurrentAmount, 0)), 0) AS MONEY), CAST(COALESCE(Sum(IIF(q.SectionNo = 1, 1 * q.PriorAmount, 0) + IIF(q.SectionNo = 2, -1 * q.PriorAmount, 0)), 0) AS MONEY)
FROM [en].[qryIncomeAccounts] AS q
UNION ALL
SELECT 35, N'', N'R', N'Operating profit', Null, CAST(COALESCE(Sum(IIF(q.SectionNo = 1, 1 * q.CurrentAmount, 0) + IIF(q.SectionNo = 2, -1 * q.CurrentAmount, 0) + IIF(q.SectionNo = 3, -1 * q.CurrentAmount, 0)), 0) AS MONEY), CAST(COALESCE(Sum(IIF(q.SectionNo = 1, 1 * q.PriorAmount, 0) + IIF(q.SectionNo = 2, -1 * q.PriorAmount, 0) + IIF(q.SectionNo = 3, -1 * q.PriorAmount, 0)), 0) AS MONEY)
FROM [en].[qryIncomeAccounts] AS q
UNION ALL
SELECT 60, N'', N'R', N'Net profit (loss)', Null, CAST(COALESCE(Sum(IIF(q.SectionNo = 1, 1 * q.CurrentAmount, 0) + IIF(q.SectionNo = 2, -1 * q.CurrentAmount, 0) + IIF(q.SectionNo = 3, -1 * q.CurrentAmount, 0) + IIF(q.SectionNo = 4, 1 * q.CurrentAmount, 0) + IIF(q.SectionNo = 5, -1 * q.CurrentAmount, 0)), 0) AS MONEY), CAST(COALESCE(Sum(IIF(q.SectionNo = 1, 1 * q.PriorAmount, 0) + IIF(q.SectionNo = 2, -1 * q.PriorAmount, 0) + IIF(q.SectionNo = 3, -1 * q.PriorAmount, 0) + IIF(q.SectionNo = 4, 1 * q.PriorAmount, 0) + IIF(q.SectionNo = 5, -1 * q.PriorAmount, 0)), 0) AS MONEY)
FROM [en].[qryIncomeAccounts] AS q;
GO
CREATE OR ALTER VIEW [en].[qryCenterMoves] AS
-- صافي حركة كل حساب إيرادات أو مصروفات لكل مركز تكلفة في الفترة
SELECT IIF(l.CostCenterID Is Null, 0, l.CostCenterID) AS CenterKey, l.AccountCode, a.AccountName, a.TreeKey,
       a.Level2Code, IIF(a.AccountType = N'REVENUE', 1, -1) * (Sum(l.Credit) - Sum(l.Debit)) AS CenterAmount
FROM ([dbo].[JournalEntries] AS e INNER JOIN [dbo].[JournalLines] AS l ON e.EntryID = l.EntryID)
     INNER JOIN [en].[qryLocAccounts] AS a ON l.AccountCode = a.AccountCode CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE e.EntryDate >= qp.[qp_PeriodStart] AND e.EntryDate < qp.[qp_PeriodEnd] AND e.SourceType <> N'YEAR_CLOSE' AND a.AccountType IN (N'REVENUE', N'EXPENSE')
GROUP BY IIF(l.CostCenterID Is Null, 0, l.CostCenterID), l.AccountCode, a.AccountName, a.TreeKey, a.Level2Code,
         a.AccountType;
GO
CREATE OR ALTER VIEW [en].[qryCenterNames] AS
-- مراكز التكلفة ومعها «غير موزع»
SELECT CostCenterID AS CenterKey, CenterCode, CenterName
FROM [en].[qryLocCostCenters]
UNION ALL
SELECT 0, N'-', N'Not allocated'
FROM [dbo].[Settings] AS z
WHERE z.SettingID = 1;
GO
CREATE OR ALTER VIEW [en].[qryCenterSums] AS
-- الإيرادات وتكلفة المبيعات والمصروفات لكل مركز تكلفة
SELECT CenterKey, Sum(IIF(Level2Code = 41 Or Level2Code = 42, CenterAmount, 0)) AS SumRevenue,
       Sum(IIF(Level2Code = 51, CenterAmount, 0)) AS SumCostOfSales,
       Sum(IIF(Level2Code = 52 Or Level2Code = 53, CenterAmount, 0)) AS SumExpenses
FROM [en].[qryCenterMoves]
GROUP BY CenterKey;
GO
CREATE OR ALTER VIEW [en].[CostCenterProfitQuery] AS
-- قائمة الدخل لكل مركز تكلفة: الإيرادات، تكلفة المبيعات، مجمل الربح، المصروفات، صافي الربح
SELECT n.CenterKey, n.CenterCode, n.CenterName, s.SumRevenue AS Revenue, s.SumCostOfSales AS CostOfSales,
       s.SumRevenue - s.SumCostOfSales AS GrossProfit, s.SumExpenses AS Expenses,
       s.SumRevenue - s.SumCostOfSales - s.SumExpenses AS NetProfit
FROM [en].[qryCenterNames] AS n INNER JOIN [en].[qryCenterSums] AS s ON n.CenterKey = s.CenterKey;
GO
CREATE OR ALTER VIEW [en].[CostCenterAccountsQuery] AS
-- إيرادات ومصروفات كل مركز تكلفة بالحسابات
SELECT n.CenterKey, n.CenterName, m.AccountCode, m.AccountName, m.TreeKey,
       IIF(m.Level2Code = 41 Or m.Level2Code = 42, N'Revenue', IIF(m.Level2Code = 51, N'Cost of sales', N'Expenses'))
           AS SectionName, m.CenterAmount
FROM [en].[qryCenterNames] AS n INNER JOIN [en].[qryCenterMoves] AS m ON n.CenterKey = m.CenterKey;
GO
CREATE OR ALTER VIEW [en].[qryBudgetMonths] AS
-- أشهر الموازنة: سطر لكل شهر من كل سطر موازنة
SELECT l.BudgetLineID, h.BudgetYear, 1 AS MonthNo, h.BudgetYear * 100 + 1 AS MonthKey, l.M1 AS PlanAmount
FROM [dbo].[BudgetLines] AS l INNER JOIN [dbo].[Budgets] AS h ON l.BudgetID = h.BudgetID
UNION ALL
SELECT l.BudgetLineID, h.BudgetYear, 2, h.BudgetYear * 100 + 2, l.M2
FROM [dbo].[BudgetLines] AS l INNER JOIN [dbo].[Budgets] AS h ON l.BudgetID = h.BudgetID
UNION ALL
SELECT l.BudgetLineID, h.BudgetYear, 3, h.BudgetYear * 100 + 3, l.M3
FROM [dbo].[BudgetLines] AS l INNER JOIN [dbo].[Budgets] AS h ON l.BudgetID = h.BudgetID
UNION ALL
SELECT l.BudgetLineID, h.BudgetYear, 4, h.BudgetYear * 100 + 4, l.M4
FROM [dbo].[BudgetLines] AS l INNER JOIN [dbo].[Budgets] AS h ON l.BudgetID = h.BudgetID
UNION ALL
SELECT l.BudgetLineID, h.BudgetYear, 5, h.BudgetYear * 100 + 5, l.M5
FROM [dbo].[BudgetLines] AS l INNER JOIN [dbo].[Budgets] AS h ON l.BudgetID = h.BudgetID
UNION ALL
SELECT l.BudgetLineID, h.BudgetYear, 6, h.BudgetYear * 100 + 6, l.M6
FROM [dbo].[BudgetLines] AS l INNER JOIN [dbo].[Budgets] AS h ON l.BudgetID = h.BudgetID
UNION ALL
SELECT l.BudgetLineID, h.BudgetYear, 7, h.BudgetYear * 100 + 7, l.M7
FROM [dbo].[BudgetLines] AS l INNER JOIN [dbo].[Budgets] AS h ON l.BudgetID = h.BudgetID
UNION ALL
SELECT l.BudgetLineID, h.BudgetYear, 8, h.BudgetYear * 100 + 8, l.M8
FROM [dbo].[BudgetLines] AS l INNER JOIN [dbo].[Budgets] AS h ON l.BudgetID = h.BudgetID
UNION ALL
SELECT l.BudgetLineID, h.BudgetYear, 9, h.BudgetYear * 100 + 9, l.M9
FROM [dbo].[BudgetLines] AS l INNER JOIN [dbo].[Budgets] AS h ON l.BudgetID = h.BudgetID
UNION ALL
SELECT l.BudgetLineID, h.BudgetYear, 10, h.BudgetYear * 100 + 10, l.M10
FROM [dbo].[BudgetLines] AS l INNER JOIN [dbo].[Budgets] AS h ON l.BudgetID = h.BudgetID
UNION ALL
SELECT l.BudgetLineID, h.BudgetYear, 11, h.BudgetYear * 100 + 11, l.M11
FROM [dbo].[BudgetLines] AS l INNER JOIN [dbo].[Budgets] AS h ON l.BudgetID = h.BudgetID
UNION ALL
SELECT l.BudgetLineID, h.BudgetYear, 12, h.BudgetYear * 100 + 12, l.M12
FROM [dbo].[BudgetLines] AS l INNER JOIN [dbo].[Budgets] AS h ON l.BudgetID = h.BudgetID;
GO
CREATE OR ALTER VIEW [en].[qryBudgetPlanned] AS
-- مبلغ الموازنة لكل سطر في أشهر الفترة
SELECT BudgetLineID, Sum(PlanAmount) AS SumPlan
FROM [en].[qryBudgetMonths] CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE BudgetYear = YEAR(qp.[qp_PeriodStart]) AND MonthKey >= YEAR(qp.[qp_PeriodStart]) * 100 + MONTH(qp.[qp_PeriodStart])
      AND MonthKey <= YEAR(DATEADD(day, -1, qp.[qp_PeriodEnd])) * 100 + MONTH(DATEADD(day, -1, qp.[qp_PeriodEnd]))
GROUP BY BudgetLineID;
GO
CREATE OR ALTER VIEW [en].[qryBudgetActual] AS
-- الفعلي لكل سطر موازنة في الفترة من القيود
SELECT b.BudgetLineID, Sum(IIF(a.AccountType = N'REVENUE', l.Credit - l.Debit, l.Debit - l.Credit)) AS SumActual
FROM [dbo].[Budgets] AS h, [dbo].[BudgetLines] AS b, [dbo].[Accounts] AS a, [dbo].[JournalEntries] AS e, [dbo].[JournalLines] AS l, [dbo].[Accounts] AS d CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE h.BudgetYear = YEAR(qp.[qp_PeriodStart]) AND b.BudgetID = h.BudgetID AND a.AccountCode = b.AccountCode
      AND l.EntryID = e.EntryID AND d.AccountCode = l.AccountCode AND (d.Level1Code = b.AccountCode OR d.Level2Code = b.AccountCode OR d.Level3Code = b.AccountCode OR d.Level4Code = b.AccountCode OR d.Level5Code = b.AccountCode)
      AND (b.CostCenterID Is Null OR l.CostCenterID = b.CostCenterID)
      AND e.EntryDate >= qp.[qp_PeriodStart] AND e.EntryDate < qp.[qp_PeriodEnd] AND e.SourceType <> N'YEAR_CLOSE'
GROUP BY b.BudgetLineID;
GO
CREATE OR ALTER VIEW [en].[BudgetVsActualQuery] AS
-- الموازنة مقابل الفعلي في الفترة: الانحراف ونسبته، وهل هو ملائم
SELECT b.BudgetLineID, b.AccountCode, a.AccountName, a.TreeKey, a.AccountType,
       IIF(a.AccountType = N'REVENUE', N'Revenue', N'Expenses') AS SectionName,
       IIF(c.CenterName Is Null, N'All centers', c.CenterName) AS BudgetCenter,
       CAST(COALESCE(p.SumPlan, 0) AS MONEY) AS BudgetAmount, CAST(COALESCE(x.SumActual, 0) AS MONEY) AS ActualAmount,
       CAST(COALESCE(x.SumActual, 0) AS MONEY) - CAST(COALESCE(p.SumPlan, 0) AS MONEY) AS Variance,
       IIF(CAST(COALESCE(p.SumPlan, 0) AS MONEY) = 0, Null, (CAST(COALESCE(x.SumActual, 0) AS MONEY) - CAST(COALESCE(p.SumPlan, 0) AS MONEY)) * 1e0 / CAST(COALESCE(p.SumPlan, 0) AS MONEY)) AS VariancePct,
       IIF(CAST(COALESCE(x.SumActual, 0) AS MONEY) = CAST(COALESCE(p.SumPlan, 0) AS MONEY), N'Matched', IIF(IIF(a.AccountType = N'REVENUE', 1, 0) =
           IIF(CAST(COALESCE(x.SumActual, 0) AS MONEY) > CAST(COALESCE(p.SumPlan, 0) AS MONEY), 1, 0), N'Suitable', N'Unsuitable')) AS VarianceNote
FROM (((([dbo].[Budgets] AS h INNER JOIN [dbo].[BudgetLines] AS b ON h.BudgetID = b.BudgetID)
       INNER JOIN [en].[qryLocAccounts] AS a ON b.AccountCode = a.AccountCode)
      LEFT JOIN [en].[qryLocCostCenters] AS c ON b.CostCenterID = c.CostCenterID)
     LEFT JOIN [en].[qryBudgetPlanned] AS p ON b.BudgetLineID = p.BudgetLineID)
     LEFT JOIN [en].[qryBudgetActual] AS x ON b.BudgetLineID = x.BudgetLineID CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE h.BudgetYear = YEAR(qp.[qp_PeriodStart]);
GO
CREATE OR ALTER VIEW [en].[qryBalanceAt] AS
-- رصيد كل حساب في نهاية الفترة (مدين موجب)
SELECT l.AccountCode, Sum(l.Debit) - Sum(l.Credit) AS NetAt
FROM [dbo].[JournalEntries] AS e INNER JOIN [dbo].[JournalLines] AS l ON e.EntryID = l.EntryID CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE e.EntryDate < qp.[qp_PeriodEnd]
GROUP BY l.AccountCode;
GO
CREATE OR ALTER VIEW [en].[qryBalanceCompare] AS
-- رصيد كل حساب في نهاية فترة المقارنة (مدين موجب)
SELECT l.AccountCode, Sum(l.Debit) - Sum(l.Credit) AS NetCompare
FROM [dbo].[JournalEntries] AS e INNER JOIN [dbo].[JournalLines] AS l ON e.EntryID = l.EntryID CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE e.EntryDate < qp.[qp_CompareEnd]
GROUP BY l.AccountCode;
GO
CREATE OR ALTER VIEW [en].[qryBalanceAccounts] AS
-- حسابات الميزانية: رصيد كل حساب أصول أو خصوم أو حقوق ملكية (بطبيعته موجب)
SELECT a.AccountCode, a.AccountName, a.TreeKey, a.Level1Code, a.Level2Code,
       IIF(a.AccountType = N'ASSET', 1, -1) * CAST(COALESCE(b.NetAt, 0) AS MONEY) AS CurrentAmount,
       IIF(a.AccountType = N'ASSET', 1, -1) * CAST(COALESCE(c.NetCompare, 0) AS MONEY) AS PriorAmount
FROM ([en].[qryLocAccounts] AS a LEFT JOIN [en].[qryBalanceAt] AS b ON a.AccountCode = b.AccountCode)
     LEFT JOIN [en].[qryBalanceCompare] AS c ON a.AccountCode = c.AccountCode
WHERE a.AccountType IN (N'ASSET', N'LIABILITY', N'EQUITY') AND (CAST(COALESCE(b.NetAt, 0) AS MONEY) <> 0 OR CAST(COALESCE(c.NetCompare, 0) AS MONEY) <> 0);
GO
CREATE OR ALTER VIEW [en].[qryProfitAt] AS
-- صافي ربح الفترات غير المقفلة حتى نهاية الفترة (مدين موجب)
SELECT CAST(COALESCE(Sum(b.NetAt), 0) AS MONEY) AS NetProfitSum
FROM [en].[qryBalanceAt] AS b INNER JOIN [dbo].[Accounts] AS a ON b.AccountCode = a.AccountCode
WHERE a.AccountType IN (N'REVENUE', N'EXPENSE');
GO
CREATE OR ALTER VIEW [en].[qryProfitCompare] AS
-- صافي ربح الفترات غير المقفلة حتى نهاية فترة المقارنة (مدين موجب)
SELECT CAST(COALESCE(Sum(c.NetCompare), 0) AS MONEY) AS NetCompareSum
FROM [en].[qryBalanceCompare] AS c INNER JOIN [dbo].[Accounts] AS a ON c.AccountCode = a.AccountCode
WHERE a.AccountType IN (N'REVENUE', N'EXPENSE');
GO
CREATE OR ALTER VIEW [en].[qryBalanceItems] AS
-- بنود الميزانية بمجموعاتها، ومعها صافي الربح غير المقفل في الأرباح المحتجزة (32)
SELECT q.Level1Code AS ClassNo, q.Level2Code AS GroupCode, q.CurrentAmount AS CurrentValue, q.PriorAmount AS PriorValue
FROM [en].[qryBalanceAccounts] AS q
UNION ALL
SELECT 3, 32, -x.NetProfitSum, -y.NetCompareSum
FROM [en].[qryProfitAt] AS x, [en].[qryProfitCompare] AS y;
GO
CREATE OR ALTER VIEW [en].[BalanceSheetQuery] AS
-- الميزانية العمومية في نهاية الفترة: الأصول = الخصوم + حقوق الملكية، مع فترة المقارنة
SELECT q.Level1Code AS ClassNo, g.TreeKey AS GroupKey, 1 AS Pos, q.TreeKey AS AccountKey, N'A' AS RowKind,
       q.AccountName AS Caption, q.AccountCode AS LineAccount, q.CurrentAmount AS CurrentValue,
       q.PriorAmount AS PriorValue
FROM [en].[qryBalanceAccounts] AS q INNER JOIN [en].[qryLocAccounts] AS g ON q.Level2Code = g.AccountCode
UNION ALL
SELECT 3, g.TreeKey, 1, N'Z', N'A', N'Net profit (loss) of the periods not closed', Null, -x.NetProfitSum, -y.NetCompareSum
FROM [en].[qryLocAccounts] AS g, [en].[qryProfitAt] AS x, [en].[qryProfitCompare] AS y
WHERE g.AccountCode = 32
UNION ALL
SELECT c.AccountCode, N'', 0, N'', N'C', c.AccountName, Null, Null, Null
FROM [en].[qryLocAccounts] AS c
WHERE c.AccountCode IN (1, 2, 3)
UNION ALL
SELECT g.Level1Code, g.TreeKey, 0, N'', N'G', g.AccountName, Null, Null, Null
FROM [en].[qryLocAccounts] AS g
WHERE g.AccountCode IN (SELECT GroupCode FROM [en].[qryBalanceItems])
UNION ALL
SELECT g.Level1Code, g.TreeKey, 2, N'', N'S', g.AccountName, Null, Sum(i.CurrentValue), Sum(i.PriorValue)
FROM [en].[qryLocAccounts] AS g INNER JOIN [en].[qryBalanceItems] AS i ON g.AccountCode = i.GroupCode
GROUP BY g.Level1Code, g.TreeKey, g.AccountName
UNION ALL
SELECT i.ClassNo, N'~', 9, N'', N'T', IIF(i.ClassNo = 1, N'Total assets', IIF(i.ClassNo = 2, N'Total liabilities', N'Total equity')), Null, Sum(i.CurrentValue), Sum(i.PriorValue)
FROM [en].[qryBalanceItems] AS i
GROUP BY i.ClassNo
UNION ALL
SELECT 4, N'', 9, N'', N'T', N'Total liabilities and equity', Null, CAST(COALESCE(Sum(i.CurrentValue), 0) AS MONEY), CAST(COALESCE(Sum(i.PriorValue), 0) AS MONEY)
FROM [en].[qryBalanceItems] AS i
WHERE i.ClassNo IN (2, 3);
GO
CREATE OR ALTER VIEW [en].[OpeningBalancesReportQuery] AS
-- أرصدة أول المدة في بداية يوم PeriodStart: الحسابات، والعملاء، والموردون، والمخزون بالكمية والقيمة (docs/54)
SELECT 1 AS SectionNo, N'Accounts' AS SectionName, CAST(a.AccountCode AS NVARCHAR(255)) AS ItemCode, a.AccountName AS ItemName,
       IIF(Sum(l.Debit) - Sum(l.Credit) > 0, Sum(l.Debit) - Sum(l.Credit), 0) AS DebitBalance,
       IIF(Sum(l.Debit) - Sum(l.Credit) < 0, Sum(l.Credit) - Sum(l.Debit), 0) AS CreditBalance, 0 AS ItemQty
FROM ([dbo].[JournalLines] AS l INNER JOIN [dbo].[JournalEntries] AS e ON l.EntryID = e.EntryID)
     INNER JOIN [en].[qryLocAccounts] AS a ON l.AccountCode = a.AccountCode CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE e.EntryDate < qp.[qp_PeriodStart]
GROUP BY a.AccountCode, a.AccountName
HAVING ROUND(Sum(l.Debit) - Sum(l.Credit), 2) <> 0
UNION ALL
SELECT 2, N'Customers', CAST(c.CustomerID AS NVARCHAR(255)), c.CustomerName,
       IIF(Sum(g.Debit) - Sum(g.Credit) > 0, Sum(g.Debit) - Sum(g.Credit), 0),
       IIF(Sum(g.Debit) - Sum(g.Credit) < 0, Sum(g.Credit) - Sum(g.Debit), 0), 0
FROM [en].[qryCustomerLedger] AS g INNER JOIN [en].[qryLocCustomers] AS c ON g.CustomerID = c.CustomerID CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE g.EntryDate < qp.[qp_PeriodStart]
GROUP BY c.CustomerID, c.CustomerName
HAVING ROUND(Sum(g.Debit) - Sum(g.Credit), 2) <> 0
UNION ALL
SELECT 3, N'Suppliers', CAST(s.SupplierID AS NVARCHAR(255)), s.SupplierName,
       IIF(Sum(g.Debit) - Sum(g.Credit) > 0, Sum(g.Debit) - Sum(g.Credit), 0),
       IIF(Sum(g.Debit) - Sum(g.Credit) < 0, Sum(g.Credit) - Sum(g.Debit), 0), 0
FROM [en].[qrySupplierLedger] AS g INNER JOIN [en].[qryLocSuppliers] AS s ON g.SupplierID = s.SupplierID CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE g.EntryDate < qp.[qp_PeriodStart]
GROUP BY s.SupplierID, s.SupplierName
HAVING ROUND(Sum(g.Debit) - Sum(g.Credit), 2) <> 0
UNION ALL
SELECT 4, N'Stock', p.ProductCode, p.ProductName, ROUND(Sum(t.Quantity * t.UnitCost), 2), 0, Sum(t.Quantity)
FROM [dbo].[InventoryTransactions] AS t INNER JOIN [dbo].[Products] AS p ON t.ProductID = p.ProductID CROSS JOIN [dbo].[QueryParamsNow] AS qp
WHERE t.TransactionDate < qp.[qp_PeriodStart]
GROUP BY p.ProductID, p.ProductCode, p.ProductName
HAVING ROUND(Sum(t.Quantity), 3) <> 0;
GO
CREATE OR ALTER VIEW [en].[AccountTreeQuery] AS
-- شجرة الحسابات: كل حساب بمستواه ونوعه وهل يقبل القيود
SELECT a.AccountCode, a.AccountName, IIF(a.AccountType = N'ASSET', N'Assets', IIF(a.AccountType = N'LIABILITY', N'Liabilities', IIF(a.AccountType = N'EQUITY', N'Equity', IIF(a.AccountType = N'REVENUE', N'Revenue', N'Expenses')))) AS TypeName, a.AccountLevel, a.TreeKey,
       a.ParentCode, IIF(a.IsPosting <> 0, N'Sub', N'Main') AS KindName, a.IsPosting, a.IsActive
FROM [en].[qryLocAccounts] AS a;
GO
CREATE OR ALTER VIEW [en].[qrySalesInvoiceLineTotals] AS
-- مجموع أسطر كل فاتورة بيع
SELECT SalesInvoiceID, Sum(LineTotal) AS LinesTotal
FROM [dbo].[SalesInvoiceDetails]
GROUP BY SalesInvoiceID;
GO
CREATE OR ALTER VIEW [en].[qryPurchaseInvoiceLineTotals] AS
-- مجموع أسطر كل فاتورة شراء
SELECT PurchaseInvoiceID, Sum(LineTotal) AS LinesTotal
FROM [dbo].[PurchaseInvoiceDetails]
GROUP BY PurchaseInvoiceID;
GO
CREATE OR ALTER VIEW [en].[qrySalesReturnedQty] AS
-- الكمية المرتجعة من كل سطر فاتورة بيع
SELECT SalesDetailID, Sum(Quantity) AS QtyReturned
FROM [dbo].[SalesReturnDetails]
GROUP BY SalesDetailID;
GO
CREATE OR ALTER VIEW [en].[qryPurchaseReturnedQty] AS
-- الكمية المرتجعة للمورد من كل سطر فاتورة شراء
SELECT PurchaseDetailID, Sum(Quantity) AS QtyReturned
FROM [dbo].[PurchaseReturnDetails]
GROUP BY PurchaseDetailID;
GO
CREATE OR ALTER VIEW [en].[IntegrityCheckQuery] AS
-- فحص سلامة البيانات: أي سطر هنا مشكلة يجب مراجعتها (النتيجة الفارغة = سليم)
SELECT N'STOCK_MISMATCH' AS IssueCode, N'The recorded quantity does not match the stock moves' AS IssueText,
       N'Products' AS SourceTable, p.ProductID AS RecordID,
       CAST(COALESCE(l.LedgerQty, 0) AS MONEY) AS ExpectedValue, CAST(p.CurrentQuantity AS MONEY) AS ActualValue
FROM [dbo].[Products] AS p LEFT JOIN [en].[qryProductLedger] AS l ON p.ProductID = l.ProductID
WHERE p.CurrentQuantity <> CAST(COALESCE(l.LedgerQty, 0) AS MONEY)
UNION ALL
SELECT N'NEGATIVE_STOCK', N'The product balance is negative', N'Products', p.ProductID, CAST(0 AS MONEY),
       CAST(p.CurrentQuantity AS MONEY)
FROM [dbo].[Products] AS p
WHERE p.CurrentQuantity < 0
UNION ALL
SELECT N'CUSTOMER_BALANCE', N'The recorded customer balance does not match the moves', N'Customers', b.CustomerID,
       CAST(b.Balance AS MONEY), CAST(b.CachedBalance AS MONEY)
FROM [en].[CustomerBalanceQuery] AS b
WHERE b.Balance <> b.CachedBalance
UNION ALL
SELECT N'SUPPLIER_BALANCE', N'The recorded supplier balance does not match the moves', N'Suppliers', b.SupplierID,
       CAST(b.Balance AS MONEY), CAST(b.CachedBalance AS MONEY)
FROM [en].[SupplierBalanceQuery] AS b
WHERE b.Balance <> b.CachedBalance
UNION ALL
SELECT N'SALE_TOTAL', N'The sales invoice total does not equal the sum of its lines', N'SalesInvoices',
       h.SalesInvoiceID, CAST(COALESCE(t.LinesTotal, 0) AS MONEY), CAST(h.TotalAmount AS MONEY)
FROM [dbo].[SalesInvoices] AS h LEFT JOIN [en].[qrySalesInvoiceLineTotals] AS t
     ON h.SalesInvoiceID = t.SalesInvoiceID
WHERE h.TotalAmount <> CAST(COALESCE(t.LinesTotal, 0) AS MONEY) OR t.SalesInvoiceID Is Null
UNION ALL
SELECT N'PURCHASE_TOTAL', N'The purchase invoice total does not equal the sum of its lines', N'PurchaseInvoices',
       h.PurchaseInvoiceID, CAST(COALESCE(t.LinesTotal, 0) AS MONEY), CAST(h.TotalAmount AS MONEY)
FROM [dbo].[PurchaseInvoices] AS h LEFT JOIN [en].[qryPurchaseInvoiceLineTotals] AS t
     ON h.PurchaseInvoiceID = t.PurchaseInvoiceID
WHERE h.TotalAmount <> CAST(COALESCE(t.LinesTotal, 0) AS MONEY) OR t.PurchaseInvoiceID Is Null
UNION ALL
SELECT N'CREDIT_NOT_ALLOWED', N'A credit sale to a customer not allowed to buy on credit', N'SalesInvoices',
       h.SalesInvoiceID, CAST(0 AS MONEY), CAST(h.RemainingAmount AS MONEY)
FROM [dbo].[SalesInvoices] AS h INNER JOIN [dbo].[Customers] AS c ON h.CustomerID = c.CustomerID
WHERE h.RemainingAmount > 0 AND c.AllowCredit = 0
UNION ALL
SELECT N'RETURN_CUSTOMER', N'The customer of the return differs from the customer of the original invoice', N'SalesReturns',
       r.SalesReturnID, CAST(h.CustomerID AS MONEY), CAST(r.CustomerID AS MONEY)
FROM [dbo].[SalesReturns] AS r INNER JOIN [dbo].[SalesInvoices] AS h ON r.SalesInvoiceID = h.SalesInvoiceID
WHERE r.CustomerID <> h.CustomerID
UNION ALL
SELECT N'RETURN_LINE_INVOICE', N'A return line from an invoice other than the invoice of the return', N'SalesReturnDetails',
       d.ReturnDetailID, CAST(r.SalesInvoiceID AS MONEY), CAST(o.SalesInvoiceID AS MONEY)
FROM ([dbo].[SalesReturnDetails] AS d INNER JOIN [dbo].[SalesReturns] AS r ON d.SalesReturnID = r.SalesReturnID)
     INNER JOIN [dbo].[SalesInvoiceDetails] AS o ON d.SalesDetailID = o.SalesDetailID
WHERE o.SalesInvoiceID <> r.SalesInvoiceID
UNION ALL
SELECT N'RETURN_LINE_PRODUCT', N'The product of the return line differs from the product of the original line', N'SalesReturnDetails',
       d.ReturnDetailID, CAST(o.ProductID AS MONEY), CAST(d.ProductID AS MONEY)
FROM [dbo].[SalesReturnDetails] AS d INNER JOIN [dbo].[SalesInvoiceDetails] AS o
     ON d.SalesDetailID = o.SalesDetailID
WHERE d.ProductID <> o.ProductID
UNION ALL
SELECT N'SALE_RETURN_QTY', N'The returned quantity is more than the quantity sold', N'SalesInvoiceDetails',
       o.SalesDetailID, CAST(o.Quantity AS MONEY), CAST(q.QtyReturned AS MONEY)
FROM [dbo].[SalesInvoiceDetails] AS o INNER JOIN [en].[qrySalesReturnedQty] AS q
     ON o.SalesDetailID = q.SalesDetailID
WHERE q.QtyReturned > o.Quantity
UNION ALL
SELECT N'PURCHASE_RETURN_QTY', N'The quantity returned to the supplier is more than the quantity bought', N'PurchaseInvoiceDetails',
       o.PurchaseDetailID, CAST(o.Quantity AS MONEY), CAST(q.QtyReturned AS MONEY)
FROM [dbo].[PurchaseInvoiceDetails] AS o INNER JOIN [en].[qryPurchaseReturnedQty] AS q
     ON o.PurchaseDetailID = q.PurchaseDetailID
WHERE q.QtyReturned > o.Quantity;
GO
CREATE OR ALTER VIEW [dbo].[QueriesVersion] AS
-- the version of these views: the front-end links to them only when it is its own
SELECT N'c5c7cf0c13e4' AS Version;
GO
